def _require(condition: bool, message: str) -> None:
    """Fail without pytest's expression rewriting or secret-bearing diffs."""
    if not condition:
        pytest.fail(message, pytrace=False)


def _database_name_from_url(value: str) -> str:
    parsed = urllib.parse.urlsplit(value)
    _require(parsed.scheme in {"postgres", "postgresql"}, "PG acceptance needs a PostgreSQL URL")
    name = urllib.parse.unquote(parsed.path.lstrip("/").split("/", 1)[0]).lower()
    _require(bool(name), "PG acceptance URL must name a database")
    _require(
        name.startswith(_DISPOSABLE_DATABASE_PREFIXES)
        and name not in {"postgres", "template0", "template1"},
        "refusing PG HTTP acceptance outside an explicitly disposable database",
    )
    return name


def _pg_epoch(connection: Any) -> int:
    """Read the same clock used by PostgreSQL lifecycle deadlines."""
    return int(
        connection.execute(
            "SELECT floor(extract(epoch FROM clock_timestamp()))::BIGINT"
        ).fetchone()[0]
    )


def _free_loopback_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.bind(("127.0.0.1", 0))
        return int(sock.getsockname()[1])


def _start_pg_backup_s3_fixture(
    access_key_id: str, control_token: str,
) -> tuple[subprocess.Popen[bytes], str]:
    node = shutil.which("node")
    if node is None:
        pytest.fail("two-node PG backup replication acceptance requires Node.js", pytrace=False)
    environment = {
        key: os.environ[key]
        for key in ("PATH", "HOME", "TMPDIR", "TMP", "TEMP", "XDG_CACHE_HOME")
        if key in os.environ
    }
    environment.update(
        {
            "ATERMIUS_FIXTURE_S3_BUCKET": PG_REPLICA_BUCKET,
            "ATERMIUS_FIXTURE_S3_ACCESS_KEY_ID": access_key_id,
            "ATERMIUS_FIXTURE_S3_CONTROL_TOKEN": control_token,
        }
    )
    process = subprocess.Popen(
        [node, str(ROOT / "integration" / "web" / "support" / "local_s3_fixture_server.cjs")],
        cwd=ROOT,
        env=environment,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        start_new_session=True,
    )
    try:
        assert process.stdout is not None
        with selectors.DefaultSelector() as selector:
            selector.register(process.stdout, selectors.EVENT_READ)
            if not selector.select(timeout=10):
                raise RuntimeError("loopback S3 fixture startup timed out")
        ready = json.loads(process.stdout.readline().decode("utf-8"))
        endpoint = ready.get("endpoint_url") if isinstance(ready, dict) else None
        parsed = urllib.parse.urlsplit(endpoint or "")
        _require(
            ready == {"ready": True, "endpoint_url": endpoint}
            and parsed.scheme == "http"
            and parsed.hostname == "127.0.0.1"
            and parsed.port is not None,
            "loopback S3 fixture did not report a private loopback endpoint",
        )
        return process, endpoint
    except Exception:
        _stop_acceptance_process(process)
        raise


def _local_private_ipv4() -> str:
    """Choose the assigned RFC1918 eth0 address used by disposable SSH fixtures."""
    ip_command = shutil.which("ip")
    if ip_command is None:
        pytest.skip("PG Relay acceptance requires iproute2 to discover the local target address")
    try:
        result = subprocess.run(
            [ip_command, "-o", "-4", "addr", "show", "dev", "eth0", "scope", "global"],
            check=False,
            capture_output=True,
            text=True,
            timeout=5,
        )
    except (OSError, subprocess.TimeoutExpired):
        pytest.skip("PG Relay acceptance could not discover the local target address")
    addresses = re.findall(r"\binet\s+(\d{1,3}(?:\.\d{1,3}){3})/", result.stdout)
    if result.returncode != 0 or not addresses:
        pytest.skip("PG Relay acceptance needs an assigned eth0 IPv4 target address")
    for address in addresses:
        try:
            parsed = socket.inet_aton(address)
        except OSError:
            continue
        first, second = parsed[0], parsed[1]
        if (
            first == 10
            or (first == 172 and 16 <= second <= 31)
            or (first == 192 and second == 168)
        ):
            return address
    pytest.skip("PG Relay acceptance requires an RFC1918 eth0 target address")


def _free_address_port(address: str) -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.bind((address, 0))
        return int(sock.getsockname()[1])


def _write_private(path: Path, raw: bytes) -> None:
    path.parent.mkdir(parents=True, mode=0o700, exist_ok=True)
    if os.name == "posix":
        os.chmod(path.parent, 0o700)
    path.write_bytes(raw)
    if os.name == "posix":
        os.chmod(path, 0o600)


def _with_application_name(pg_url: str, name: str) -> str:
    parsed = urllib.parse.urlsplit(pg_url)
    query = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True)
    query = [(key, value) for key, value in query if key != "application_name"]
    query.append(("application_name", name))
    query_text = urllib.parse.urlencode(query)
    if not parsed.netloc:
        # Preserve the libpq/SQLx Unix-socket form ``postgresql:///db``;
        # urllib.urlunsplit normalizes it to ``postgresql:/db``.
        value = f"{parsed.scheme}:///{parsed.path.lstrip('/')}"
        return f"{value}?{query_text}" if query_text else value
    return urllib.parse.urlunsplit(parsed._replace(query=query_text))


def _with_database_name(pg_url: str, database_name: str) -> str:
    parsed = urllib.parse.urlsplit(pg_url)
    path = "/" + urllib.parse.quote(database_name, safe="")
    if not parsed.netloc:
        # Preserve libpq's hostless Unix-socket URL form. urlunsplit would
        # collapse this to ``postgresql:/db``, which psycopg rejects.
        value = f"{parsed.scheme}:///{urllib.parse.quote(database_name, safe='')}"
        if parsed.query:
            value += "?" + parsed.query
        if parsed.fragment:
            value += "#" + parsed.fragment
        return value
    return urllib.parse.urlunsplit(parsed._replace(path=path))


def _error_code(response: HttpResponse) -> str | None:
    body = response.json()
    if not isinstance(body, dict):
        return None
    error = body.get("error")
    return error.get("code") if isinstance(error, dict) else None


def _pg_ws_read_exact(reader: Any, size: int) -> bytes:
    result = bytearray()
    while len(result) < size:
        chunk = reader.read(size - len(result))
        if not chunk:
            raise EOFError("notification WebSocket closed during a frame")
        result.extend(chunk)
    return bytes(result)


def _pg_ws_connect(
    base_url: str,
    origin: str,
    *,
    additional_origins: tuple[str, ...] = (),
) -> tuple[int, dict[str, str], socket.socket, Any, bytes]:
    parsed = urllib.parse.urlsplit(base_url)
    _require(parsed.scheme == "http", "PG notification WebSocket fixture expects loopback HTTP")
    host = parsed.hostname or "127.0.0.1"
    port = parsed.port or 80
    connection = socket.create_connection((host, port), timeout=6)
    connection.settimeout(6)
    reader = connection.makefile("rb")
    key = base64.b64encode(os.urandom(16)).decode("ascii")
    origins = "".join(f"Origin: {value}\r\n" for value in (origin, *additional_origins))
    request = (
        "GET /api/v1/notifications HTTP/1.1\r\n"
        f"Host: {parsed.netloc}\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        f"Sec-WebSocket-Key: {key}\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        f"{origins}"
        "\r\n"
    )
    connection.sendall(request.encode("ascii"))
    status_line = reader.readline().decode("latin-1").strip()
    try:
        status = int(status_line.split(" ", 2)[1])
    except (IndexError, ValueError):
        reader.close()
        connection.close()
        raise AssertionError("notification WebSocket returned an invalid status") from None
    headers: dict[str, str] = {}
    while True:
        line = reader.readline()
        if line in (b"\r\n", b"\n", b""):
            break
        name, separator, value = line.decode("latin-1").partition(":")
        if separator:
            headers[name.strip().lower()] = value.strip()
    body = b""
    if status != 101:
        if headers.get("transfer-encoding", "").lower() == "chunked":
            chunks = bytearray()
            while True:
                length = int(reader.readline().split(b";", 1)[0].strip(), 16)
                if length == 0:
                    while reader.readline() not in (b"\r\n", b"\n", b""):
                        pass
                    break
                chunks.extend(_pg_ws_read_exact(reader, length))
                _pg_ws_read_exact(reader, 2)
            body = bytes(chunks)
        else:
            length = int(headers.get("content-length", "0") or "0")
            if length:
                body = _pg_ws_read_exact(reader, length)
    else:
        expected_accept = base64.b64encode(
            hashlib.sha1(
                (key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode("ascii")
            ).digest()
        ).decode("ascii")
        _require(
            headers.get("sec-websocket-accept") == expected_accept,
            "notification WebSocket upgrade response was invalid",
        )
    return status, headers, connection, reader, body


def _pg_ws_send_frame(connection: socket.socket, opcode: int, payload: bytes) -> None:
    mask = os.urandom(4)
    size = len(payload)
    first = bytes((0x80 | opcode,))
    if size < 126:
        header = first + bytes((0x80 | size,))
    elif size <= 0xFFFF:
        header = first + bytes((0x80 | 126,)) + struct.pack("!H", size)
    else:
        header = first + bytes((0x80 | 127,)) + struct.pack("!Q", size)
    masked = bytes(value ^ mask[index % 4] for index, value in enumerate(payload))
    connection.sendall(header + mask + masked)


def _pg_ws_receive_frame(connection: socket.socket, reader: Any) -> tuple[int, bytes]:
    first, second = _pg_ws_read_exact(reader, 2)
    opcode = first & 0x0F
    size = second & 0x7F
    if size == 126:
        size = struct.unpack("!H", _pg_ws_read_exact(reader, 2))[0]
    elif size == 127:
        size = struct.unpack("!Q", _pg_ws_read_exact(reader, 8))[0]
    mask = _pg_ws_read_exact(reader, 4) if second & 0x80 else None
    payload = _pg_ws_read_exact(reader, size)
    if mask:
        payload = bytes(value ^ mask[index % 4] for index, value in enumerate(payload))
    if opcode == 0x9:
        _pg_ws_send_frame(connection, 0xA, payload)
        return _pg_ws_receive_frame(connection, reader)
    return opcode, payload


def _pg_ws_send_json(connection: socket.socket, payload: dict[str, Any]) -> None:
    _pg_ws_send_frame(
        connection,
        0x1,
        json.dumps(payload, separators=(",", ":")).encode("utf-8"),
    )


def _pg_ws_receive_json(connection: socket.socket, reader: Any) -> tuple[int, dict[str, Any]]:
    opcode, payload = _pg_ws_receive_frame(connection, reader)
    if opcode != 0x1:
        return opcode, {}
    decoded = json.loads(payload.decode("utf-8"))
    _require(isinstance(decoded, dict), "notification WebSocket text frame was not an object")
    return opcode, decoded


def _pg_ws_authenticate(
    base_url: str,
    origin: str,
    ticket: str,
) -> tuple[socket.socket, Any, dict[str, Any]]:
    status, _headers, connection, reader, _body = _pg_ws_connect(base_url, origin)
    _require(status == 101, "notification WebSocket did not upgrade on the peer node")
    _pg_ws_send_json(connection, {"type": "authenticate", "ticket": ticket})
    opcode, ready = _pg_ws_receive_json(connection, reader)
    _require(
        opcode == 0x1 and ready.get("type") == "ready",
        "cross-node notification ticket was not accepted",
    )
    return connection, reader, ready


def _pg_ws_authenticated_probe(
    world: Any,
    issuer: HttpClient,
    peer: HttpClient,
    actor: Actor,
) -> tuple[socket.socket, Any]:
    """Open a fresh, authenticated observer socket for one silence window."""
    ticket_response = issuer.request(
        "POST", "/api/v1/notifications/tickets", token=actor.access_token
    )
    ticket_body = ticket_response.json()
    ticket = ticket_body.get("ticket") if isinstance(ticket_body, dict) else None
    _require(
        ticket_response.status == 200
        and isinstance(ticket, str)
        and re.fullmatch(r"[A-Za-z0-9_-]{43}", ticket) is not None
        and set(ticket_body) == {"ticket", "expires_at", "expires_in_seconds"}
        and 0 < ticket_body.get("expires_in_seconds", 0) <= 30,
        "could not issue a fresh short-lived silence-probe ticket",
    )
    world.remember_secret(ticket)
    ticket_hash = hashlib.sha256(ticket.encode("ascii")).hexdigest()
    stored = world.database_connection.execute(
        "SELECT ticket_hash,consumed_at FROM notification_tickets WHERE ticket_hash=%s",
        (ticket_hash,),
    ).fetchone()
    _require(
        stored == (ticket_hash, None),
        "silence-probe ticket was not stored as a one-use hash",
    )

    connection = None
    reader = None
    try:
        status, _headers, connection, reader, _body = _pg_ws_connect(
            peer.base_url, PG_NOTIFICATION_TEST_ORIGIN
        )
        _require(status == 101, "silence-probe WebSocket did not upgrade on the peer node")
        _pg_ws_send_json(connection, {"type": "authenticate", "ticket": ticket})
        opcode, ready = _pg_ws_receive_json(connection, reader)
        _require(
            opcode == 0x1
            and set(ready)
            == {
                "type",
                "server_generation",
                "sync_required",
                "heartbeat_seconds",
                "poll_interval_seconds",
            }
            and ready.get("type") == "ready"
            and ready.get("sync_required") is True
            and ready.get("poll_interval_seconds") == 2,
            "silence-probe socket did not establish its baseline snapshot",
        )
        consumed = world.database_connection.execute(
            "SELECT consumed_at FROM notification_tickets WHERE ticket_hash=%s",
            (ticket_hash,),
        ).fetchone()
        _require(
            consumed is not None and consumed[0] is not None,
            "silence-probe socket did not consume its one-use ticket",
        )
        return connection, reader
    except BaseException:
        if connection is not None and reader is not None:
            _pg_ws_close(connection, reader)
        raise


def _pg_ws_open_for_actor(
    world: Any,
    issuer: HttpClient,
    peer: HttpClient,
    actor: Actor,
    *,
    access_token: str | None = None,
) -> tuple[socket.socket, Any, dict[str, Any]]:
    token = access_token or actor.access_token
    ticket_response = issuer.request(
        "POST", "/api/v1/notifications/tickets", token=token
    )
    ticket_body = ticket_response.json()
    ticket = ticket_body.get("ticket") if isinstance(ticket_body, dict) else None
    _require(
        ticket_response.status == 200
        and isinstance(ticket, str)
        and re.fullmatch(r"[A-Za-z0-9_-]{43}", ticket) is not None,
        "could not issue a live-session notification ticket",
    )
    world.remember_secret(ticket)
    ticket_hash = hashlib.sha256(ticket.encode("ascii")).hexdigest()
    _require(
        world.database_connection.execute(
            "SELECT ticket_hash,consumed_at FROM notification_tickets WHERE ticket_hash=%s",
            (ticket_hash,),
        ).fetchone()
        == (ticket_hash, None),
        "notification ticket must be stored as a pending one-way hash",
    )
    connection, reader, ready = _pg_ws_authenticate(
        peer.base_url, PG_NOTIFICATION_TEST_ORIGIN, ticket
    )
    return connection, reader, ready


def _pg_ws_expect_pong(
    connection: socket.socket,
    reader: Any,
    *,
    timeout_seconds: float = 2,
) -> None:
    payload = os.urandom(8)
    _pg_ws_send_frame(connection, 0x9, payload)
    connection.settimeout(timeout_seconds)
    try:
        opcode, response = _pg_ws_receive_frame(connection, reader)
    except (TimeoutError, socket.timeout):
        pytest.fail("still-authorized notification WebSocket did not answer a ping", pytrace=False)
    _require(
        opcode == 0xA and response == payload,
        "still-authorized notification WebSocket closed or sent an invalid frame",
    )


def _pg_ws_wait_hint(
    connection: socket.socket,
    reader: Any,
    predicate,
    *,
    timeout_seconds: float = 10,
) -> dict[str, Any]:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        connection.settimeout(max(0.2, deadline - time.monotonic()))
        try:
            opcode, frame = _pg_ws_receive_json(connection, reader)
        except (TimeoutError, socket.timeout):
            continue
        if opcode == 0x8:
            break
        if opcode == 0x1 and frame.get("type") == "sync_required" and predicate(frame):
            return frame
    pytest.fail("cross-node encrypted push did not produce its metadata hint", pytrace=False)


def _pg_ws_wait_hint_within(
    connection: socket.socket,
    reader: Any,
    predicate,
    *,
    started_at: float,
    timeout_seconds: float,
    description: str,
) -> tuple[dict[str, Any], float]:
    elapsed = time.monotonic() - started_at
    remaining = timeout_seconds - elapsed
    if remaining <= 0:
        pytest.fail(f"{description} exceeded its {timeout_seconds:.2f}s bound", pytrace=False)
    frame = _pg_ws_wait_hint(
        connection,
        reader,
        predicate,
        timeout_seconds=remaining,
    )
    elapsed = time.monotonic() - started_at
    _require(
        elapsed <= timeout_seconds,
        f"{description} exceeded its {timeout_seconds:.2f}s bound",
    )
    return frame, elapsed


def _pg_notification_listener_pid(world: Any, node_index: int) -> int | None:
    application_name = f"atermius-pg-http-node-{node_index}"
    row = world.database_connection.execute(
        "SELECT pid FROM pg_stat_activity WHERE datname=current_database() "
        "AND application_name=%s AND query ILIKE 'LISTEN %%' "
        "AND backend_type='client backend' ORDER BY backend_start DESC LIMIT 1",
        (application_name,),
    ).fetchone()
    return int(row[0]) if row is not None else None


def _pg_wait_notification_listener(
    world: Any,
    node_index: int,
    *,
    excluded_pid: int | None = None,
    timeout_seconds: float = 8,
) -> int:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        pid = _pg_notification_listener_pid(world, node_index)
        if pid is not None and pid != excluded_pid:
            return pid
        time.sleep(0.025)
    pytest.fail(
        f"node {node_index} did not restore its PostgreSQL LISTEN connection",
        pytrace=False,
    )


def _pg_wait_backend_exit(world: Any, backend_pid: int, *, timeout_seconds: float = 3) -> None:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        active = world.database_connection.execute(
            "SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE pid=%s)",
            (backend_pid,),
        ).fetchone()[0]
        if not active:
            return
        time.sleep(0.025)
    pytest.fail("terminated PostgreSQL notification backend remained active", pytrace=False)


def _pg_ws_expect_no_hint(
    connection: socket.socket,
    reader: Any,
    predicate,
    *,
    timeout_seconds: float,
    description: str,
) -> None:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return
        connection.settimeout(remaining)
        try:
            opcode, frame = _pg_ws_receive_json(connection, reader)
        except (TimeoutError, socket.timeout):
            # A socket.makefile reader cannot be reused after a read timeout.
            # This helper is only used with a short-lived probe socket, which
            # the caller closes immediately after this silence window.
            return
        if opcode == 0x8:
            pytest.fail(f"notification WebSocket closed during {description}", pytrace=False)
        if opcode == 0x1 and frame.get("type") == "sync_required" and predicate(frame):
            pytest.fail(f"unexpected sync hint during {description}", pytrace=False)


def _pg_ws_expect_auth_rejection(
    connection: socket.socket,
    reader: Any,
    *,
    timeout_seconds: float = 10,
) -> None:
    deadline = time.monotonic() + timeout_seconds
    error_frame = None
    close_code = None
    while time.monotonic() < deadline:
        connection.settimeout(max(0.2, deadline - time.monotonic()))
        try:
            opcode, payload = _pg_ws_receive_frame(connection, reader)
        except (TimeoutError, socket.timeout):
            continue
        if opcode == 0x1:
            try:
                decoded = json.loads(payload.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                pytest.fail("revoked notification socket sent invalid JSON", pytrace=False)
            if isinstance(decoded, dict) and decoded.get("type") == "error":
                error_frame = decoded
            elif isinstance(decoded, dict) and decoded.get("type") == "sync_required":
                pytest.fail(
                    "authorization revocation emitted a sync hint before closing the socket",
                    pytrace=False,
                )
        elif opcode == 0x8:
            close_code = struct.unpack("!H", payload[:2])[0] if len(payload) >= 2 else None
            break
    _require(
        error_frame == {"type": "error", "code": "AUTH_REQUIRED"}
        and close_code == 4001,
        "notification WebSocket did not reject and close with AUTH_REQUIRED",
    )


def _pg_ws_close(connection: socket.socket, reader: Any) -> None:
    try:
        _pg_ws_send_frame(connection, 0x8, struct.pack("!H", 1000))
    except OSError:
        pass
    try:
        reader.close()
    except OSError:
        pass
    connection.close()


@dataclass
class HttpResponse:
    status: int
    headers: Any
    body: bytes

    def json(self) -> Any:
        if not self.body:
            return None
        try:
            return json.loads(self.body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            return None

    def __repr__(self) -> str:
        return f"<HttpResponse status={self.status} body=[REDACTED]>"


class HttpClient:
    """Minimal black-box HTTP helper that never prints request secrets."""

    def __init__(self, base_url: str):
        self.base_url = base_url.rstrip("/")

    def request(
        self,
        method: str,
        path: str,
        *,
        token: str | None = None,
        body: bytes | None = None,
        json_body: Any = None,
        timeout: int = PG_ACCEPTANCE_TIMEOUT_SECONDS,
        additional_headers: dict[str, str] | None = None,
    ) -> HttpResponse:
        headers = {"Accept": "application/json"}
        if json_body is not None:
            body = json.dumps(
                json_body,
                separators=(",", ":"),
                ensure_ascii=False,
                allow_nan=False,
            ).encode("utf-8")
            headers["Content-Type"] = "application/json"
        elif body is not None:
            headers["Content-Type"] = "application/json"
        if token is not None:
            headers["Authorization"] = f"Bearer {token}"
        if additional_headers:
            headers.update(additional_headers)
        request = urllib.request.Request(
            self.base_url + path,
            data=body,
            headers=headers,
            method=method.upper(),
        )
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                return HttpResponse(response.status, response.headers, response.read())
        except urllib.error.HTTPError as error:
            return HttpResponse(error.code, error.headers, error.read())


@dataclass
class Actor:
    user_id: str
    device_id: str
    session_id: str
    username: str
    access_token: str = field(repr=False)
    refresh_token: str = field(repr=False)
    login_verifier: str = field(repr=False)
    signing_key: SigningKey = field(repr=False)
    signing_public_key: str
    device_seq: int = 0

    def __repr__(self) -> str:
        return f"<Actor user_id={self.user_id!r} device_id={self.device_id!r} credentials=[REDACTED]>"


@dataclass
class Tenant:
    vault_id: str
    actors: tuple[Actor, Actor]
    server_space_id: str
    generation: str

    def __repr__(self) -> str:
        return f"<Tenant vault_id={self.vault_id!r} actors=[REDACTED] generation={self.generation!r}>"


class PgHttpWorld:
    def __init__(
        self,
        *,
        root: Path,
        schema: str,
        database_connection: Any,
        psycopg_module: Any,
        pg_url: str,
        processes: list[subprocess.Popen[bytes]],
        log_handles: list[Any],
        log_paths: list[Path],
        clients: tuple[HttpClient, HttpClient],
        instance: dict[str, Any],
        secrets: list[str],
        binary: Path,
        runtime_env: dict[str, str],
        restore_target_url: str | None,
        v25_archive_url: str | None,
        backup_replica_endpoint_url: str | None,
        backup_replica_fixture_control_token: str | None,
        backup_replica_fixture_process: subprocess.Popen[bytes] | None,
    ):
        self.root = root
        self.schema = schema
        self.database_connection = database_connection
        self.psycopg = psycopg_module
        self.pg_url = pg_url
        self.processes = processes
        self.log_handles = log_handles
        self.log_paths = log_paths
        self.clients = clients
        self.instance = instance
        self.secrets = secrets
        self.binary = binary
        self.runtime_env = runtime_env
        self.restore_target_url = restore_target_url
        self.v25_archive_url = v25_archive_url
        self.backup_replica_endpoint_url = backup_replica_endpoint_url
        self.backup_replica_fixture_control_token = backup_replica_fixture_control_token
        self.backup_replica_fixture_process = backup_replica_fixture_process
        self._cli_invocation = 0
        self._cli_invocation_lock = threading.Lock()

    def __repr__(self) -> str:
        return f"<PgHttpWorld schema={self.schema!r} processes={len(self.processes)} secrets=[REDACTED]>"

    def remember_secret(self, value: str) -> None:
        self.secrets.append(value)

    def run_cli_result(self, *arguments: str) -> subprocess.CompletedProcess[str]:
        """Run a CLI operation against the shared PG schema with isolated local state."""
        with self._cli_invocation_lock:
            self._cli_invocation += 1
            invocation = self._cli_invocation
        cli_root = self.root / f"cli-{invocation}"
        data_dir = cli_root / "data"
        data_dir.mkdir(parents=True, mode=0o700)
        if os.name == "posix":
            os.chmod(cli_root, 0o700)
            os.chmod(data_dir, 0o700)
        env = self.runtime_env.copy()
        env["ATERMIUS_DATA_DIR"] = str(data_dir)
        env["ATERMIUS_DATABASE_URL"] = f"sqlite://{data_dir / 'atermius.db'}?mode=rwc"
        env["ATERMIUS_SYNC_PG_URL"] = _with_application_name(
            self.pg_url, f"atermius-pg-http-cli-{invocation}"
        )
        env["PGAPPNAME"] = f"atermius-pg-http-cli-{invocation}"
        try:
            result = subprocess.run(
                [str(self.binary), *arguments],
                cwd=ROOT,
                env=env,
                capture_output=True,
                text=True,
                timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired):
            pytest.fail("PostgreSQL onboarding CLI command could not complete", pytrace=False)
        return result

    def run_cli(self, *arguments: str) -> str:
        result = self.run_cli_result(*arguments)
        if result.returncode != 0:
            # CLI output can contain a one-time credential. Keep failure output
            # deliberately generic even when a command implementation regresses.
            pytest.fail(
                f"PostgreSQL onboarding CLI command failed (exit {result.returncode})",
                pytrace=False,
            )
        return result.stdout

    def restart_node(self, index: int, *, pg_url: str | None = None) -> None:
        """Restart one PG node so its startup maintenance tick sees seeded rows."""
        _stop_acceptance_process(self.processes[index])
        port = _free_loopback_port()
        node = "a" if index == 0 else "b"
        invocation = f"restart-{index}-{uuid.uuid4().hex[:8]}"
        data_dir = self.root / f"node-{node}" / "data"
        env = self.runtime_env.copy()
        env.update(
            {
                "ATERMIUS_BIND": f"127.0.0.1:{port}",
                "ATERMIUS_DATA_DIR": str(data_dir),
                "ATERMIUS_DATABASE_URL": f"sqlite://{data_dir / 'atermius.db'}?mode=rwc",
                "ATERMIUS_SYNC_PG_URL": _with_application_name(
                    pg_url or self.pg_url, f"atermius-pg-http-{invocation}"
                ),
                "PGAPPNAME": f"atermius-pg-http-{invocation}",
            }
        )
        log_path = self.root / f"node-{node}-{invocation}.log"
        log_handle = log_path.open("wb")
        self.log_handles.append(log_handle)
        self.log_paths.append(log_path)
        process = subprocess.Popen(
            [str(self.binary), "serve"],
            cwd=ROOT,
            env=env,
            stdout=log_handle,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )
        self.processes[index] = process
        clients = list(self.clients)
        clients[index] = HttpClient(f"http://127.0.0.1:{port}")
        self.clients = (clients[0], clients[1])
        deadline = time.monotonic() + PG_ACCEPTANCE_TIMEOUT_SECONDS
        while time.monotonic() < deadline:
            if process.poll() is not None:
                pytest.fail(
                    "restarted PostgreSQL worker node exited during startup; redacted log tail: "
                    f"{self.redacted_log_tail()}",
                    pytrace=False,
                )
            try:
                if self.clients[index].request("GET", "/health/ready", timeout=2).status == 200:
                    return
            except (OSError, urllib.error.URLError, TimeoutError):
                pass
            time.sleep(0.1)
        pytest.fail(
            "restarted PostgreSQL worker node did not become ready; redacted log tail: "
            f"{self.redacted_log_tail()}",
            pytrace=False,
        )

    def bootstrap_token(self) -> str:
        output = self.run_cli("bootstrap")
        match = re.search(r"one-time setup token[^\n]*:\s*([A-Za-z0-9_-]{43})", output)
        if not match:
            pytest.fail("bootstrap CLI did not return a valid one-time token", pytrace=False)
        token = match.group(1)
        self.remember_secret(token)
        return token

    def account_invitation(self, username: str) -> str:
        output = self.run_cli("create-account-invite", "--username", username)
        match = re.search(r"account invitation[^\n]*:\s*([A-Za-z0-9_-]{43})", output)
        if not match:
            pytest.fail("account invitation CLI did not return a valid one-time token", pytrace=False)
        token = match.group(1)
        self.remember_secret(token)
        return token

    def seed_tenant(self, key_dir: Path, *, vault_id: str | None = None) -> Tenant:
        """Insert provisioned credentials, token hashes and device material into PG."""
        key_dir.mkdir(parents=True, mode=0o700, exist_ok=True)
        if os.name == "posix":
            os.chmod(key_dir, 0o700)
        actors: list[Actor] = []
        user_id = str(uuid.uuid4())
        vault_id = vault_id or str(uuid.uuid4())
        username = f"pg-http-{uuid.uuid4().hex}@example.test"
        verifier_bytes = os.urandom(32)
        login_verifier = b64url(verifier_bytes)
        verifier_salt = os.urandom(16)
        verifier_hash = hash_secret(
            verifier_bytes,
            verifier_salt,
            time_cost=2,
            memory_cost=19_456,
            parallelism=1,
            hash_len=32,
            type=Argon2Type.ID,
            version=19,
        ).decode("ascii")
        kdf = {
            "id": "argon2id13",
            "salt": b64url(verifier_salt),
            "mem_kib": 65_536,
            "iterations": 3,
            "parallelism": 1,
            "version": 1,
        }
        self.remember_secret(login_verifier)
        self.remember_secret(verifier_hash)
        for index in range(2):
            signing_key = SigningKey(key_dir, f"device-{index}")
            device_id = str(uuid.uuid4())
            session_id = str(uuid.uuid4())
            access_token = b64url(os.urandom(32))
            refresh_token = b64url(os.urandom(32))
            self.remember_secret(access_token)
            self.remember_secret(refresh_token)
            access_hash = hashlib.sha256(access_token.encode("ascii")).hexdigest()
            refresh_hash = hashlib.sha256(refresh_token.encode("ascii")).hexdigest()
            self.remember_secret(access_hash)
            self.remember_secret(refresh_hash)
            public_key = b64url(signing_key.public_key)
            actor = Actor(
                user_id=user_id,
                device_id=device_id,
                session_id=session_id,
                username=username,
                access_token=access_token,
                refresh_token=refresh_token,
                login_verifier=login_verifier,
                signing_key=signing_key,
                signing_public_key=public_key,
            )
            actors.append(actor)

        connection = self.database_connection
        connection.execute(
            "INSERT INTO users(user_id,username,status) VALUES (%s,%s,'active')",
            (user_id, actors[0].username),
        )
        connection.execute(
            "INSERT INTO auth_credentials(user_id,login_verifier_hash,verifier_salt,kdf_json,account_key_envelope) "
            "VALUES (%s,%s,%s,%s,%s)",
            (
                user_id,
                verifier_hash,
                b64url(verifier_salt),
                json.dumps(kdf, separators=(",", ":")),
                "{}",
            ),
        )
        for actor in actors:
            connection.execute(
                "INSERT INTO devices(device_id,user_id,name,signing_public_key,encryption_public_key,status) "
                "VALUES (%s,%s,%s,%s,%s,'active')",
                (
                    actor.device_id,
                    user_id,
                    "pytest device",
                    actor.signing_public_key,
                    b64url(os.urandom(32)),
                ),
            )
            connection.execute(
                "INSERT INTO sessions(session_id,user_id,device_id,family_id,access_hash,refresh_hash,"
                "access_expires_at,refresh_expires_at) "
                "VALUES (%s,%s,%s,%s,%s,%s,CURRENT_TIMESTAMP + INTERVAL '1 hour',"
                "CURRENT_TIMESTAMP + INTERVAL '1 day')",
                (
                    actor.session_id,
                    user_id,
                    actor.device_id,
                    str(uuid.uuid4()),
                    hashlib.sha256(actor.access_token.encode("ascii")).hexdigest(),
                    hashlib.sha256(actor.refresh_token.encode("ascii")).hexdigest(),
                ),
            )
        connection.execute(
            "INSERT INTO vaults(vault_id,owner_user_id,state,active_epoch,membership_version,required_record_schema) "
            "VALUES (%s,%s,'active',1,1,1)",
            (vault_id, user_id),
        )
        connection.execute(
            "INSERT INTO vault_members(vault_id,user_id,role,state) VALUES (%s,%s,'owner','active')",
            (vault_id, user_id),
        )
        connection.execute(
            "INSERT INTO vault_counters(vault_id,last_committed_seq,last_conflict_seq,minimum_available_seq) "
            "VALUES (%s,0,0,1)",
            (vault_id,),
        )
        return Tenant(
            vault_id=vault_id,
            actors=(actors[0], actors[1]),
            server_space_id=str(self.instance["server_space_id"]),
            generation=str(self.instance["generation"]),
        )

    def make_envelope(
        self,
        tenant: Tenant,
        actor: Actor,
        *,
        operation: str = "create",
        record_id: str | None = None,
        revision_id: str | None = None,
        op_id: str | None = None,
        base_revision_id: str | None = None,
        ciphertext: bytes | None = None,
    ) -> dict[str, Any]:
        actor.device_seq += 1
        unsigned = {
            "header": {
                "wire_version": 1,
                "server_space_id": tenant.server_space_id,
                "vault_id": tenant.vault_id,
                "record_id": record_id or str(uuid.uuid4()),
                "revision_id": revision_id or str(uuid.uuid4()),
                "base_revision_id": base_revision_id,
                "op_id": op_id or str(uuid.uuid4()),
                "device_id": actor.device_id,
                "device_seq": str(actor.device_seq),
                "key_epoch": "1",
                "membership_version": "1",
                "record_schema": 1,
                "operation": operation,
                "crypto_suite": "atermius-vault-v1",
                "kdf_salt": b64url(os.urandom(32)),
            },
            "nonce": b64url(os.urandom(24)),
            "ciphertext": b64url(ciphertext if ciphertext is not None else os.urandom(64)),
        }
        self.remember_secret(unsigned["ciphertext"])
        return {
            **unsigned,
            "signature": b64url(actor.signing_key.sign(jcs(unsigned))),
        }

    def push_body(
        self, tenant: Tenant, actor: Actor, operations: list[dict[str, Any]], batch_id: str | None = None
    ) -> dict[str, Any]:
        return {
            "protocol_version": 1,
            "server_generation": tenant.generation,
            "vault_id": tenant.vault_id,
            "device_id": actor.device_id,
            "batch_id": batch_id or str(uuid.uuid4()),
            "operations": operations,
        }

    def state(
        self,
        tenant: Tenant,
        *,
        record_ids: list[str] = (),
        op_ids: list[str] = (),
        batch_ids: list[str] = (),
    ) -> tuple[int, int, int, int, int, int, int]:
        connection = self.database_connection
        counter = connection.execute(
            "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s",
            (tenant.vault_id,),
        ).fetchone()[0]
        versions = connection.execute(
            "SELECT count(*) FROM record_versions WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (tenant.vault_id, list(record_ids)),
        ).fetchone()[0]
        heads = connection.execute(
            "SELECT count(*) FROM record_heads WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (tenant.vault_id, list(record_ids)),
        ).fetchone()[0]
        events = connection.execute(
            "SELECT count(*) FROM change_events WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (tenant.vault_id, list(record_ids)),
        ).fetchone()[0]
        receipts = connection.execute(
            "SELECT count(*) FROM op_receipts WHERE vault_id=%s AND op_id=ANY(%s::text[])",
            (tenant.vault_id, list(op_ids)),
        ).fetchone()[0]
        batches = connection.execute(
            "SELECT count(*) FROM batch_receipts WHERE vault_id=%s AND batch_id=ANY(%s::text[])",
            (tenant.vault_id, list(batch_ids)),
        ).fetchone()[0]
        vault_audits = connection.execute(
            "SELECT count(*) FROM audit_events WHERE scope_type='vault' AND scope_id=%s",
            (tenant.vault_id,),
        ).fetchone()[0]
        return counter, versions, heads, events, receipts, batches, vault_audits

    def assert_secrets_not_in_local_files(self) -> None:
        """Check private node/CLI data and logs; PostgreSQL is the intended store."""
        paths: list[Path] = []
        local_data_dirs = [self.root / "node-a" / "data", self.root / "node-b" / "data"]
        local_data_dirs.extend(self.root.glob("cli-*/data"))
        for local_dir in local_data_dirs:
            paths.extend(path for path in local_dir.rglob("*") if path.is_file())
        paths.extend(path for path in self.log_paths if path.exists())
        byte_secrets = [value.encode("utf-8") for value in self.secrets if value]
        for path in paths:
            try:
                contents = path.read_bytes()
            except OSError:
                pytest.fail("could not inspect a private node artifact", pytrace=False)
            if any(secret in contents for secret in byte_secrets):
                pytest.fail(
                    f"opaque credential/ciphertext found in local artifact {path.name}",
                    pytrace=False,
                )

    def redacted_log_tail(self, limit: int = 3000) -> str:
        combined = "\n".join(path.read_text(errors="replace") for path in self.log_paths if path.exists())
        return redact_secrets(combined, self.pg_url, *self.secrets)[-limit:]


def _assert_postgres_v25_schema_upgrades_to_v38(world: PgHttpWorld) -> None:
    """Apply the bundled v26-v38 migrations to an independent v25 schema."""
    admin_connection = world.database_connection
    psycopg = world.psycopg
    schema = f"atermius_it_v25_upgrade_{uuid.uuid4().hex}"
    admin_connection.execute(
        psycopg.sql.SQL("CREATE SCHEMA {}").format(psycopg.sql.Identifier(schema))
    )
    legacy_connection = None
    try:
        legacy_connection = psycopg.connect(
            world.pg_url,
            autocommit=True,
            connect_timeout=10,
            application_name="atermius-pg-v25-upgrade-acceptance",
        )
        legacy_connection.execute(
            psycopg.sql.SQL("SET search_path TO {}").format(psycopg.sql.Identifier(schema))
        )
        migrations = sorted(POSTGRES_MIGRATIONS.glob("[0-9][0-9][0-9][0-9]_*.sql"))
        for migration in migrations:
            if int(migration.name[:4]) <= 25:
                legacy_connection.execute(migration.read_text(encoding="utf-8"), prepare=False)
        marker_before = legacy_connection.execute(
            "SELECT schema_version FROM atermius_instance_schema WHERE singleton=1"
        ).fetchone()[0]
        _require(marker_before == 25, "the isolated pre-upgrade PostgreSQL schema must be v25")
        for migration in migrations:
            if 25 < int(migration.name[:4]) <= 38:
                legacy_connection.execute(migration.read_text(encoding="utf-8"), prepare=False)
        marker_after = legacy_connection.execute(
            "SELECT schema_version FROM atermius_instance_schema WHERE singleton=1"
        ).fetchone()[0]
        schedule = legacy_connection.execute(
            "SELECT interval_hours,next_run_at FROM instance_backup_schedule WHERE schedule_id=1"
        ).fetchone()
        actor_column = legacy_connection.execute(
            "SELECT is_nullable FROM information_schema.columns \
             WHERE table_schema=current_schema() AND table_name='instance_admin_jobs' \
               AND column_name='requested_by_user_id'"
        ).fetchone()
        _require(
            marker_after == 38 and schedule == (None, None) and actor_column == ("YES",),
            "the bundled v26-v38 migrations must upgrade a fresh v25 schema and seed its disabled schedule",
        )
    finally:
        if legacy_connection is not None:
            legacy_connection.close()
        admin_connection.execute(
            psycopg.sql.SQL("DROP SCHEMA IF EXISTS {} CASCADE").format(
                psycopg.sql.Identifier(schema)
            )
        )


class LostAckProxyServer(http.server.ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address: tuple[str, int], upstream: tuple[str, int], target_path: str):
        self.upstream = upstream
        self.target_path = target_path
        self.forwarded = threading.Event()
        self.dropped = threading.Event()
        self.upstream_status: int | None = None
        self._drop_once_lock = threading.Lock()
        self._drop_once = True
        super().__init__(address, LostAckProxyHandler)


class LostAckProxyHandler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, _format: str, *args: Any) -> None:
        # Request paths, headers and bodies are intentionally never logged.
        return

    def do_POST(self) -> None:  # noqa: N802 - BaseHTTPRequestHandler API
        server = self.server
        assert isinstance(server, LostAckProxyServer)
        try:
            content_length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self.send_error(400)
            return
        body = self.rfile.read(content_length)
        host, port = server.upstream
        upstream = http.client.HTTPConnection(host, port, timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
        headers = {
            key: value
            for key, value in self.headers.items()
            if key.lower() not in {"host", "connection", "proxy-connection"}
        }
        headers["Connection"] = "close"
        try:
            upstream.request("POST", self.path, body=body, headers=headers)
            response = upstream.getresponse()
            response_body = response.read()
            status = response.status
            response_headers = response.getheaders()
        except (OSError, http.client.HTTPException):
            self.close_connection = True
            return
        finally:
            upstream.close()

        should_drop = False
        if self.path == server.target_path and status in (200, 201):
            with server._drop_once_lock:
                if server._drop_once:
                    server._drop_once = False
                    should_drop = True
        server.upstream_status = status
        server.forwarded.set()
        if should_drop:
            # The upstream has committed and returned success; close without
            # writing status, headers, or body to simulate a lost ACK.
            server.dropped.set()
            self.close_connection = True
            try:
                self.connection.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            self.connection.close()
            return

        self.send_response(status)
        skip_headers = {"connection", "transfer-encoding", "content-length"}
        for key, value in response_headers:
            if key.lower() not in skip_headers:
                self.send_header(key, value)
        self.send_header("Content-Length", str(len(response_body)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(response_body)
        self.close_connection = True


class PgRecoveryWebProbe:
    """Loopback-only, token-gated state probe for the external Web runner."""

    def __init__(self, world: PgHttpWorld):
        self.world = world
        self.token = b64url(os.urandom(32))
        self.lock = threading.Lock()
        probe = self

        class Handler(http.server.BaseHTTPRequestHandler):
            def log_message(self, _format: str, *_args: Any) -> None:
                return

            def do_POST(self) -> None:
                if self.path != "/probe" or not hmac.compare_digest(
                    self.headers.get("x-probe-token", ""), probe.token
                ):
                    self.send_error(404)
                    return
                try:
                    length = int(self.headers.get("content-length", "0"))
                    if length <= 0 or length > 1_000_000:
                        raise ValueError("invalid request length")
                    request_data = json.loads(self.rfile.read(length))
                    action = request_data.get("action")
                    with probe.lock:
                        if action == "snapshot":
                            result = probe.snapshot(str(request_data.get("username", "")))
                        elif action == "vault_roles":
                            vault_id = str(request_data.get("vault_id", ""))
                            rows = probe.world.database_connection.execute(
                                "SELECT role,state,count(*) AS count FROM vault_members "
                                "WHERE vault_id=%s GROUP BY role,state ORDER BY role,state",
                                (vault_id,),
                            ).fetchall()
                            result = [
                                {"role": row[0], "state": row[1], "count": row[2]}
                                for row in rows
                            ]
                        elif action == "clear_rate_limits":
                            probe.world.database_connection.execute(
                                "DELETE FROM auth_rate_limits WHERE endpoint = ANY(%s)",
                                (["prelogin", "login", "mfa_login"],),
                            )
                            result = {"cleared": True}
                        elif action == "remember_and_scan":
                            username = str(request_data.get("username", ""))
                            secrets = request_data.get("secrets")
                            if not isinstance(secrets, list) or len(secrets) > 128 or any(
                                not isinstance(value, str) or len(value) > 4096 for value in secrets
                            ):
                                raise ValueError("invalid privacy-scan input")
                            for value in secrets:
                                if value:
                                    probe.world.remember_secret(value)
                            result = {"matched": probe.scan_database(username, secrets)}
                        else:
                            raise ValueError("unknown probe action")
                    body = json.dumps(result, separators=(",", ":")).encode()
                    self.send_response(200)
                    self.send_header("content-type", "application/json")
                    self.send_header("content-length", str(len(body)))
                    self.end_headers()
                    self.wfile.write(body)
                except Exception:
                    self.send_error(400)

        self.server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        self.server.daemon_threads = True
        host, port = self.server.server_address
        self.url = f"http://{host}:{port}/probe"
        self.thread = threading.Thread(target=self.server.serve_forever, daemon=True)
        self.thread.start()

    def snapshot(self, username: str) -> dict[str, Any]:
        connection = self.world.database_connection
        connection.execute("BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY")
        try:
            user = connection.execute(
                "SELECT user_id FROM users WHERE username=%s", (username,)
            ).fetchone()
            if user is None:
                raise ValueError("test user not found")
            user_id = user[0]
            def rows_as_dicts(query: str, params: tuple[Any, ...]) -> list[dict[str, Any]]:
                cursor = connection.execute(query, params)
                names = [column.name for column in cursor.description]
                return [dict(zip(names, row)) for row in cursor.fetchall()]

            devices = rows_as_dicts(
                "SELECT device_id,status FROM devices WHERE user_id=%s ORDER BY created_at,device_id",
                (user_id,),
            )
            vaults = rows_as_dicts(
                "SELECT v.vault_id,v.active_epoch,v.membership_version,vm.role,"
                "vm.state AS member_state FROM vaults v JOIN vault_members vm "
                "ON vm.vault_id=v.vault_id WHERE vm.user_id=%s AND vm.state='active' "
                "AND v.state IN ('active','deleting') ORDER BY v.created_at,v.vault_id",
                (user_id,),
            )
            sessions = []
            for row in connection.execute(
                "SELECT session_id,device_id,revoked_at FROM sessions WHERE user_id=%s ORDER BY created_at,session_id",
                (user_id,),
            ).fetchall():
                sessions.append({
                    "session_id": row[0], "device_id": row[1],
                    "revoked_at": row[2].isoformat() if row[2] is not None else None,
                })
            versions = rows_as_dicts(
                "SELECT vault_id,record_id,revision_id,digest,envelope,commit_seq "
                "FROM record_versions WHERE vault_id IN "
                "(SELECT vault_id FROM vault_members WHERE user_id=%s) ORDER BY commit_seq",
                (user_id,),
            )
            mfa = connection.execute(
                "SELECT enabled_at FROM auth_mfa WHERE user_id=%s AND enabled_at IS NOT NULL",
                (user_id,),
            ).fetchone()
            codes = connection.execute(
                "SELECT count(*) FROM auth_mfa_recovery_codes WHERE user_id=%s AND consumed_at IS NULL",
                (user_id,),
            ).fetchone()[0]
            recovery = connection.execute(
                "SELECT recovery_generation FROM account_recovery WHERE user_id=%s", (user_id,)
            ).fetchone()
            boxes = rows_as_dicts(
                "SELECT vault_id,key_epoch,envelope FROM account_recovery_key_envelopes WHERE user_id=%s",
                (user_id,),
            )
            keyboxes = rows_as_dicts(
                "SELECT vault_id,epoch,membership_version,recipient_device_id,envelope FROM vault_key_envelopes "
                "WHERE recipient_user_id=%s", (user_id,),
            )
            challenges = rows_as_dicts(
                "SELECT challenge_id_hash,challenge_hash,recovery_generation,consumed_at FROM ("
                "SELECT challenge_id_hash,challenge_hash,recovery_generation,consumed_at "
                "FROM account_recovery_challenges WHERE user_id=%s UNION ALL "
                "SELECT challenge_id_hash,challenge_hash,recovery_generation,consumed_at "
                "FROM pg_test_recovery_challenge_deletions WHERE user_id=%s) evidence "
                "ORDER BY challenge_id_hash",
                (user_id, user_id),
            )
            connection.execute("COMMIT")
            return {
                "user_id": user_id,
                "devices": devices,
                "sessions": sessions,
                "vaults": vaults,
                "versions": versions,
                "mfa_enabled": mfa is not None,
                "mfa_recovery_codes": codes,
                "recovery_generation": recovery[0] if recovery else None,
                "recovery_boxes": boxes,
                "keyboxes": keyboxes,
                "recovery_challenges": challenges,
            }
        except Exception:
            connection.execute("ROLLBACK")
            raise

    def scan_database(self, username: str, secrets: list[str]) -> bool:
        connection = self.world.database_connection
        user = connection.execute("SELECT user_id FROM users WHERE username=%s", (username,)).fetchone()
        if user is None:
            raise ValueError("test user not found for privacy scan")
        user_id = user[0]
        scans = (
            ("users", "user_id=%s"),
            ("auth_credentials", "user_id=%s"),
            ("auth_mfa", "user_id=%s"),
            ("auth_mfa_recovery_codes", "user_id=%s"),
            ("auth_mfa_login_challenges", "user_id=%s"),
            ("devices", "user_id=%s"),
            ("sessions", "user_id=%s"),
            ("account_recovery", "user_id=%s"),
            ("account_recovery_generation", "user_id=%s"),
            ("account_recovery_key_envelopes", "user_id=%s"),
            ("account_recovery_challenges", "user_id=%s"),
            ("pg_test_recovery_challenge_deletions", "user_id=%s"),
            ("account_recovery_receipts", "user_id=%s"),
            ("audit_events", "scope_type='account' AND scope_id=%s"),
            ("vault_key_envelopes", "recipient_user_id=%s"),
            ("record_versions", "vault_id IN (SELECT vault_id FROM vault_members WHERE user_id=%s)"),
            ("record_heads", "vault_id IN (SELECT vault_id FROM vault_members WHERE user_id=%s)"),
            ("change_events", "vault_id IN (SELECT vault_id FROM vault_members WHERE user_id=%s)"),
            ("op_receipts", "vault_id IN (SELECT vault_id FROM vault_members WHERE user_id=%s)"),
        )
        documents: list[str] = []
        for table, predicate in scans:
            documents.extend(
                row[0] for row in connection.execute(
                    f"SELECT to_jsonb(row_data)::text FROM {table} AS row_data WHERE {predicate}",
                    (user_id,),
                ).fetchall()
            )
        haystack = "\n".join(documents)
        return any(value and len(value) >= 16 and value in haystack for value in secrets)

    def close(self) -> None:
        self.server.shutdown()
        self.server.server_close()
        self.thread.join(timeout=5)


