@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_OVERVIEW_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_overview_is_shared_bounded_and_rechecks_allowlist(
    pg_http_world: PgHttpWorld,
    tmp_path: Path,
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-overview-admin")
    admin = admin_tenant.actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_OVERVIEW_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-overview-outsider").actors[0]

    unauthenticated = pg_http_world.clients[0].request("GET", "/api/v1/admin/overview")
    denied = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/overview", token=outsider.access_token
    )
    _require(
        unauthenticated.status == 401
        and denied.status == 403
        and _error_code(denied) == "INSTANCE_ADMIN_REQUIRED",
        "PostgreSQL overview must require a live session and current admin allowlist",
    )

    object_id = str(uuid.uuid4())
    upload_id = str(uuid.uuid4())
    database.execute(
        "INSERT INTO blob_objects(vault_id,object_id,size,sha256) VALUES (%s,%s,321,%s)",
        (admin_tenant.vault_id, object_id, "a" * 64),
    )
    database.execute(
        "INSERT INTO uploads(upload_id,vault_id,user_id,object_id,expected_size,"
        "expected_sha256,chunk_size,state,expires_at,storage_backend,storage_store_id,storage_key) "
        "VALUES (%s,%s,%s,%s,1234,%s,1024,'open',clock_timestamp()+INTERVAL '1 hour',"
        "'filesystem','acceptance-store','acceptance-key')",
        (upload_id, admin_tenant.vault_id, admin.user_id, str(uuid.uuid4()), "b" * 64),
    )
    expected_counts = database.execute(
        "SELECT (SELECT COUNT(*) FROM users),"
        "(SELECT COUNT(*) FROM users WHERE status='active'),"
        "(SELECT COUNT(*) FROM users WHERE status='deleting'),"
        "(SELECT COUNT(*) FROM users WHERE status='disabled'),"
        "(SELECT COUNT(*) FROM devices d JOIN users u ON u.user_id=d.user_id "
        " WHERE d.status='active' AND u.status='active'),"
        "(SELECT COUNT(*) FROM vaults WHERE state='active'),"
        "(SELECT COUNT(*) FROM vaults WHERE state='deleting'),"
        "(SELECT COALESCE(SUM(size),0)::BIGINT FROM blob_objects),"
        "(SELECT COALESCE(SUM(expected_size),0) FROM uploads "
        " WHERE state='open' AND expires_at>clock_timestamp())::BIGINT,"
        "(SELECT COALESCE(SUM(quota_bytes),0)::BIGINT FROM vaults "
        " WHERE state IN ('active','deleting'))"
    ).fetchone()
    count_keys = (
        "accounts_total",
        "accounts_active",
        "accounts_deleting",
        "accounts_disabled",
        "devices_active",
        "vaults_active",
        "vaults_deleting",
        "stored_bytes",
        "reserved_upload_bytes",
        "vault_quota_bytes",
    )
    first = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/overview", token=admin.access_token
    )
    peer = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/overview", token=admin.access_token
    )
    _require(
        first.status == peer.status == 200,
        "both PostgreSQL nodes must serve the allowlisted admin overview",
    )
    body = first.json()
    peer_body = peer.json()
    _require(
        isinstance(body, dict)
        and set(body)
        == {"instance", "counts", "relay", "database_encryption", "generated_at"}
        and body.get("database_encryption") in {"enabled", "disabled"}
        and isinstance(body.get("instance"), dict)
        and set(body["instance"])
        == {"instance_id", "server_space_id", "generation", "protocol_version"}
        and body["instance"]["protocol_version"] == 1
        and isinstance(body.get("counts"), dict)
        and set(body["counts"]) == set(count_keys)
        and tuple(body["counts"][key] for key in count_keys) == tuple(expected_counts),
        "PostgreSQL overview must return exact shared counts from server-side metadata",
    )
    _require(
        body["counts"]["stored_bytes"] >= 321
        and body["counts"]["reserved_upload_bytes"] >= 1234
        and all(type(value) is int and value >= 0 for value in body["counts"].values()),
        "overview storage and reservation aggregates must be bounded nonnegative integers",
    )
    _require(
        isinstance(body.get("relay"), dict)
        and set(body["relay"])
        == {"enabled", "allow_cidrs", "allow_ports", "max_connections_per_user"}
        and body["relay"]["enabled"] is False
        and body["relay"]["allow_cidrs"] == []
        and body["relay"]["allow_ports"] == []
        and isinstance(body["relay"]["max_connections_per_user"], int)
        and body["relay"]["max_connections_per_user"] > 0,
        "restricted PostgreSQL overview must report that Relay routes are unavailable",
    )
    _require(
        isinstance(body.get("generated_at"), str)
        and datetime.fromisoformat(body["generated_at"].replace("Z", "+00:00"))
        and {
            key: value for key, value in body.items() if key != "generated_at"
        }
        == {key: value for key, value in peer_body.items() if key != "generated_at"},
        "two PostgreSQL nodes must return the same shared overview DTO",
    )
    serialized = json.dumps(body).lower()
    _require(
        PG_ADMIN_OVERVIEW_USERNAME not in serialized
        and admin.user_id not in serialized
        and admin_tenant.vault_id not in serialized
        and "username" not in serialized
        and "envelope" not in serialized,
        "overview must not disclose account identity, Vault ID, or client envelopes",
    )

    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        ("former-admin@example.test", admin.user_id),
    )
    removed_from_allowlist = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/overview", token=admin.access_token
    )
    _require(
        removed_from_allowlist.status == 403
        and _error_code(removed_from_allowlist) == "INSTANCE_ADMIN_REQUIRED",
        "the overview must recheck current allowlist membership on every request",
    )
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_OVERVIEW_USERNAME, admin.user_id),
    )
    logged_out = pg_http_world.clients[0].request(
        "POST", "/api/v1/auth/logout", token=admin.access_token
    )
    revoked = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/overview", token=admin.access_token
    )
    _require(
        logged_out.status == 200
        and revoked.status == 401
        and _error_code(revoked) == "AUTH_REQUIRED",
        "a revoked PG session must immediately lose overview access across nodes",
    )
    for method, path in (
        ("POST", "/api/v1/admin/overview"),
        ("GET", "/api/v1/admin/overview/"),
        ("GET", "/api/v1/admin/overview/extra"),
    ):
        blocked = pg_http_world.clients[0].request(method, path, token=admin.access_token)
        _require(
            blocked.status == 503 and _error_code(blocked) == "PG_SYNC_SCOPE_LIMITED",
            "overview route guard must reject noncanonical methods and paths",
        )


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_METRICS_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_metrics_credentials_are_shared_scoped_and_private(
    pg_http_world: PgHttpWorld,
    tmp_path: Path,
) -> None:
    """Exercise the fixed scrape contract and shared one-time credential on both PG nodes."""
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-metrics-admin")
    admin = admin_tenant.actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_METRICS_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-metrics-outsider").actors[0]
    node_a, node_b = pg_http_world.clients
    metrics_path = "/api/v1/admin/metrics"
    credential_path = "/api/v1/admin/metrics-credential"

    no_session = [
        node_a.request("GET", metrics_path),
        node_a.request("GET", credential_path),
        node_a.request("POST", credential_path),
        node_a.request("DELETE", credential_path),
    ]
    member_denied = [
        node_b.request("GET", metrics_path, token=outsider.access_token),
        node_b.request("GET", credential_path, token=outsider.access_token),
        node_b.request("POST", credential_path, token=outsider.access_token),
        node_b.request("DELETE", credential_path, token=outsider.access_token),
    ]
    _require(
        all(response.status == 401 for response in no_session)
        and all(
            response.status == 403
            and _error_code(response) == "INSTANCE_ADMIN_REQUIRED"
            for response in member_denied
        ),
        "PG metrics scrape and credential management must require an allowlisted active administrator",
    )

    def status(client: HttpClient, token: str) -> HttpResponse:
        return client.request("GET", credential_path, token=token)

    inactive_a = status(node_a, admin.access_token)
    inactive_b = status(node_b, admin.access_token)
    _require(
        inactive_a.status == inactive_b.status == 200
        and inactive_a.json() == {"active": False, "updated_at": None}
        and inactive_b.json() == inactive_a.json(),
        "both PG nodes must report the same inactive scrape credential status",
    )

    precredential_scrape = node_a.request("GET", metrics_path, token=admin.access_token)
    _require(
        precredential_scrape.status == 200,
        "an allowlisted administrator session must scrape metrics before issuing a scrape credential",
    )

    def verify_metrics_contract(response: HttpResponse) -> dict[str, int]:
        content_type = response.headers.get("Content-Type", "")
        _require(
            response.status == 200
            and content_type.startswith("text/plain;")
            and "version=0.0.4" in content_type
            and "charset=utf-8" in content_type
            and response.headers.get("Cache-Control") == "no-store"
            and response.headers.get("X-Content-Type-Options") == "nosniff",
            "PG metrics response must retain the exact Prometheus content and cache headers",
        )
        exposition = response.body.decode("utf-8")
        samples = [line for line in exposition.splitlines() if line and not line.startswith("#")]
        expected_series = {
            'atermius_accounts{status="active"}',
            'atermius_accounts{status="deleting"}',
            'atermius_accounts{status="disabled"}',
            "atermius_devices_active",
            'atermius_vaults{state="active"}',
            'atermius_vaults{state="deleting"}',
            "atermius_blob_stored_bytes",
            "atermius_upload_reserved_bytes",
            'atermius_object_delete_queue{state="pending"}',
            'atermius_object_delete_queue{state="retry_wait"}',
            'atermius_object_delete_queue{state="quarantined"}',
            'atermius_mobile_push_send_results_total{provider="apns",outcome="accepted"}',
            'atermius_mobile_push_send_results_total{provider="apns",outcome="invalid_token"}',
            'atermius_mobile_push_send_results_total{provider="apns",outcome="retryable_failure"}',
            'atermius_mobile_push_send_results_total{provider="fcm_v1",outcome="accepted"}',
            'atermius_mobile_push_send_results_total{provider="fcm_v1",outcome="invalid_token"}',
            'atermius_mobile_push_send_results_total{provider="fcm_v1",outcome="retryable_failure"}',
            "atermius_backup_last_success_timestamp_seconds",
            "atermius_vault_quota_bytes",
            "atermius_ssh_relay_enabled",
        }
        parsed: dict[str, int] = {}
        for line in samples:
            match = re.fullmatch(r'(atermius_[a-z_]+(?:\{[^}\n]+\})?) ([0-9]+)', line)
            _require(match is not None, "PG metrics exposition contained a malformed or nonnumeric sample")
            assert match is not None
            _require(match.group(1) not in parsed, "PG metrics exposition repeated a sample series")
            parsed[match.group(1)] = int(match.group(2))
        _require(
            len(samples) == 20 and set(parsed) == expected_series,
            "PG metrics exposition must contain exactly the fixed aggregate sample set",
        )
        _require(
            "reset on process restart" in exposition
            and "not device receipt or sync" in exposition,
            "push send metric must document process-local and provider-only semantics",
        )
        expected_families = {series.split("{", 1)[0] for series in expected_series}
        help_families = {
            line.split(" ", 3)[2]
            for line in exposition.splitlines()
            if line.startswith("# HELP ")
        }
        type_families = {
            line.split(" ", 3)[2]
            for line in exposition.splitlines()
            if line.startswith("# TYPE ")
        }
        actual_types = {
            line.split(" ", 3)[2]: line.split(" ", 3)[3]
            for line in exposition.splitlines()
            if line.startswith("# TYPE ")
        }
        expected_types = {
            family: "counter"
            if family == "atermius_mobile_push_send_results_total"
            else "gauge"
            for family in expected_families
        }
        _require(
            help_families == type_families == expected_families
            and actual_types == expected_types,
            "PG metrics must describe fixed aggregate families with matching gauge/counter types",
        )
        return parsed

    def expected_metric_values() -> dict[str, int]:
        counts = database.execute(
            "SELECT "
            "(SELECT COUNT(*) FROM users WHERE status='active'),"
            "(SELECT COUNT(*) FROM users WHERE status='deleting'),"
            "(SELECT COUNT(*) FROM users WHERE status='disabled'),"
            "(SELECT COUNT(*) FROM devices d JOIN users u ON u.user_id=d.user_id "
            " WHERE d.status='active' AND u.status='active'),"
            "(SELECT COUNT(*) FROM vaults WHERE state='active'),"
            "(SELECT COUNT(*) FROM vaults WHERE state='deleting'),"
            "(SELECT COALESCE(SUM(size),0)::BIGINT FROM blob_objects),"
            "(SELECT COALESCE(SUM(expected_size),0)::BIGINT FROM uploads "
            " WHERE state='open' AND expires_at>clock_timestamp()),"
            "(SELECT COUNT(*) FROM object_delete_queue WHERE state='pending'),"
            "(SELECT COUNT(*) FROM object_delete_queue WHERE state='retry_wait'),"
            "(SELECT COUNT(*) FROM object_delete_queue WHERE state='quarantined'),"
            "(SELECT COALESCE(SUM(quota_bytes),0)::BIGINT FROM vaults "
            " WHERE state IN ('active','deleting'))"
        ).fetchone()
        keys = (
            'atermius_accounts{status="active"}',
            'atermius_accounts{status="deleting"}',
            'atermius_accounts{status="disabled"}',
            "atermius_devices_active",
            'atermius_vaults{state="active"}',
            'atermius_vaults{state="deleting"}',
            "atermius_blob_stored_bytes",
            "atermius_upload_reserved_bytes",
            'atermius_object_delete_queue{state="pending"}',
            'atermius_object_delete_queue{state="retry_wait"}',
            'atermius_object_delete_queue{state="quarantined"}',
            "atermius_vault_quota_bytes",
        )
        return {
            **{key: int(value) for key, value in zip(keys, counts, strict=True)},
            "atermius_backup_last_success_timestamp_seconds": 0,
            "atermius_ssh_relay_enabled": 0,
        }

    first_rotation = node_a.request("POST", credential_path, token=admin.access_token)
    first_body = first_rotation.json()
    first_credential = first_body.get("credential") if isinstance(first_body, dict) else None
    _require(
        first_rotation.status == 200
        and isinstance(first_body, dict)
        and set(first_body) == {"credential", "created_at"}
        and isinstance(first_credential, str)
        and re.fullmatch(r"atm_[A-Za-z0-9_-]{43}", first_credential) is not None
        and isinstance(first_body.get("created_at"), str),
        "PG credential creation must return a single well-formed one-time token",
    )
    assert isinstance(first_credential, str)
    pg_http_world.remember_secret(first_credential)
    verifier_row = database.execute(
        "SELECT credential_id,verifier,created_at,updated_at "
        "FROM instance_metrics_credential WHERE credential_id=1"
    ).fetchone()
    rate_key = (pg_http_world.root / "shared" / "auth-rate-limit.key").read_bytes()
    expected_verifier = hmac.new(
        rate_key,
        b"atermius/admin-metrics-credential/v1\0" + first_credential.encode("ascii"),
        hashlib.sha256,
    ).digest()
    _require(
        verifier_row is not None
        and verifier_row[0] == 1
        and bytes(verifier_row[1]) == expected_verifier
        and len(bytes(verifier_row[1])) == 32
        and first_credential.encode("ascii") != bytes(verifier_row[1]),
        "PG must persist only the expected server-keyed 32-byte verifier, never the cleartext token",
    )

    first_status_a = status(node_a, admin.access_token)
    first_status_b = status(node_b, admin.access_token)
    _require(
        first_status_a.status == first_status_b.status == 200
        and first_status_a.json().get("active") is True
        and first_status_a.json() == first_status_b.json()
        and first_status_b.json().get("updated_at") == first_body.get("created_at"),
        "credential rotation on node A must become visible from node B",
    )

    first_metrics = node_b.request("GET", metrics_path, token=first_credential)
    first_samples = verify_metrics_contract(first_metrics)
    expected_database_samples = expected_metric_values()
    local_push_result_samples = {
        key: value
        for key, value in first_samples.items()
        if key.startswith("atermius_mobile_push_send_results_total{")
    }
    _require(
        all(
            first_samples[key] == expected_value
            for key, expected_value in expected_database_samples.items()
        )
        and len(local_push_result_samples) == 6
        and all(value >= 0 for value in local_push_result_samples.values()),
        "PG scrape must preserve database aggregates and expose six nonnegative node-local push counters",
    )
    exposition_lower = first_metrics.body.decode("utf-8").lower()
    _require(
        all(
            value.lower() not in exposition_lower
            for value in (
                PG_ADMIN_METRICS_USERNAME,
                admin.user_id,
                admin_tenant.vault_id,
                outsider.user_id,
                first_credential,
                "username",
                "vault_id",
                "device_id",
                "envelope",
            )
        ),
        "PG metrics exposition disclosed identity, credential, or client metadata",
    )

    credential_scoped_denials = [
        node_b.request("GET", "/api/v1/admin/overview", token=first_credential),
        node_b.request("GET", credential_path, token=first_credential),
        node_a.request("POST", credential_path, token=first_credential),
        node_b.request("DELETE", credential_path, token=first_credential),
    ]
    _require(
        all(
            response.status == 401 and _error_code(response) == "AUTH_REQUIRED"
            for response in credential_scoped_denials
        )
        and node_b.request("GET", metrics_path, token=first_credential).status == 200,
        "the scrape credential must be accepted only by GET metrics, never admin overview or management",
    )

    malformed_body_rotation = node_a.request(
        "POST", credential_path, token=admin.access_token, json_body={}
    )
    malformed_body_revoke = node_b.request(
        "DELETE", credential_path, token=admin.access_token, body=b"unexpected"
    )
    _require(
        malformed_body_rotation.status == malformed_body_revoke.status == 400
        and _error_code(malformed_body_rotation) == _error_code(malformed_body_revoke) == "INVALID_REQUEST"
        and node_b.request("GET", metrics_path, token=first_credential).status == 200,
        "nonempty credential-management bodies must be rejected without changing the active credential",
    )

    second_rotation = node_b.request("POST", credential_path, token=admin.access_token)
    second_body = second_rotation.json()
    second_credential = second_body.get("credential") if isinstance(second_body, dict) else None
    _require(
        second_rotation.status == 200
        and isinstance(second_body, dict)
        and set(second_body) == {"credential", "created_at"}
        and isinstance(second_credential, str)
        and re.fullmatch(r"atm_[A-Za-z0-9_-]{43}", second_credential) is not None,
        "PG credential rotation on node B must return a fresh one-time token",
    )
    assert isinstance(second_credential, str)
    pg_http_world.remember_secret(second_credential)
    second_status_a = status(node_a, admin.access_token)
    second_status_b = status(node_b, admin.access_token)
    _require(
        second_status_a.status == second_status_b.status == 200
        and second_status_a.json() == second_status_b.json()
        and second_status_a.json().get("updated_at") == second_body.get("created_at")
        and all(
            node.request("GET", metrics_path, token=first_credential).status == 401
            and node.request("GET", metrics_path, token=second_credential).status == 200
            for node in (node_a, node_b)
        ),
        "rotation on node B must invalidate the prior token and activate the new token on both nodes",
    )

    revoked_a = node_a.request("DELETE", credential_path, token=admin.access_token)
    revoked_b = node_b.request("DELETE", credential_path, token=admin_tenant.actors[1].access_token)
    final_status_a = status(node_a, admin.access_token)
    final_status_b = status(node_b, admin.access_token)
    _require(
        revoked_a.status == revoked_b.status == 200
        and revoked_a.json() == revoked_b.json() == {"revoked": True}
        and final_status_a.status == final_status_b.status == 200
        and final_status_a.json() == final_status_b.json() == {"active": False, "updated_at": None}
        and all(
            node.request("GET", metrics_path, token=second_credential).status == 401
            for node in (node_a, node_b)
        ),
        "revocation through either PG node must be idempotent and immediately invalidate the shared token",
    )

    audit_rows = database.execute(
        "SELECT action,actor_user_id,actor_device_id,resource_type,resource_id,source,result "
        "FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND action IN ('admin.metrics_credential_rotated','admin.metrics_credential_revoked') "
        "ORDER BY event_id",
        (admin.user_id,),
    ).fetchall()
    _require(
        len(audit_rows) == 3
        and [row[0] for row in audit_rows]
        == [
            "admin.metrics_credential_rotated",
            "admin.metrics_credential_rotated",
            "admin.metrics_credential_revoked",
        ]
        and all(
            row[1] == admin.user_id
            and row[2] == admin.device_id
            and row[3] == "metrics_credential"
            and row[4] is None
            and row[5] == "api"
            and row[6] == "success"
            for row in audit_rows
        )
        and first_credential not in json.dumps(audit_rows)
        and second_credential not in json.dumps(audit_rows),
        "PG credential lifecycle must audit two rotations and one successful revoke without secret material",
    )

    for method, path in (
        ("POST", metrics_path),
        ("DELETE", metrics_path),
        ("GET", metrics_path + "/"),
        ("GET", metrics_path + "/extra"),
        ("PUT", credential_path),
        ("GET", credential_path + "/"),
        ("GET", credential_path + "/extra"),
    ):
        blocked = node_a.request(method, path, token=admin.access_token)
        _require(
            blocked.status == 503 and _error_code(blocked) == "PG_SYNC_SCOPE_LIMITED",
            "PG metrics routes must reject unsupported methods and noncanonical paths exactly",
        )
    pg_http_world.assert_secrets_not_in_local_files()


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_PUSH_HEALTH_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_push_health_is_shared_exact_and_privacy_safe(
    pg_http_world: PgHttpWorld,
    tmp_path: Path,
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-push-health-admin")
    admin = admin_tenant.actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_PUSH_HEALTH_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-push-health-outsider").actors[0]

    unauthenticated = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/push-health"
    )
    denied = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/push-health", token=outsider.access_token
    )
    _require(
        unauthenticated.status == 401
        and denied.status == 403
        and _error_code(denied) == "INSTANCE_ADMIN_REQUIRED",
        "PostgreSQL push health must require an active admin session",
    )

    now = database.execute(
        "SELECT floor(extract(epoch FROM clock_timestamp()))::BIGINT"
    ).fetchone()[0]
    private_values: list[str] = []

    def add_device(user_id: str, marker: str, *, status: str = "active") -> str:
        device_id = str(uuid.uuid4())
        database.execute(
            "INSERT INTO devices(device_id,user_id,name,signing_public_key,"
            "encryption_public_key,status) VALUES (%s,%s,%s,%s,%s,%s)",
            (device_id, user_id, "push-health-" + marker, "sign-" + marker, "encrypt-" + marker, status),
        )
        private_values.extend([device_id, "sign-" + marker, "encrypt-" + marker])
        return device_id

    def add_endpoint(
        provider: str,
        marker: str,
        state: str | None = None,
        *,
        user_id: str | None = None,
        device_id: str | None = None,
    ) -> None:
        selected_user = user_id or admin.user_id
        selected_device = device_id or add_device(selected_user, marker)
        endpoint_id = str(uuid.uuid4())
        token_hash = hashlib.sha256(("pg-push-health-token-" + marker).encode()).hexdigest()
        token_envelope = "pg-private-envelope-" + marker.ljust(96, "x")
        database.execute(
            "INSERT INTO notification_push_endpoints "
            "(endpoint_id,device_id,user_id,provider,token_hash,token_envelope,created_at,updated_at) "
            "VALUES (%s,%s,%s,%s,%s,%s,%s,%s)",
            (endpoint_id, selected_device, selected_user, provider, token_hash, token_envelope, now, now),
        )
        private_values.extend([endpoint_id, token_hash, token_envelope])
        if state is None:
            return
        requested = 2 if state == "complete" else 1
        delivered = 2 if state == "complete" else 0
        next_attempt = now + 600 if state == "retry" else now - 10
        lease_id = None
        lease_until = None
        dead_lettered = False
        if state == "leased":
            lease_id, lease_until = "pg-lease-" + marker, now + 600
        elif state == "expired_lease":
            lease_id, lease_until = "pg-lease-" + marker, now - 1
        elif state == "dead":
            dead_lettered = True
        database.execute(
            "INSERT INTO notification_push_outbox "
            "(endpoint_id,requested_seq,delivered_seq,attempt_count,next_attempt_at,lease_id,lease_until,dead_lettered,updated_at) "
            "VALUES (%s,%s,%s,0,%s,%s,%s,%s,%s)",
            (endpoint_id, requested, delivered, next_attempt, lease_id, lease_until, dead_lettered, now),
        )

    add_endpoint("apns", "due", "due", device_id=admin.device_id)
    add_endpoint("apns", "expired", "expired_lease")
    add_endpoint("apns", "leased", "leased")
    add_endpoint("apns", "retry", "retry")
    add_endpoint("apns", "dead", "dead")
    add_endpoint("apns", "complete", "complete")
    add_endpoint("apns", "registered-only")
    disabled_user = str(uuid.uuid4())
    database.execute(
        "INSERT INTO users(user_id,username,status) VALUES (%s,%s,'disabled')",
        (disabled_user, disabled_user + "@example.test"),
    )
    disabled_device = add_device(disabled_user, "disabled-account")
    disabled_marker = "disabled-account-due-private-marker"
    private_values.extend([disabled_user, disabled_marker])
    add_endpoint(
        "apns", disabled_marker, "due", user_id=disabled_user, device_id=disabled_device
    )
    inactive_device = add_device(admin.user_id, "inactive-device", status="revoked")
    add_endpoint(
        "apns",
        "inactive-device-due-private-marker",
        "due",
        device_id=inactive_device,
    )
    add_endpoint("fcm_v1", "fcm-due", "due", device_id=admin.device_id)
    add_endpoint("fcm_v1", "fcm-registered-only")
    today_start = now // 86400 * 86400
    with database.cursor() as cursor:
        cursor.executemany(
            "INSERT INTO notification_push_delivery_daily(provider,outcome,day_start,count) VALUES (%s,%s,%s,%s)",
            [
                ("apns", "accepted", today_start, 5),
                ("apns", "accepted", today_start - 6 * 86400, 3),
                ("apns", "invalid_token", today_start, 1),
                ("apns", "retryable_failure", today_start, 2),
                ("apns", "accepted", today_start - 7 * 86400, 99),
                ("fcm_v1", "retryable_failure", today_start, 4),
            ],
        )

    def push_row_fingerprint() -> str:
        rows = {
            "endpoints": database.execute(
                "SELECT * FROM notification_push_endpoints ORDER BY endpoint_id"
            ).fetchall(),
            "outbox": database.execute(
                "SELECT * FROM notification_push_outbox ORDER BY endpoint_id"
            ).fetchall(),
            "delivery_daily": database.execute(
                "SELECT * FROM notification_push_delivery_daily ORDER BY provider,outcome,day_start"
            ).fetchall(),
        }
        encoded = json.dumps(rows, sort_keys=True, default=str, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    row_counts_before = database.execute(
        "SELECT (SELECT COUNT(*) FROM notification_push_endpoints), "
        "(SELECT COUNT(*) FROM notification_push_outbox), "
        "(SELECT COUNT(*) FROM notification_push_delivery_daily)"
    ).fetchone()
    row_fingerprint_before = push_row_fingerprint()

    first = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/push-health", token=admin.access_token
    )
    peer = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/push-health", token=admin.access_token
    )
    _require(
        first.status == peer.status == 200,
        "both PostgreSQL nodes must serve the shared admin push snapshot",
    )
    body = first.json()
    peer_body = peer.json()
    expected_keys = {
        "provider",
        "configured",
        "registered_endpoints",
        "due",
        "retry_waiting",
        "leased",
        "dead_lettered",
        "delivery_results",
    }
    expected_counts = [
        {
            "registered_endpoints": 9,
            "due": 4,
            "retry_waiting": 1,
            "leased": 1,
            "dead_lettered": 1,
            "delivery_results": {"accepted": 8, "invalid_token": 1, "retryable_failure": 2},
        },
        {
            "registered_endpoints": 2,
            "due": 1,
            "retry_waiting": 0,
            "leased": 0,
            "dead_lettered": 0,
            "delivery_results": {"accepted": 0, "invalid_token": 0, "retryable_failure": 4},
        },
    ]
    generated_at = datetime.fromisoformat(body["generated_at"].replace("Z", "+00:00"))
    database_now = database.execute(
        "SELECT floor(extract(epoch FROM clock_timestamp()))::BIGINT"
    ).fetchone()[0]
    _require(
        isinstance(body, dict)
        and set(body) == {"generated_at", "delivery_window", "providers"}
        and body["delivery_window"]["days"] == 7
        and body["delivery_window"]["start_date_utc"]
        == datetime.fromtimestamp(today_start - 6 * 86400, tz=timezone.utc).date().isoformat()
        and body["delivery_window"]["end_date_utc"]
        == datetime.fromtimestamp(today_start, tz=timezone.utc).date().isoformat()
        and isinstance(body.get("providers"), list)
        and len(body["providers"]) == 2
        and [item.get("provider") for item in body["providers"]] == ["apns", "fcm_v1"]
        and all(set(item) == expected_keys for item in body["providers"])
        and body["providers"] == peer_body.get("providers")
        and [
            {key: item[key] for key in expected_counts[index]}
            for index, item in enumerate(body["providers"])
        ]
        == expected_counts
        and all(item["configured"] is False for item in body["providers"]),
        "PostgreSQL snapshot must include exact shared counters and process-local adapter state",
    )
    _require(
        all(
            type(item[key]) is int and item[key] >= 0
            for item in body["providers"]
            for key in ("registered_endpoints", "due", "retry_waiting", "leased", "dead_lettered")
        )
        and all(
            set(item["delivery_results"]) == {"accepted", "invalid_token", "retryable_failure"}
            and all(type(value) is int and value >= 0 for value in item["delivery_results"].values())
            for item in body["providers"]
        )
        and abs(int(generated_at.timestamp()) - database_now) <= 3,
        "PostgreSQL push counters must be nonnegative and use an ISO database timestamp",
    )
    serialized = json.dumps(body).lower()
    _require(
        all(value.lower() not in serialized for value in private_values)
        and "token_hash" not in serialized
        and "token_envelope" not in serialized
        and "token_value" not in serialized
        and "payload" not in serialized
        and "project_id" not in serialized
        and "error_body" not in serialized,
        "PostgreSQL push snapshot must not expose endpoint, token, or provider details",
    )
    row_counts_after = database.execute(
        "SELECT (SELECT COUNT(*) FROM notification_push_endpoints), "
        "(SELECT COUNT(*) FROM notification_push_outbox), "
        "(SELECT COUNT(*) FROM notification_push_delivery_daily)"
    ).fetchone()
    row_fingerprint_after = push_row_fingerprint()
    _require(
        row_counts_after == row_counts_before
        and row_fingerprint_after == row_fingerprint_before,
        "read-only PostgreSQL push-health requests must not modify registration or queue rows",
    )

    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        ("former-push-health-admin@example.test", admin.user_id),
    )
    removed_from_allowlist = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/push-health", token=admin.access_token
    )
    _require(
        removed_from_allowlist.status == 403
        and _error_code(removed_from_allowlist) == "INSTANCE_ADMIN_REQUIRED",
        "push-health must recheck current PG admin allowlist on each node",
    )
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_PUSH_HEALTH_USERNAME, admin.user_id),
    )
    for method, path in (
        ("POST", "/api/v1/admin/push-health"),
        ("DELETE", "/api/v1/admin/push-health"),
        ("GET", "/api/v1/admin/push-health/"),
        ("GET", "/api/v1/admin/push-health/extra"),
    ):
        blocked = pg_http_world.clients[0].request(method, path, token=admin.access_token)
        _require(
            blocked.status == 503 and _error_code(blocked) == "PG_SYNC_SCOPE_LIMITED",
            "restricted PostgreSQL admin route guard must reject adjacent unsupported push-health paths/methods",
        )


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_ACCOUNTS_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_account_and_session_reads_are_shared_and_revalidated(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-accounts-admin")
    admin = admin_tenant.actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_ACCOUNTS_USERNAME, admin.user_id),
    )
    target = pg_http_world.seed_tenant(tmp_path / "pg-admin-accounts-target")
    target_user = target.actors[0].user_id
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-accounts-outsider").actors[0]

    no_auth = pg_http_world.clients[0].request("GET", "/api/v1/admin/accounts")
    denied = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/accounts", token=outsider.access_token
    )
    denied_sessions = pg_http_world.clients[0].request(
        "GET",
        f"/api/v1/admin/accounts/{target_user}/sessions",
        token=outsider.access_token,
    )
    _require(
        no_auth.status == 401
        and denied.status == denied_sessions.status == 403
        and _error_code(denied) == _error_code(denied_sessions) == "INSTANCE_ADMIN_REQUIRED",
        "PG account and session listings must require a live allowlisted administrator",
    )

    page_one = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/accounts?limit=1&offset=0", token=admin.access_token
    )
    all_accounts = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/accounts?limit=100&offset=0", token=admin.access_token
    )
    all_accounts_peer = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/accounts?limit=100&offset=0", token=admin.access_token
    )
    _require(
        page_one.status == all_accounts.status == 200,
        "both PostgreSQL nodes must serve bounded account pages",
    )
    first_body, all_body = page_one.json(), all_accounts.json()
    _require(
        isinstance(first_body, dict)
        and set(first_body) == {"accounts", "total", "limit", "offset"}
        and first_body["limit"] == 1
        and first_body["offset"] == 0
        and len(first_body["accounts"]) == 1
        and isinstance(all_body, dict)
        and set(all_body) == {"accounts", "total", "limit", "offset"}
        and all_body["limit"] == 100
        and all_body["offset"] == 0
        and len(all_body["accounts"]) == all_body["total"]
        and all_body["total"] >= 3
        and all_accounts_peer.status == 200
        and all_accounts_peer.json() == all_body,
        "account pagination must follow the existing fixed response contract",
    )
    accounts = all_body["accounts"]
    target_rows = [row for row in accounts if row["user_id"] == target_user]
    _require(
        len(target_rows) == 1
        and set(target_rows[0])
        == {
            "user_id",
            "username",
            "status",
            "created_at",
            "active_device_count",
            "active_session_count",
        }
        and target_rows[0]["status"] == "active"
        and target_rows[0]["active_device_count"] == 2
        and target_rows[0]["active_session_count"] == 2,
        "account projection must include only its documented metadata and live counts",
    )
    _require(
        page_one.json()["total"] == all_accounts.json()["total"]
        and page_one.json()["accounts"][0]
        == pg_http_world.clients[1].request(
            "GET", "/api/v1/admin/accounts?limit=1&offset=0", token=admin.access_token
        ).json()["accounts"][0],
        "the account list and page boundary must be shared across PG nodes",
    )

    sessions_a = pg_http_world.clients[0].request(
        "GET",
        f"/api/v1/admin/accounts/{target_user}/sessions?limit=1&offset=0",
        token=admin.access_token,
    )
    sessions_b = pg_http_world.clients[1].request(
        "GET",
        f"/api/v1/admin/accounts/{target_user}/sessions?limit=100&offset=0",
        token=admin.access_token,
    )
    _require(
        sessions_a.status == sessions_b.status == 200,
        "both PostgreSQL nodes must serve account session pages",
    )
    sessions_page, sessions_all = sessions_a.json(), sessions_b.json()
    _require(
        set(sessions_all) == {"sessions", "total", "limit", "offset"}
        and sessions_all["total"] == 2
        and sessions_all["limit"] == 100
        and sessions_all["offset"] == 0
        and len(sessions_all["sessions"]) == 2
        and sessions_page["total"] == sessions_all["total"]
        and sessions_page["limit"] == 1
        and len(sessions_page["sessions"]) == 1,
        "session pagination must be bounded and consistent across nodes",
    )
    session = sessions_all["sessions"][0]
    _require(
        set(session)
        == {
            "session_id",
            "device_id",
            "device_name",
            "created_at",
            "access_expires_at",
            "refresh_expires_at",
            "revoked_at",
            "active",
        }
        and session["active"] is True
        and session["revoked_at"] is None
        and all(row["active"] is True for row in sessions_all["sessions"]),
        "session projection must contain only safe session/device metadata",
    )
    account_text = json.dumps(all_body).lower()
    session_text = json.dumps(sessions_all).lower()
    _require(
        PG_ADMIN_ACCOUNTS_USERNAME not in session_text
        and target_user not in session_text
        and target.vault_id not in account_text + session_text
        and not any(
            marker in account_text + session_text
            for marker in (
                "access_hash",
                "refresh_hash",
                "account_key_envelope",
                "login_verifier",
                "signing_public_key",
                "ciphertext",
                "vault_id",
            )
        ),
        "account and session projections must not expose credentials, Vault IDs, or client data",
    )

    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        ("former-pg-admin-accounts@example.test", admin.user_id),
    )
    removed_from_allowlist = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/accounts", token=admin.access_token
    )
    _require(
        removed_from_allowlist.status == 403
        and _error_code(removed_from_allowlist) == "INSTANCE_ADMIN_REQUIRED",
        "the PG account-list handler must revalidate the live admin allowlist",
    )
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_ACCOUNTS_USERNAME, admin.user_id),
    )
    revoked_session = pg_http_world.clients[0].request(
        "POST", "/api/v1/auth/logout", token=admin.access_token
    )
    rejected_session = pg_http_world.clients[1].request(
        "GET", f"/api/v1/admin/accounts/{target_user}/sessions", token=admin.access_token
    )
    _require(
        revoked_session.status == 200
        and rejected_session.status == 401
        and _error_code(rejected_session) == "AUTH_REQUIRED",
        "revoking the acting session must immediately remove list access across nodes",
    )

    for method, path in (
        ("POST", "/api/v1/admin/accounts"),
        ("GET", "/api/v1/admin/accounts/"),
        ("GET", f"/api/v1/admin/accounts/{target_user}/sessions/"),
        ("GET", f"/api/v1/admin/accounts/{target_user}/sessions/extra"),
        ("POST", f"/api/v1/admin/accounts/{target_user}/sessions"),
        ("GET", f"/api/v1/admin/accounts/{target_user}/status"),
        ("PUT", f"/api/v1/admin/accounts/{target_user}/status/"),
        ("PUT", f"/api/v1/admin/accounts/{target_user}/sessions/revoke"),
        ("GET", f"/api/v1/admin/accounts/{target_user}/sessions/revoke"),
        (
            "POST",
            f"/api/v1/admin/accounts/{target_user}/sessions/{admin.session_id}/revoke/",
        ),
    ):
        blocked = pg_http_world.clients[0].request(method, path, token=admin.access_token)
        _require(
            blocked.status == 503 and _error_code(blocked) == "PG_SYNC_SCOPE_LIMITED",
            "only canonical account listing and mutation routes may pass the PG route guard",
        )


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_ACCOUNT_INVITATIONS_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_account_invitations_are_shared_private_and_atomic(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin = pg_http_world.seed_tenant(tmp_path / "pg-admin-invitations-admin").actors[0]
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-invitations-outsider").actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_ACCOUNT_INVITATIONS_USERNAME, admin.user_id),
    )
    database.execute(
        "UPDATE instance_meta SET setup_consumed_at=COALESCE(setup_consumed_at,clock_timestamp()) "
        "WHERE id=1"
    )

    no_auth = pg_http_world.clients[0].request("GET", "/api/v1/admin/account-invitations")
    outsider_read = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/account-invitations", token=outsider.access_token
    )
    outsider_write = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/account-invitations",
        token=outsider.access_token,
        json_body={"username": "outsider@example.test"},
    )
    _require(
        no_auth.status == 401
        and outsider_read.status == outsider_write.status == 403
        and _error_code(outsider_read) == _error_code(outsider_write) == "INSTANCE_ADMIN_REQUIRED",
        "PG invitation routes must require the live allowlisted administrator",
    )

    for query, code in (
        ("limit=0", "INVALID_LIMIT"),
        ("limit=101", "INVALID_LIMIT"),
        ("offset=-1", "INVALID_OFFSET"),
        ("offset=1000001", "INVALID_OFFSET"),
    ):
        invalid_page = pg_http_world.clients[0].request(
            "GET", f"/api/v1/admin/account-invitations?{query}", token=admin.access_token
        )
        _require(invalid_page.status == 400 and _error_code(invalid_page) == code,
                 "PG invitation pagination must retain the bounded page contract")
    for ttl in (59, 2_592_001, -1):
        invalid_ttl = pg_http_world.clients[0].request(
            "POST",
            "/api/v1/admin/account-invitations",
            token=admin.access_token,
            json_body={"username": f"bad-ttl-{uuid.uuid4().hex}@example.test", "expires_in_seconds": ttl},
        )
        _require(
            invalid_ttl.status == 400 and _error_code(invalid_ttl) == "INVALID_INVITATION_TTL",
            "PG invitation TTL must preserve the 60-second to 30-day bound",
        )
    invalid_username = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/account-invitations",
        token=admin.access_token,
        json_body={"username": "not-an-account-name"},
    )
    strict_body = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/account-invitations",
        token=admin.access_token,
        json_body={"username": "strict@example.test", "unexpected": True},
    )
    _require(
        invalid_username.status == 400
        and _error_code(invalid_username) == "INVALID_USERNAME"
        and strict_body.status == 400,
        "PG invitation input must retain strict username/body validation",
    )

    normalized = f"pg-admin-invite-{uuid.uuid4().hex}@example.test"
    first = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/account-invitations",
        token=admin.access_token,
        json_body={"username": f"  {normalized.upper()}  ", "expires_in_seconds": 3600},
    )
    first_invitation = (first.json() or {}).get("invitation")
    _require(
        first.status == 201
        and isinstance(first_invitation, dict)
        and set(first_invitation) == {"invitation_id", "username", "created_at", "expires_at", "token"}
        and first_invitation["username"] == normalized
        and first_invitation["expires_at"] > first_invitation["created_at"],
        "node A must issue a normalized invitation with a one-time token receipt "
        f"(status={first.status}, error={_error_code(first)})",
    )
    first_token = first_invitation["token"]
    pg_http_world.remember_secret(first_token)
    first_hash = hashlib.sha256(first_token.encode("ascii")).hexdigest()
    pg_http_world.remember_secret(first_hash)
    stored = database.execute(
        "SELECT token_hash,username,consumed_at,revoked_at FROM account_invitations WHERE invitation_id=%s",
        (first_invitation["invitation_id"],),
    ).fetchone()
    _require(
        stored == (first_hash, normalized, None, None),
        "PG invitation storage must retain only the hash and normalized username",
    )

    page = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/account-invitations?limit=1&offset=0", token=admin.access_token
    )
    page_peer = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/account-invitations?limit=100&offset=0", token=admin.access_token
    )
    page_other_node = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/account-invitations?limit=100&offset=0", token=admin.access_token
    )
    _require(
        page.status == page_peer.status == page_other_node.status == 200
        and page.json()["limit"] == 1
        and page.json()["offset"] == 0
        and len(page.json()["invitations"]) == 1
        and page_peer.json() == page_other_node.json()
        and page_peer.json()["total"] == len(page_peer.json()["invitations"]),
        "invitation pagination and ordering must be identical across PG nodes",
    )
    page_text = json.dumps(page_peer.json()).lower()
    _require(
        all(
            set(row) == {"invitation_id", "username", "created_at", "expires_at", "status"}
            for row in page_peer.json()["invitations"]
        )
        and first_token not in page_text
        and first_hash not in page_text
        and "token_hash" not in page_text,
        "list DTOs must omit the token, token hash and private invitation fields",
    )

    replacement = pg_http_world.clients[1].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": normalized},
    )
    replacement_invitation = (replacement.json() or {}).get("invitation")
    _require(
        replacement.status == 201 and isinstance(replacement_invitation, dict),
        "node B must reissue an invitation for the same unregistered username",
    )
    replacement_token = replacement_invitation["token"]
    pg_http_world.remember_secret(replacement_token)
    old_revoked_at = database.execute(
        "SELECT revoked_at FROM account_invitations WHERE invitation_id=%s",
        (first_invitation["invitation_id"],),
    ).fetchone()[0]
    _require(old_revoked_at is not None, "reissue must revoke every previous live token")

    def registration(username: str, token: str, label: str):
        return _registration_request(
            pg_http_world,
            tmp_path / label,
            username,
            invitation_token=token,
        )

    stale_request, _, _, _, _ = registration(normalized, first_token, "pg-admin-invitations-stale")
    stale = pg_http_world.clients[0].request(
        "POST", "/api/v1/auth/register", json_body=stale_request
    )
    _require(
        stale.status == 401 and _error_code(stale) == "ACCOUNT_INVITATION_INVALID",
        "the superseded token must fail on the second service node",
    )
    _assert_failed_registration_absent(
        pg_http_world, stale_request, label="superseded admin invitation"
    )

    accepted_request, signer, verifier, device_id, _ = registration(
        normalized, replacement_token, "pg-admin-invitations-accepted"
    )
    accepted = pg_http_world.clients[1].request(
        "POST", "/api/v1/auth/register", json_body=accepted_request
    )
    _require(accepted.status in (200, 201), "an API-issued token must authorize PG registration")
    accepted_actor = _registered_actor(
        pg_http_world, accepted_request, accepted, signer, verifier, device_id
    )
    consumed = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/account-invitations?limit=100", token=admin.access_token
    )
    consumed_row = next(
        row for row in consumed.json()["invitations"]
        if row["invitation_id"] == replacement_invitation["invitation_id"]
    )
    _require(
        consumed_row["status"] == "consumed"
        and database.execute(
            "SELECT consumed_user_id FROM account_invitations WHERE invitation_id=%s",
            (replacement_invitation["invitation_id"],),
        ).fetchone()[0] == accepted_actor.user_id,
        "registration and invitation consumption must commit together across nodes",
    )
    taken = pg_http_world.clients[0].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": normalized},
    )
    _require(taken.status == 409 and _error_code(taken) == "USERNAME_TAKEN",
             "an existing PG username must not receive another invitation")

    revocable_username = f"pg-admin-revoke-{uuid.uuid4().hex}@example.test"
    revocable = pg_http_world.clients[0].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": revocable_username},
    )
    revocable_invitation = revocable.json()["invitation"]
    pg_http_world.remember_secret(revocable_invitation["token"])
    revoke_path = f"/api/v1/admin/account-invitations/{revocable_invitation['invitation_id']}/revoke"
    revoked = pg_http_world.clients[0].request("POST", revoke_path, token=admin.access_token)
    repeated = pg_http_world.clients[1].request("POST", revoke_path, token=admin.access_token)
    _require(
        revoked.status == repeated.status == 200
        and revoked.json() == repeated.json()
        and revoked.json()["status"] == "revoked",
        "single-invitation revoke must return the same receipt on retry across nodes",
    )
    revocable_hash = hashlib.sha256(revocable_invitation["token"].encode("ascii")).hexdigest()
    pg_http_world.remember_secret(revocable_hash)
    revoke_audits = database.execute(
        "SELECT count(*) FROM audit_events WHERE actor_user_id=%s AND action="
        "'instance.account_invitation_revoked' AND resource_type='account_invitation'",
        (admin.user_id,),
    ).fetchone()[0]
    audit_text = json.dumps(
        database.execute(
            "SELECT action,actor_user_id,actor_device_id,resource_type,resource_id,source "
            "FROM audit_events WHERE actor_user_id=%s AND action LIKE %s",
            (admin.user_id, "instance.account_invitation_%"),
        ).fetchall()
    )
    _require(
        revoke_audits == 2
        and revocable_hash not in audit_text
        and revocable_invitation["invitation_id"] not in audit_text,
        "issue/reissue/revoke audit rows must not expose tokens, hashes or raw invitation IDs",
    )
    revoked_request, _, _, _, _ = registration(
        revocable_username, revocable_invitation["token"], "pg-admin-invitations-revoked"
    )
    rejected_revoked = pg_http_world.clients[1].request(
        "POST", "/api/v1/auth/register", json_body=revoked_request
    )
    _require(
        rejected_revoked.status == 401
        and _error_code(rejected_revoked) == "ACCOUNT_INVITATION_INVALID",
        "a revoked invitation must not authorize registration on another node",
    )
    _assert_failed_registration_absent(
        pg_http_world, revoked_request, label="revoked admin invitation"
    )

    expired_username = f"pg-admin-expired-{uuid.uuid4().hex}@example.test"
    expired = pg_http_world.clients[0].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": expired_username, "expires_in_seconds": 3600},
    )
    expired_invitation = expired.json()["invitation"]
    database.execute(
        "UPDATE account_invitations SET expires_at=clock_timestamp()-INTERVAL '1 second' "
        "WHERE invitation_id=%s",
        (expired_invitation["invitation_id"],),
    )
    expired_page = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/account-invitations?limit=100", token=admin.access_token
    )
    expired_row = next(
        row for row in expired_page.json()["invitations"]
        if row["invitation_id"] == expired_invitation["invitation_id"]
    )
    expired_revoke = pg_http_world.clients[0].request(
        "POST",
        f"/api/v1/admin/account-invitations/{expired_invitation['invitation_id']}/revoke",
        token=admin.access_token,
    )
    _require(
        expired_row["status"] == "expired"
        and expired_revoke.status == 409
        and _error_code(expired_revoke) == "ACCOUNT_INVITATION_NOT_PENDING",
        "PostgreSQL clock must determine expiry and revoke eligibility",
    )

    rollback_username = f"pg-admin-rollback-{uuid.uuid4().hex}@example.test"
    database.execute(
        "ALTER TABLE audit_events ADD CONSTRAINT pg_admin_invite_audit_fail "
        "CHECK (action <> 'instance.account_invitation_issued') NOT VALID"
    )
    failed_issue = pg_http_world.clients[0].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": rollback_username},
    )
    _require(
        failed_issue.status == 500
        and database.execute(
            "SELECT count(*) FROM account_invitations WHERE username=%s", (rollback_username,)
        ).fetchone()[0] == 0,
        "a failed audit insert must roll back invitation state and token hash",
    )
    database.execute("ALTER TABLE audit_events DROP CONSTRAINT pg_admin_invite_audit_fail")
    retry_issue = pg_http_world.clients[1].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": rollback_username},
    )
    _require(
        retry_issue.status == 201
        and database.execute(
            "SELECT count(*) FROM account_invitations WHERE username=%s", (rollback_username,)
        ).fetchone()[0] == 1,
        "invitation creation must succeed after the audit failure is repaired",
    )
    pg_http_world.remember_secret(retry_issue.json()["invitation"]["token"])

    race_username = f"pg-admin-race-{uuid.uuid4().hex}@example.test"
    race_initial = pg_http_world.clients[0].request(
        "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
        json_body={"username": race_username},
    )
    race_invitation = race_initial.json()["invitation"]
    race_token = race_invitation["token"]
    pg_http_world.remember_secret(race_token)
    race_request, race_signer, race_verifier, race_device, _ = registration(
        race_username, race_token, "pg-admin-invitations-race"
    )
    race_barrier = threading.Barrier(3)

    def register_race() -> HttpResponse:
        race_barrier.wait(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
        return pg_http_world.clients[1].request(
            "POST", "/api/v1/auth/register", json_body=race_request
        )

    def reissue_race() -> HttpResponse:
        race_barrier.wait(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
        return pg_http_world.clients[0].request(
            "POST", "/api/v1/admin/account-invitations", token=admin.access_token,
            json_body={"username": race_username},
        )

    with ThreadPoolExecutor(max_workers=2) as executor:
        register_future = executor.submit(register_race)
        reissue_future = executor.submit(reissue_race)
        race_barrier.wait(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
        registration_result = register_future.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
        reissue_result = reissue_future.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
    if registration_result.status in (200, 201):
        _require(
            reissue_result.status == 409 and _error_code(reissue_result) == "USERNAME_TAKEN",
            "registration winning the metadata fence must make reissue reject the username",
        )
        _registered_actor(
            pg_http_world, race_request, registration_result,
            race_signer, race_verifier, race_device,
        )
    else:
        _require(
            registration_result.status == 401
            and _error_code(registration_result) == "ACCOUNT_INVITATION_INVALID"
            and reissue_result.status == 201,
            "reissue winning the metadata fence must invalidate the raced token",
        )
        _assert_failed_registration_absent(
            pg_http_world, race_request, label="admin invitation registration/reissue race"
        )
        pg_http_world.remember_secret(reissue_result.json()["invitation"]["token"])

    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        ("former-pg-admin-invitations@example.test", admin.user_id),
    )
    removed_allowlist = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/account-invitations", token=admin.access_token
    )
    _require(
        removed_allowlist.status == 403
        and _error_code(removed_allowlist) == "INSTANCE_ADMIN_REQUIRED",
        "the current administrator allowlist must be rechecked on each read",
    )
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_ACCOUNT_INVITATIONS_USERNAME, admin.user_id),
    )
    for method, path in (
        ("PUT", "/api/v1/admin/account-invitations"),
        ("DELETE", "/api/v1/admin/account-invitations"),
        ("GET", "/api/v1/admin/account-invitations/"),
        ("POST", "/api/v1/admin/account-invitations/not-a-uuid/revoke/"),
        ("POST", "/api/v1/admin/account-invitations/not-a-uuid/revoke/extra"),
        ("GET", "/api/v1/admin/account-invitations/not-a-uuid/revoke"),
    ):
        blocked = pg_http_world.clients[0].request(method, path, token=admin.access_token)
        _require(
            blocked.status == 503 and _error_code(blocked) == "PG_SYNC_SCOPE_LIMITED",
            "the PG route guard must expose only canonical account invitation paths",
        )

    audit_rows = database.execute(
        "SELECT actor_user_id,actor_device_id,resource_type,resource_id,source "
        "FROM audit_events WHERE actor_user_id=%s AND action LIKE %s",
        (admin.user_id, "instance.account_invitation_%"),
    ).fetchall()
    raw_invitation_ids = {
        first_invitation["invitation_id"],
        replacement_invitation["invitation_id"],
        revocable_invitation["invitation_id"],
        expired_invitation["invitation_id"],
        race_invitation["invitation_id"],
    }
    _require(
        len(audit_rows) >= 6
        and all(
            row[0] == admin.user_id
            and row[1] == admin.device_id
            and row[2] == "account_invitation"
            and len(row[3]) == 64
            and row[3] not in raw_invitation_ids
            and row[4] == "api"
            for row in audit_rows
        ),
        "committed invitation writes must retain the admin actor and HMAC only resource IDs",
    )

    pg_http_world.assert_secrets_not_in_local_files()


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_VAULT_QUOTA_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_vault_quotas_are_shared_private_and_atomic(
    pg_http_world: PgHttpWorld, tmp_path: Path, request: pytest.FixtureRequest
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-vault-quota-admin")
    admin = admin_tenant.actors[0]
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-vault-quota-outsider").actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_VAULT_QUOTA_USERNAME, admin.user_id),
    )
    database.execute(
        "UPDATE instance_meta SET setup_consumed_at=COALESCE(setup_consumed_at,clock_timestamp()) "
        "WHERE id=1"
    )

    vault_id = admin_tenant.vault_id
    blob_id = str(uuid.uuid4())
    open_upload_id = str(uuid.uuid4())
    completing_upload_id = str(uuid.uuid4())
    quota_first_object_id = str(uuid.uuid4())
    upload_first_object_id = str(uuid.uuid4())
    constraint_name = "pg_admin_vault_quota_audit_fail"

    def cleanup() -> None:
        database.execute(f"ALTER TABLE audit_events DROP CONSTRAINT IF EXISTS {constraint_name}")
        database.execute(
            "DELETE FROM uploads WHERE upload_id IN (%s,%s) OR object_id IN (%s,%s)",
            (open_upload_id, completing_upload_id, quota_first_object_id, upload_first_object_id),
        )
        database.execute(
            "DELETE FROM blob_objects WHERE vault_id=%s AND object_id=%s", (vault_id, blob_id)
        )
        database.execute(
            "UPDATE vaults SET quota_bytes=1073741824,state='active' WHERE vault_id=%s", (vault_id,)
        )
        database.execute(
            "UPDATE users SET username='pg-admin-vault-quota-cleanup@example.test' WHERE user_id=%s",
            (admin.user_id,),
        )

    request.addfinalizer(cleanup)
    database.execute(
        "INSERT INTO blob_objects(vault_id,object_id,size,sha256) VALUES (%s,%s,64,%s)",
        (vault_id, blob_id, "a" * 64),
    )
    for upload_id, state_name, object_id, size in (
        (open_upload_id, "open", str(uuid.uuid4()), 32),
        (completing_upload_id, "completing", str(uuid.uuid4()), 16),
    ):
        database.execute(
            "INSERT INTO uploads(upload_id,vault_id,user_id,object_id,expected_size,"
            "expected_sha256,chunk_size,state,expires_at,created_at,storage_backend,"
            "storage_store_id,storage_key) VALUES (%s,%s,%s,%s,%s,%s,65536,%s,"
            "clock_timestamp()+INTERVAL '1 hour',clock_timestamp(),'filesystem',%s,%s)",
            (
                upload_id,
                vault_id,
                admin.user_id,
                object_id,
                size,
                "b" * 64,
                state_name,
                f"pg-admin-quota-{upload_id}",
                f"acceptance/{upload_id}",
            ),
        )

    no_auth = pg_http_world.clients[0].request("GET", "/api/v1/admin/vaults")
    no_auth_write = pg_http_world.clients[1].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", json_body={"quota_bytes": 128}
    )
    outsider_read = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/vaults", token=outsider.access_token
    )
    outsider_write = pg_http_world.clients[1].request(
        "PUT",
        f"/api/v1/admin/vaults/{vault_id}/quota",
        token=outsider.access_token,
        json_body={"quota_bytes": 128},
    )
    _require(
        no_auth.status == no_auth_write.status == 401
        and outsider_read.status == outsider_write.status == 403
        and _error_code(outsider_read) == _error_code(outsider_write) == "INSTANCE_ADMIN_REQUIRED",
        "PG Vault quota routes must require the live allowlisted administrator",
    )

    for query, code in (
        ("limit=0", "INVALID_LIMIT"),
        ("limit=101", "INVALID_LIMIT"),
        ("offset=-1", "INVALID_OFFSET"),
        ("offset=1000001", "INVALID_OFFSET"),
    ):
        invalid_page = pg_http_world.clients[0].request(
            "GET", f"/api/v1/admin/vaults?{query}", token=admin.access_token
        )
        _require(invalid_page.status == 400 and _error_code(invalid_page) == code,
                 "PG Vault pagination must retain the bounded page contract")

    one_row = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/vaults?limit=1&offset=0", token=admin.access_token
    )
    page_a = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/vaults?limit=100&offset=0", token=admin.access_token
    )
    page_b = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/vaults?limit=100&offset=0", token=admin.access_token
    )
    _require(
        one_row.status == page_a.status == page_b.status == 200
        and one_row.json()["limit"] == 1
        and one_row.json()["offset"] == 0
        and len(one_row.json()["vaults"]) == 1
        and page_a.json() == page_b.json()
        and page_a.json()["total"] >= 2,
        "Vault list pagination must return an identical shared page on both nodes",
    )
    listed = next(row for row in page_a.json()["vaults"] if row["vault_id"] == vault_id)
    _require(
        set(listed)
        == {
            "vault_id", "owner_user_id", "owner_username", "state", "stored_bytes",
            "reserved_upload_bytes", "quota_bytes", "created_at",
        }
        and listed["owner_username"] == PG_ADMIN_VAULT_QUOTA_USERNAME
        and listed["state"] == "active"
        and listed["stored_bytes"] == 64
        and listed["reserved_upload_bytes"] == 48
        and listed["quota_bytes"] == 1073741824,
        "PG Vault DTO must include DB-clock open/completing usage and only the safe metadata fields",
    )
    page_text = json.dumps(page_a.json()).lower()
    _require(
        all(value not in page_text for value in ("name_envelope", "ciphertext", "access_token", "storage_key")),
        "PG Vault inventory must omit encrypted names, contents, credentials and object keys",
    )

    below_usage = pg_http_world.clients[0].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
        json_body={"quota_bytes": 111},
    )
    _require(
        below_usage.status == 409
        and _error_code(below_usage) == "QUOTA_BELOW_USAGE"
        and below_usage.json()["error"]["details"] == {
            "stored_bytes": 64,
            "reserved_upload_bytes": 48,
            "used_bytes": 112,
            "requested_quota_bytes": 111,
        },
        "quota updates must count both open and completing reservations",
    )

    changed = pg_http_world.clients[1].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
        json_body={"quota_bytes": 128},
    )
    _require(
        changed.status == 200
        and set(changed.json()) == {
            "vault_id", "quota_bytes", "stored_bytes", "reserved_upload_bytes", "updated_at",
        }
        and changed.json()["vault_id"] == vault_id
        and changed.json()["quota_bytes"] == 128
        and changed.json()["stored_bytes"] == 64
        and changed.json()["reserved_upload_bytes"] == 48
        and isinstance(changed.json()["updated_at"], str),
        "PG quota update must return the existing bounded receipt DTO",
    )
    _require(
        database.execute("SELECT quota_bytes FROM vaults WHERE vault_id=%s", (vault_id,)).fetchone()[0]
        == 128,
        "quota writes must be immediately shared across PostgreSQL nodes",
    )

    before_audits = database.execute(
        "SELECT count(*) FROM audit_events WHERE actor_user_id=%s AND action='admin.vault_quota_set'",
        (admin.user_id,),
    ).fetchone()[0]
    database.execute(
        f"ALTER TABLE audit_events ADD CONSTRAINT {constraint_name} "
        "CHECK (action <> 'admin.vault_quota_set') NOT VALID"
    )
    failed_audit = pg_http_world.clients[0].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
        json_body={"quota_bytes": 144},
    )
    _require(
        failed_audit.status == 500
        and database.execute("SELECT quota_bytes FROM vaults WHERE vault_id=%s", (vault_id,)).fetchone()[0]
        == 128
        and database.execute(
            "SELECT count(*) FROM audit_events WHERE actor_user_id=%s AND action='admin.vault_quota_set'",
            (admin.user_id,),
        ).fetchone()[0] == before_audits,
        "an audit insertion failure must roll back the quota change",
    )
    database.execute(f"ALTER TABLE audit_events DROP CONSTRAINT {constraint_name}")
    retry = pg_http_world.clients[1].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
        json_body={"quota_bytes": 144},
    )
    _require(retry.status == 200, "quota update must succeed after an audit failure is repaired")

    audit_rows = database.execute(
        "SELECT scope_type,actor_user_id,actor_device_id,action,resource_type,resource_id,source "
        "FROM audit_events WHERE actor_user_id=%s AND action='admin.vault_quota_set' ORDER BY event_id",
        (admin.user_id,),
    ).fetchall()
    _require(
        len(audit_rows) == before_audits + 1
        and all(
            row[0] == "instance" and row[1] == admin.user_id and row[2] == admin.device_id
            and row[3] == "admin.vault_quota_set" and row[4] == "vault"
            and isinstance(row[5], str) and len(row[5]) == 64 and row[5] != vault_id
            and row[6] == "api"
            for row in audit_rows[-2:]
        )
        and vault_id not in json.dumps(audit_rows[-2:]),
        "quota audits must be atomic, actor-attributed and HMAC the Vault resource identifier",
    )

    for quota_bytes in (0, -1, (1 << 40) + 1):
        invalid = pg_http_world.clients[0].request(
            "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
            json_body={"quota_bytes": quota_bytes},
        )
        _require(invalid.status == 400 and _error_code(invalid) == "INVALID_QUOTA",
                 "PG quota values must remain bounded from one byte through one TiB")
    invalid_body = pg_http_world.clients[0].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
        json_body={"quota_bytes": 256, "unexpected": True},
    )
    invalid_id = pg_http_world.clients[0].request(
        "PUT", "/api/v1/admin/vaults/not-a-vault/quota", token=admin.access_token,
        json_body={"quota_bytes": 256},
    )
    noncanonical_id = pg_http_world.clients[0].request(
        "PUT", "/api/v1/admin/vaults/AAAAAAAA-BBBB-4CCC-8DDD-EEEEEEEEEEEE/quota",
        token=admin.access_token, json_body={"quota_bytes": 256},
    )
    missing_vault = pg_http_world.clients[0].request(
        "PUT", f"/api/v1/admin/vaults/{uuid.uuid4()}/quota", token=admin.access_token,
        json_body={"quota_bytes": 256},
    )
    _require(
        invalid_body.status == 400 and invalid_id.status == noncanonical_id.status == 400
        and missing_vault.status == 404,
        "PG quota routes must retain strict bodies, canonical IDs and not-found behavior",
    )

    database.execute("UPDATE vaults SET state='deleting' WHERE vault_id=%s", (vault_id,))
    try:
        deleting = pg_http_world.clients[0].request(
            "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
            json_body={"quota_bytes": 256},
        )
        _require(deleting.status == 409 and _error_code(deleting) == "VAULT_NOT_ACTIVE",
                 "deleting Vaults must not accept quota changes")
    finally:
        database.execute("UPDATE vaults SET state='active' WHERE vault_id=%s", (vault_id,))

    database.execute(
        "DELETE FROM uploads WHERE upload_id IN (%s,%s)", (open_upload_id, completing_upload_id)
    )
    def run_locked_quota_upload_race(
        *, first: str, object_id: str
    ) -> tuple[bool, bool, HttpResponse, HttpResponse]:
        """Queue both HTTP operations behind a held Vault lock in known order."""
        database.execute("DELETE FROM uploads WHERE object_id=%s", (object_id,))
        database.execute("UPDATE vaults SET quota_bytes=200 WHERE vault_id=%s", (vault_id,))
        holder = pg_http_world.psycopg.connect(
            pg_http_world.pg_url,
            autocommit=False,
            connect_timeout=10,
            application_name="atermius-pg-http-quota-holder",
        )
        quota_future = None
        upload_future = None
        first_request_blocked = False
        second_request_blocked = False
        try:
            holder.execute(
                pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                    pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
                )
            )
            holder.execute(
                "SELECT vault_id FROM vaults WHERE vault_id=%s FOR UPDATE", (vault_id,)
            )
            init_request = {"object_id": object_id, "size": 101, "sha256": "c" * 64}

            def update_quota() -> HttpResponse:
                return pg_http_world.clients[0].request(
                    "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
                    json_body={"quota_bytes": 64},
                )

            def reserve_upload() -> HttpResponse:
                return pg_http_world.clients[1].request(
                    "POST", f"/api/v1/vaults/{vault_id}/uploads/init", token=admin.access_token,
                    json_body=init_request,
                )

            first_app = "atermius-pg-http-node-0" if first == "quota" else "atermius-pg-http-node-1"
            second_app = "atermius-pg-http-node-1" if first == "quota" else "atermius-pg-http-node-0"
            with ThreadPoolExecutor(max_workers=2) as executor:
                if first == "quota":
                    quota_future = executor.submit(update_quota)
                else:
                    upload_future = executor.submit(reserve_upload)
                try:
                    first_request_blocked = _wait_for_pg_blocker(
                        pg_http_world,
                        waiting_application=first_app,
                        holder_application="atermius-pg-http-quota-holder",
                    )

                    if first == "quota":
                        upload_future = executor.submit(reserve_upload)
                    else:
                        quota_future = executor.submit(update_quota)
                    second_request_blocked = _wait_for_pg_vault_lock_waiter(
                        pg_http_world, waiting_application=second_app
                    )
                finally:
                    # Always release before assertions or future waits,
                    # including when lock observation fails, so a failed
                    # acceptance cannot strand either HTTP request.
                    holder.commit()
                quota_response = quota_future.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
                upload_response = upload_future.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS)
            return first_request_blocked, second_request_blocked, quota_response, upload_response
        finally:
            if not holder.closed:
                holder.rollback()
                holder.close()

    quota_first = run_locked_quota_upload_race(first="quota", object_id=quota_first_object_id)
    _require(
        quota_first[0] and quota_first[1],
        "quota-first race must observe both node requests queued behind the held Vault row lock",
    )
    quota_first_response, upload_after_quota = quota_first[2], quota_first[3]
    quota_first_usage = database.execute(
        "SELECT (SELECT COALESCE(SUM(size),0) FROM blob_objects WHERE vault_id=%s)+"
        "(SELECT COALESCE(SUM(expected_size),0) FROM uploads WHERE vault_id=%s "
        "AND state IN ('open','completing') AND expires_at>clock_timestamp()),quota_bytes "
        "FROM vaults WHERE vault_id=%s",
        (vault_id, vault_id, vault_id),
    ).fetchone()
    _require(
        quota_first_response.status == 200
        and upload_after_quota.status == 507
        and _error_code(upload_after_quota) == "QUOTA_EXCEEDED"
        and quota_first_usage[0] == quota_first_usage[1] == 64,
        "when quota reduction is queued first, it must commit and the later reservation must fail",
    )

    upload_first = run_locked_quota_upload_race(first="upload", object_id=upload_first_object_id)
    _require(
        upload_first[0] and upload_first[1],
        "upload-first race must observe both node requests queued behind the held Vault row lock",
    )
    quota_after_upload, upload_first_response = upload_first[2], upload_first[3]
    upload_first_usage = database.execute(
        "SELECT (SELECT COALESCE(SUM(size),0) FROM blob_objects WHERE vault_id=%s)+"
        "(SELECT COALESCE(SUM(expected_size),0) FROM uploads WHERE vault_id=%s "
        "AND state IN ('open','completing') AND expires_at>clock_timestamp()),quota_bytes "
        "FROM vaults WHERE vault_id=%s",
        (vault_id, vault_id, vault_id),
    ).fetchone()
    _require(
        upload_first_response.status in (200, 201)
        and quota_after_upload.status == 409
        and _error_code(quota_after_upload) == "QUOTA_BELOW_USAGE"
        and upload_first_usage[0] == 165
        and upload_first_usage[1] == 200,
        "when reservation is queued first, it must commit and the later quota reduction must fail",
    )

    database.execute(
        "UPDATE users SET username='pg-admin-vault-quota-former@example.test' WHERE user_id=%s",
        (admin.user_id,),
    )
    stale_admin = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/vaults", token=admin.access_token
    )
    stale_admin_write = pg_http_world.clients[0].request(
        "PUT", f"/api/v1/admin/vaults/{vault_id}/quota", token=admin.access_token,
        json_body={"quota_bytes": 256},
    )
    _require(
        stale_admin.status == stale_admin_write.status == 403
        and _error_code(stale_admin) == _error_code(stale_admin_write) == "INSTANCE_ADMIN_REQUIRED",
        "the current administrator allowlist must be rechecked on every read and write",
    )
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_VAULT_QUOTA_USERNAME, admin.user_id),
    )

    for method, path in (
        ("POST", "/api/v1/admin/vaults"),
        ("GET", "/api/v1/admin/vaults/"),
        ("PUT", "/api/v1/admin/vaults"),
        ("GET", f"/api/v1/admin/vaults/{vault_id}/quota"),
        ("PUT", f"/api/v1/admin/vaults/{vault_id}/quota/"),
        ("PUT", f"/api/v1/admin/vaults/{vault_id}//quota"),
        ("PUT", f"/api/v1/admin/vaults/{vault_id}/quota/extra"),
    ):
        blocked = pg_http_world.clients[0].request(method, path, token=admin.access_token)
        _require(
            blocked.status == 503 and _error_code(blocked) == "PG_SYNC_SCOPE_LIMITED",
            "the PG guard must allow only exact Vault inventory/quota routes",
        )

    pg_http_world.assert_secrets_not_in_local_files()


@pytest.mark.parametrize(
    "pg_http_world",
    [f"{PG_ADMIN_ACCOUNT_CONTROLS_USERNAME},{PG_ADMIN_ACCOUNT_CONTROLS_SECOND_USERNAME}"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_account_mutations_are_atomic_and_revoke_credentials(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-controls-admin")
    admin = admin_tenant.actors[0]
    target = pg_http_world.seed_tenant(tmp_path / "pg-admin-controls-target")
    target_actor = target.actors[0]
    target_user = target_actor.user_id
    second_admin = pg_http_world.seed_tenant(
        tmp_path / "pg-admin-controls-second-admin"
    ).actors[0]
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-controls-outsider").actors[0]
    database = pg_http_world.database_connection
    database.execute(
        "UPDATE users SET username=CASE user_id WHEN %s THEN %s WHEN %s THEN %s END "
        "WHERE user_id IN (%s,%s)",
        (
            admin.user_id,
            PG_ADMIN_ACCOUNT_CONTROLS_USERNAME,
            second_admin.user_id,
            PG_ADMIN_ACCOUNT_CONTROLS_SECOND_USERNAME,
            admin.user_id,
            second_admin.user_id,
        ),
    )

    self_target = pg_http_world.clients[0].request(
        "PUT",
        f"/api/v1/admin/accounts/{admin.user_id}/status",
        token=admin.access_token,
        json_body={"status": "disabled"},
    )
    outsider = pg_http_world.clients[1].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=outsider.access_token,
        json_body={"status": "disabled"},
    )
    _require(
        self_target.status == 409
        and _error_code(self_target) == "ADMIN_SELF_TARGET"
        and outsider.status == 403
        and _error_code(outsider) == "INSTANCE_ADMIN_REQUIRED",
        "PG account status auth fence mismatch: "
        f"self={self_target.status}/{_error_code(self_target)} "
        f"outsider={outsider.status}/{_error_code(outsider)}",
    )

    # Force the audit insert to fail once. Account status and session revokes
    # must roll back together, then the same request can be retried safely.
    database.execute(
        "ALTER TABLE audit_events ADD CONSTRAINT pg_admin_controls_audit_fail "
        "CHECK (action <> 'admin.account_disabled') NOT VALID"
    )
    failed_disable = pg_http_world.clients[0].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "disabled"},
    )
    _require(
        failed_disable.status == 500
        and database.execute(
            "SELECT status FROM users WHERE user_id=%s", (target_user,)
        ).fetchone()[0]
        == "active"
        and database.execute(
            "SELECT COUNT(*) FROM sessions WHERE user_id=%s AND revoked_at IS NULL",
            (target_user,),
        ).fetchone()[0]
        == 2,
        "failed PG audit insertion must roll back account status and all session revokes",
    )
    database.execute("ALTER TABLE audit_events DROP CONSTRAINT pg_admin_controls_audit_fail")

    disabled = pg_http_world.clients[1].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "disabled"},
    )
    _require(
        disabled.status == 200
        and disabled.json()["status"] == "disabled"
        and disabled.json()["changed"] is True
        and disabled.json()["revoked_sessions"] == 2,
        "disabling a target account must atomically revoke all its active PG sessions",
    )
    _require(
        all(
            pg_http_world.clients[index].request(
                "GET", "/api/v1/me", token=actor.access_token
            ).status
            == 401
            for index, actor in enumerate(target.actors)
        ),
        "old target access tokens must fail on every node after the disable commit",
    )
    for actor in target.actors:
        _require(
            pg_http_world.clients[0].request(
                "POST",
                "/api/v1/auth/refresh",
                json_body={"refresh_token": actor.refresh_token},
            ).status
            == 401,
            "old refresh tokens must remain unusable after account disable",
        )
    disabled_sessions = pg_http_world.clients[1].request(
        "GET",
        f"/api/v1/admin/accounts/{target_user}/sessions?limit=100",
        token=admin.access_token,
    )
    _require(
        disabled_sessions.status == 200
        and disabled_sessions.json()["total"] == 2
        and all(
            not session["active"] and session["revoked_at"] is not None
            for session in disabled_sessions.json()["sessions"]
        ),
        "the other node must see the disabled status and every revoked target session",
    )

    repeated_disable = pg_http_world.clients[0].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "disabled"},
    )
    enabled = pg_http_world.clients[1].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "active"},
    )
    _require(
        repeated_disable.status == enabled.status == 200
        and repeated_disable.json()["changed"] is False
        and repeated_disable.json()["revoked_sessions"] == 0
        and enabled.json()["changed"] is True
        and enabled.json()["revoked_sessions"] == 0
        and pg_http_world.clients[0].request(
            "GET", "/api/v1/me", token=target_actor.access_token
        ).status
        == 401,
        "same-status updates must be idempotent and re-enable must not revive old sessions",
    )

    logins = [_login(pg_http_world.clients[index], actor) for index, actor in enumerate(target.actors)]
    _require(
        all(response.status == 200 for response in logins),
        "an enabled account may create new sessions after the administrator action",
    )
    sessions = []
    for index, response in enumerate(logins):
        credentials = response.json()
        access_hash = hashlib.sha256(credentials["access_token"].encode("ascii")).hexdigest()
        session_id = database.execute(
            "SELECT session_id FROM sessions WHERE access_hash=%s", (access_hash,)
        ).fetchone()[0]
        sessions.append((index, credentials, session_id))

    one = sessions[0]
    revoked_one = pg_http_world.clients[1].request(
        "POST",
        f"/api/v1/admin/accounts/{target_user}/sessions/{one[2]}/revoke",
        token=admin.access_token,
    )
    repeated_one = pg_http_world.clients[0].request(
        "POST",
        f"/api/v1/admin/accounts/{target_user}/sessions/{one[2]}/revoke",
        token=admin.access_token,
    )
    _require(
        revoked_one.status == repeated_one.status == 200
        and revoked_one.json()["changed"] is True
        and repeated_one.json()["changed"] is False
        and pg_http_world.clients[0].request(
            "GET", "/api/v1/me", token=one[1]["access_token"]
        ).status
        == 401
        and pg_http_world.clients[1].request(
            "GET", "/api/v1/me", token=sessions[1][1]["access_token"]
        ).status
        == 200,
        "single-session revoke must be cross-node visible, idempotent and account-scoped",
    )
    revoke_all = pg_http_world.clients[0].request(
        "POST",
        f"/api/v1/admin/accounts/{target_user}/sessions/revoke",
        token=admin.access_token,
    )
    repeated_all = pg_http_world.clients[1].request(
        "POST",
        f"/api/v1/admin/accounts/{target_user}/sessions/revoke",
        token=admin.access_token,
    )
    _require(
        revoke_all.status == repeated_all.status == 200
        and revoke_all.json()["revoked_sessions"] == 1
        and repeated_all.json()["revoked_sessions"] == 0
        and pg_http_world.clients[1].request(
            "GET", "/api/v1/me", token=sessions[1][1]["access_token"]
        ).status
        == 401,
        "bulk session revocation must atomically revoke every remaining active target session",
    )

    database.execute("UPDATE users SET status='deleting' WHERE user_id=%s", (target_user,))
    deleting_status = pg_http_world.clients[0].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "active"},
    )
    deleting_bulk = pg_http_world.clients[0].request(
        "POST",
        f"/api/v1/admin/accounts/{target_user}/sessions/revoke",
        token=admin.access_token,
    )
    deleting_single = pg_http_world.clients[0].request(
        "POST",
        f"/api/v1/admin/accounts/{target_user}/sessions/{sessions[1][2]}/revoke",
        token=admin.access_token,
    )
    _require(
        all(
            response.status == 409 and _error_code(response) == "ACCOUNT_DELETING"
            for response in (deleting_status, deleting_bulk, deleting_single)
        )
        and database.execute(
            "SELECT status FROM users WHERE user_id=%s", (target_user,)
        ).fetchone()[0]
        == "deleting"
        and database.execute(
            "SELECT COUNT(*) FROM sessions WHERE user_id=%s AND revoked_at IS NULL",
            (target_user,),
        ).fetchone()[0]
        == 0,
        "account status and session-revoke controls must reject deleting accounts without side effects",
    )
    database.execute("UPDATE users SET status='active' WHERE user_id=%s", (target_user,))

    def hold_target_lifecycle_lock() -> Any:
        gate = pg_http_world.psycopg.connect(pg_http_world.pg_url, autocommit=False)
        gate.execute(
            pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
            )
        )
        gate.execute(
            "SELECT pg_advisory_xact_lock(%s,hashtext(%s))",
            (0x41544552, target_user),
        )
        return gate

    def wait_for_lifecycle_waiters(expected: int) -> None:
        deadline = time.monotonic() + 10
        while time.monotonic() < deadline:
            count = database.execute(
                "SELECT COUNT(*) FROM pg_stat_activity WHERE datname=current_database() "
                "AND application_name LIKE 'atermius-pg-http-node-%' "
                "AND wait_event_type='Lock' AND wait_event='advisory'"
            ).fetchone()[0]
            if count >= expected:
                return
            time.sleep(0.01)
        pytest.fail("expected account lifecycle requests to queue on the shared PG fence", pytrace=False)

    def release_gate_after_queued_requests(gate: Any, requests: list[Any]) -> list[Any]:
        try:
            for count, _request in enumerate(requests, start=1):
                wait_for_lifecycle_waiters(count)
            gate.commit()
            return [request.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS) for request in requests]
        finally:
            if not gate.closed:
                gate.rollback()
            gate.close()

    # If login queues first, it may return success, but the later disable must
    # revoke that just-created session before the disable response commits.
    race_enable = pg_http_world.clients[0].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "active"},
    )
    _require(race_enable.status == 200, "target account must be active before login/disable race")
    gate = hold_target_lifecycle_lock()
    with ThreadPoolExecutor(max_workers=2) as executor:
        login_first = executor.submit(_login, pg_http_world.clients[0], target_actor)
        wait_for_lifecycle_waiters(1)
        disable_second = executor.submit(
            pg_http_world.clients[1].request,
            "PUT",
            f"/api/v1/admin/accounts/{target_user}/status",
            token=admin.access_token,
            json_body={"status": "disabled"},
        )
        login_result, disable_result = release_gate_after_queued_requests(
            gate, [login_first, disable_second]
        )
    login_token = (login_result.json() or {}).get("access_token")
    raced_me = (
        pg_http_world.clients[1].request("GET", "/api/v1/me", token=login_token)
        if login_token
        else None
    )
    _require(
        login_result.status == 200
        and disable_result.status == 200
        and disable_result.json()["changed"] is True
        and raced_me is not None
        and raced_me.status == 401,
        "login-first race mismatch: "
        f"login={login_result.status}/{_error_code(login_result)} "
        f"disable={disable_result.status}/{_error_code(disable_result)} "
        f"post-disable-me={getattr(raced_me, 'status', None)}",
    )

    # If disable queues first, login must observe the committed disabled state
    # and fail without inserting a new active session.
    race_reenable = pg_http_world.clients[1].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "active"},
    )
    _require(race_reenable.status == 200, "target account must re-enable before reverse race")
    gate = hold_target_lifecycle_lock()
    with ThreadPoolExecutor(max_workers=2) as executor:
        disable_first = executor.submit(
            pg_http_world.clients[0].request,
            "PUT",
            f"/api/v1/admin/accounts/{target_user}/status",
            token=admin.access_token,
            json_body={"status": "disabled"},
        )
        wait_for_lifecycle_waiters(1)
        login_second = executor.submit(_login, pg_http_world.clients[1], target.actors[1])
        disable_result, login_result = release_gate_after_queued_requests(
            gate, [disable_first, login_second]
        )
    _require(
        disable_result.status == 200
        and disable_result.json()["changed"] is True
        and login_result.status == 401
        and database.execute(
            "SELECT COUNT(*) FROM sessions WHERE user_id=%s AND revoked_at IS NULL",
            (target_user,),
        ).fetchone()[0]
        == 0,
        "disable queued before login must prevent an active session from being inserted",
    )

    # Refresh shares the same per-account lifecycle fence. If refresh wins,
    # the subsequent disable must revoke the rotated session before commit.
    refresh_reenable = pg_http_world.clients[0].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "active"},
    )
    refresh_login = _login(pg_http_world.clients[0], target.actors[0])
    _require(
        refresh_reenable.status == refresh_login.status == 200,
        "target account must re-enable and create a session before refresh/disable race",
    )
    refresh_token = refresh_login.json()["refresh_token"]
    gate = hold_target_lifecycle_lock()
    with ThreadPoolExecutor(max_workers=2) as executor:
        refresh_first = executor.submit(
            pg_http_world.clients[0].request,
            "POST",
            "/api/v1/auth/refresh",
            json_body={"refresh_token": refresh_token},
        )
        wait_for_lifecycle_waiters(1)
        disable_second = executor.submit(
            pg_http_world.clients[1].request,
            "PUT",
            f"/api/v1/admin/accounts/{target_user}/status",
            token=admin.access_token,
            json_body={"status": "disabled"},
        )
        refresh_result, disable_result = release_gate_after_queued_requests(
            gate, [refresh_first, disable_second]
        )
    rotated = (refresh_result.json() or {}).get("refresh_token")
    refreshed_access = (refresh_result.json() or {}).get("access_token")
    _require(
        refresh_result.status == disable_result.status == 200
        and disable_result.json()["changed"] is True
        and refreshed_access is not None
        and pg_http_world.clients[1].request(
            "GET", "/api/v1/me", token=refreshed_access
        ).status
        == 401
        and pg_http_world.clients[0].request(
            "POST",
            "/api/v1/auth/refresh",
            json_body={"refresh_token": rotated},
        ).status
        == 401,
        "refresh-first race must rotate successfully, then leave no usable credentials after disable",
    )

    # Conversely, a refresh queued behind disable must observe the committed
    # disabled state and cannot create or rotate into a live session.
    refresh_reenable = pg_http_world.clients[1].request(
        "PUT",
        f"/api/v1/admin/accounts/{target_user}/status",
        token=admin.access_token,
        json_body={"status": "active"},
    )
    refresh_login = _login(pg_http_world.clients[1], target.actors[1])
    _require(
        refresh_reenable.status == refresh_login.status == 200,
        "target account must re-enable and create a second session before reverse refresh race",
    )
    refresh_token = refresh_login.json()["refresh_token"]
    gate = hold_target_lifecycle_lock()
    with ThreadPoolExecutor(max_workers=2) as executor:
        disable_first = executor.submit(
            pg_http_world.clients[0].request,
            "PUT",
            f"/api/v1/admin/accounts/{target_user}/status",
            token=admin.access_token,
            json_body={"status": "disabled"},
        )
        wait_for_lifecycle_waiters(1)
        refresh_second = executor.submit(
            pg_http_world.clients[1].request,
            "POST",
            "/api/v1/auth/refresh",
            json_body={"refresh_token": refresh_token},
        )
        disable_result, refresh_result = release_gate_after_queued_requests(
            gate, [disable_first, refresh_second]
        )
    _require(
        disable_result.status == 200
        and disable_result.json()["changed"] is True
        and refresh_result.status == 401
        and database.execute(
            "SELECT COUNT(*) FROM sessions WHERE user_id=%s AND revoked_at IS NULL",
            (target_user,),
        ).fetchone()[0]
        == 0,
        "disable queued before refresh must reject rotation and leave no active target sessions",
    )

    audit_rows = database.execute(
        "SELECT action,actor_user_id,actor_device_id,resource_id,result FROM audit_events "
        "WHERE scope_type='instance' AND actor_user_id=%s AND resource_type='account' "
        "ORDER BY event_id",
        (admin.user_id,),
    ).fetchall()
    actions = [row[0] for row in audit_rows]
    expected = [
        "admin.account_disabled",
        "admin.account_enabled",
        "admin.account_session_revoked",
        "admin.account_sessions_revoked",
    ]
    _require(
        all(action in actions for action in expected)
        and actions.count("admin.account_disabled") == 5
        and actions.count("admin.account_enabled") == 4
        and actions.count("admin.account_session_revoked") == 1
        and actions.count("admin.account_sessions_revoked") == 1
        and all(
            row[1] == admin.user_id
            and row[2] == admin.device_id
            and row[3] != target_user
            and row[4] == "success"
            for row in audit_rows
            if row[0] in expected
        ),
        "PG account controls must write one HMAC-resource instance audit per actual transition",
    )

    # Two live administrators may concurrently try to disable each other.
    # Queue both writes behind the shared PG admin-account fence: the winner
    # must revoke the loser's session before the loser is reauthorized.
    admin_gate = pg_http_world.psycopg.connect(pg_http_world.pg_url, autocommit=False)
    admin_gate.execute(
        pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
            pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
        )
    )
    admin_gate.execute(
        "SELECT pg_advisory_xact_lock(%s,%s)", (0x41544144, 1)
    )
    admin_audit_count_before = database.execute(
        "SELECT COUNT(*) FROM audit_events WHERE scope_type='instance' "
        "AND action='admin.account_disabled' AND resource_type='account' "
        "AND actor_user_id IN (%s,%s)",
        (admin.user_id, second_admin.user_id),
    ).fetchone()[0]
    with ThreadPoolExecutor(max_workers=2) as executor:
        disable_second_admin = executor.submit(
            pg_http_world.clients[0].request,
            "PUT",
            f"/api/v1/admin/accounts/{second_admin.user_id}/status",
            token=admin.access_token,
            json_body={"status": "disabled"},
        )
        wait_for_lifecycle_waiters(1)
        second_disables_admin = executor.submit(
            pg_http_world.clients[1].request,
            "PUT",
            f"/api/v1/admin/accounts/{admin.user_id}/status",
            token=second_admin.access_token,
            json_body={"status": "disabled"},
        )
        try:
            wait_for_lifecycle_waiters(2)
            admin_gate.commit()
            concurrent_results = [
                disable_second_admin.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS),
                second_disables_admin.result(timeout=PG_ACCEPTANCE_TIMEOUT_SECONDS),
            ]
        finally:
            if not admin_gate.closed:
                admin_gate.rollback()
            admin_gate.close()
    admin_statuses = database.execute(
        "SELECT status FROM users WHERE user_id IN (%s,%s) ORDER BY user_id",
        (admin.user_id, second_admin.user_id),
    ).fetchall()
    admin_audit_count = database.execute(
        "SELECT COUNT(*) FROM audit_events WHERE scope_type='instance' "
        "AND action='admin.account_disabled' AND resource_type='account' "
        "AND actor_user_id IN (%s,%s)",
        (admin.user_id, second_admin.user_id),
    ).fetchone()[0]
    _require(
        len([response for response in concurrent_results if response.status == 200]) == 1
        and len([response for response in concurrent_results if response.status == 401]) == 1
        and _error_code(
            next(response for response in concurrent_results if response.status == 401)
        )
        == "AUTH_REQUIRED"
        and next(
            response for response in concurrent_results if response.status == 200
        ).json()["changed"]
        and sum(row[0] == "active" for row in admin_statuses) == 1
        and sum(row[0] == "disabled" for row in admin_statuses) == 1
        and admin_audit_count - admin_audit_count_before == 1,
        "concurrent administrators disabling each other must leave exactly one active admin",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_JOBS_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_maintenance_jobs_are_shared_idempotent_and_admin_only(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-job-admin")
    admin = admin_tenant.actors[0]
    pg_http_world.database_connection.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_JOBS_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-job-outsider").actors[0]

    first_page = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/jobs?limit=10&offset=0", token=admin.access_token
    )
    _require(
        first_page.status == 200
        and first_page.json()
        == {"jobs": [], "total": 0, "supported_actions": ["maintenance", "backup_status", "backup_schedule"]},
        "an allowlisted PostgreSQL administrator must see the shared job list and PG capabilities",
    )
    schedule = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/backup-schedule", token=admin.access_token
    )
    cannot_enable = pg_http_world.clients[1].request(
        "PUT",
        "/api/v1/admin/backup-schedule",
        token=admin.access_token,
        json_body={"interval_hours": 1},
    )
    _require(
        schedule.status == 200
        and schedule.json()
        == {
            "operation": "backup_schedule",
            "backup_configured": False,
            "interval_hours": None,
            "next_run_at": None,
            "last_run": None,
        }
        and cannot_enable.status == 503
        and _error_code(cannot_enable) == "BACKUP_NOT_CONFIGURED"
        and pg_http_world.database_connection.execute(
            "SELECT interval_hours,next_run_at FROM instance_backup_schedule WHERE schedule_id=1"
        ).fetchone()
        == (None, None),
        "schedule state must remain visible but cannot be enabled without ready PostgreSQL backup storage and key",
    )
    missing_status = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/backup-status"
    )
    _require(
        missing_status.status == 401,
        "PostgreSQL backup status must require an authenticated administrator",
    )
    empty_status = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/backup-status", token=admin.access_token
    )
    _require(
        empty_status.status == 200
        and empty_status.json() == {"operation": "backup", "last_attempt": None},
        "PostgreSQL backup status must be readable from another node before the first backup",
    )
    denied_status = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/backup-status", token=outsider.access_token
    )
    _require(
        denied_status.status == 403
        and _error_code(denied_status) == "INSTANCE_ADMIN_REQUIRED",
        "ordinary PostgreSQL accounts must not read backup status",
    )
    denied_list = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/jobs", token=outsider.access_token
    )
    _require(
        denied_list.status == 403
        and _error_code(denied_list) == "INSTANCE_ADMIN_REQUIRED",
        "ordinary PostgreSQL accounts must not read instance job history",
    )
    denied_create = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        token=outsider.access_token,
        json_body={"request_id": str(uuid.uuid4()), "action": "maintenance"},
    )
    _require(
        denied_create.status == 403
        and _error_code(denied_create) == "INSTANCE_ADMIN_REQUIRED",
        "ordinary PostgreSQL accounts must not enqueue instance maintenance",
    )

    backup_rejected = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={"request_id": str(uuid.uuid4()), "action": "backup"},
    )
    restore_rejected = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={
            "request_id": str(uuid.uuid4()),
            "action": "restore",
            "archive_id": str(uuid.uuid4()),
            "archive_source": "local",
        },
    )
    _require(
        backup_rejected.status == 503
        and restore_rejected.status == 503
        and _error_code(backup_rejected) == "PG_ADMIN_ACTION_UNSUPPORTED"
        and _error_code(restore_rejected) == "PG_ADMIN_ACTION_UNSUPPORTED",
        "PostgreSQL backup and restore jobs must fail with an explicit capability error",
    )

    database = pg_http_world.database_connection
    occupied_job = str(uuid.uuid4())
    occupied_request = str(uuid.uuid4())
    database.execute(
        "INSERT INTO instance_admin_jobs( \
             job_id,request_id,requested_by_user_id,requested_by_device_id,action,status, \
             requested_at,started_at,worker_token,lease_expires_at \
         ) VALUES (%s,%s,%s,%s,'maintenance','running',clock_timestamp(), \
                   clock_timestamp(),'acceptance-hold',clock_timestamp()+INTERVAL '1 hour')",
        (occupied_job, occupied_request, admin.user_id, admin.device_id),
    )
    blocked = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={"request_id": str(uuid.uuid4()), "action": "maintenance"},
    )
    _require(
        blocked.status == 409
        and _error_code(blocked) == "MAINTENANCE_ALREADY_RUNNING",
        "a database-enforced active-job fence must reject overlapping maintenance work",
    )
    database.execute("DELETE FROM instance_admin_jobs WHERE job_id=%s", (occupied_job,))

    request_id = str(uuid.uuid4())
    submitted = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={"request_id": request_id, "action": "maintenance"},
    )
    _require(
        submitted.status == 202
        and submitted.json().get("job", {}).get("request_id") == request_id
        and submitted.json().get("job", {}).get("status") == "queued",
        "the first shared PostgreSQL maintenance request must be durably queued",
    )
    job_id = submitted.json()["job"]["job_id"]
    replay = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={"request_id": request_id, "action": "maintenance"},
    )
    _require(
        replay.status == 202 and replay.json().get("job", {}).get("job_id") == job_id,
        "the other PostgreSQL node must return the same job for an idempotent retry",
    )

    deadline = time.monotonic() + 15
    terminal = None
    while time.monotonic() < deadline:
        page = pg_http_world.clients[1].request(
            "GET", "/api/v1/admin/jobs?limit=10&offset=0", token=admin.access_token
        )
        _require(page.status == 200, "the second PostgreSQL node must read job progress")
        matches = [job for job in page.json().get("jobs", []) if job.get("job_id") == job_id]
        if matches and matches[0].get("status") in {"succeeded", "failed"}:
            terminal = matches[0]
            break
        time.sleep(0.05)
    _require(
        terminal is not None
        and terminal.get("status") == "succeeded"
        and terminal.get("result_code") == "completed",
        "the shared PG worker must complete the bounded maintenance pass and publish its terminal state",
    )
    _require(
        terminal.get("action") == "maintenance"
        and terminal.get("archive_id") is None
        and terminal.get("archive_source") is None
        and terminal.get("restore_stage_status") is None,
        "the shared maintenance DTO must expose only the supported safe job fields",
    )
    audit = database.execute(
        "SELECT action,resource_id,result FROM audit_events \
         WHERE scope_type='instance' AND actor_user_id=%s AND resource_type='admin_job' \
         ORDER BY event_id",
        (admin.user_id,),
    ).fetchall()
    _require(
        [row[0] for row in audit]
        == [
            "admin.maintenance_requested",
            "admin.maintenance_started",
            "admin.maintenance_completed",
        ]
        and all(row[1] != job_id and row[2] == "success" for row in audit),
        "job lifecycle audit must be atomic, attributable, and HMAC-only for the job resource",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_ADMIN_AUTO_PURGE_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_maintenance_purges_only_due_consented_tombstones(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    """An explicit shared maintenance job purges only due, opted-in tombstones."""
    world = pg_http_world
    tenant = world.seed_tenant(tmp_path / "pg-auto-purge-owner")
    owner, second_device = tenant.actors
    admin_tenant = world.seed_tenant(tmp_path / "pg-auto-purge-admin")
    admin = admin_tenant.actors[0]
    database = world.database_connection
    database.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_AUTO_PURGE_USERNAME, admin.user_id),
    )

    redaction_marker = {"X-Atermius-Redaction-Marker": "v1"}
    report_path = "/api/v1/devices/redaction-capabilities"
    for actor in (owner, second_device):
        report = {
            "format": "atermius-sync-redaction-capability-v1",
            "account_id": actor.user_id,
            "device_id": actor.device_id,
            "revision": 1,
            "sync_redaction_version": 1,
        }
        signed_report = {
            **report,
            "signature": b64url(actor.signing_key.sign(jcs(report))),
        }
        published = world.clients[0].request(
            "PUT",
            report_path,
            token=actor.access_token,
            json_body=signed_report,
            additional_headers=redaction_marker,
        )
        _require(
            published.status == 200,
            "each active target-Vault device must publish its signed redaction capability",
        )

    record_ids = {
        "expired_opted_in": str(uuid.uuid4()),
        "not_due_opted_in": str(uuid.uuid4()),
        "expired_unconsented": str(uuid.uuid4()),
    }
    tombstones: dict[str, tuple[str, str]] = {}
    for name, record_id in record_ids.items():
        create_revision_id = str(uuid.uuid4())
        create = world.make_envelope(
            tenant,
            owner,
            operation="create",
            record_id=record_id,
            revision_id=create_revision_id,
        )
        create_response = world.clients[0].request(
            "POST",
            f"/api/v1/vaults/{tenant.vault_id}/sync/push",
            token=owner.access_token,
            json_body=world.push_body(tenant, owner, [create]),
            additional_headers=redaction_marker,
        )
        create_body = create_response.json()
        _require(
            create_response.status == 200
            and isinstance(create_body, dict)
            and len(create_body.get("results", [])) == 1,
            "the disposable fixture must create each synthetic record through the signed sync API",
        )

        deleted_revision_id = str(uuid.uuid4())
        delete = world.make_envelope(
            tenant,
            owner,
            operation="delete",
            record_id=record_id,
            revision_id=deleted_revision_id,
            base_revision_id=create_revision_id,
        )
        delete_response = world.clients[0].request(
            "POST",
            f"/api/v1/vaults/{tenant.vault_id}/sync/push",
            token=owner.access_token,
            json_body=world.push_body(tenant, owner, [delete]),
            additional_headers=redaction_marker,
        )
        delete_body = delete_response.json()
        delete_results = delete_body.get("results") if isinstance(delete_body, dict) else None
        _require(
            delete_response.status == 200
            and isinstance(delete_results, list)
            and len(delete_results) == 1
            and isinstance(delete_results[0].get("commit_seq"), str),
            "the disposable fixture must create each exact tombstone through the signed sync API",
        )
        tombstones[name] = (deleted_revision_id, delete_results[0]["commit_seq"])

    for name in ("expired_opted_in", "not_due_opted_in"):
        record_id = record_ids[name]
        deleted_revision_id, deleted_seq = tombstones[name]
        consent = world.clients[0].request(
            "PUT",
            f"/api/v1/vaults/{tenant.vault_id}/records/{record_id}/automatic-purge",
            token=owner.access_token,
            json_body={
                "expected_deleted_revision_id": deleted_revision_id,
                "expected_deleted_seq": deleted_seq,
                "expected_policy_revision": "0",
                "enabled": True,
            },
            additional_headers=redaction_marker,
        )
        _require(
            consent.status == 200 and (consent.json() or {}).get("enabled") is True,
            "Owner consent must apply to each opted-in exact tombstone",
        )

    database.execute(
        "UPDATE record_versions SET restore_until=CASE \
             WHEN record_id=%s THEN clock_timestamp()-INTERVAL '1 second' \
             WHEN record_id=%s THEN clock_timestamp()+INTERVAL '1 hour' \
             ELSE clock_timestamp()-INTERVAL '1 second' END \
         WHERE vault_id=%s AND operation='delete' AND record_id=ANY(%s::text[])",
        (
            record_ids["expired_opted_in"],
            record_ids["not_due_opted_in"],
            tenant.vault_id,
            list(record_ids.values()),
        ),
    )

    endpoint_id = str(uuid.uuid4())
    endpoint_token = b64url(os.urandom(32))
    world.remember_secret(endpoint_token)
    now = int(time.time())
    database.execute(
        "INSERT INTO notification_push_endpoints( \
             endpoint_id,device_id,user_id,provider,token_hash,token_envelope,created_at,updated_at \
         ) VALUES (%s,%s,%s,'fcm_v1',%s,%s,%s,%s)",
        (
            endpoint_id,
            owner.device_id,
            owner.user_id,
            hashlib.sha256(endpoint_token.encode("ascii")).hexdigest(),
            b64url(os.urandom(64)),
            now,
            now,
        ),
    )
    target_ids = list(record_ids.values())
    before_sequence = database.execute(
        "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s",
        (tenant.vault_id,),
    ).fetchone()[0]
    _require(
        before_sequence == 6
        and database.execute(
            "SELECT COUNT(*) FROM record_redactions WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (tenant.vault_id, target_ids),
        ).fetchone()[0]
        == 0,
        "the three disposable tombstones must remain unpurged until the explicit admin job",
    )

    def run_admin_maintenance(request_id: str) -> dict[str, Any]:
        submitted = world.clients[0].request(
            "POST",
            "/api/v1/admin/jobs",
            token=admin.access_token,
            json_body={"request_id": request_id, "action": "maintenance"},
        )
        submitted_job = (submitted.json() or {}).get("job", {})
        _require(
            submitted.status == 202
            and submitted_job.get("status") == "queued"
            and submitted_job.get("action") == "maintenance",
            "an instance administrator must explicitly enqueue the shared Maintenance job",
        )
        job_id = submitted_job.get("job_id")
        _require(isinstance(job_id, str), "the queued Maintenance job must have a shared ID")
        deadline = time.monotonic() + 15
        while time.monotonic() < deadline:
            page = world.clients[1].request(
                "GET", "/api/v1/admin/jobs?limit=20&offset=0", token=admin.access_token
            )
            _require(page.status == 200, "node B must read the shared Maintenance job state")
            jobs = (page.json() or {}).get("jobs", [])
            matches = [job for job in jobs if job.get("job_id") == job_id]
            if matches and matches[0].get("status") in {"succeeded", "failed"}:
                _require(
                    matches[0].get("status") == "succeeded"
                    and matches[0].get("result_code") == "completed",
                    "the explicit Maintenance job must complete successfully",
                )
                return matches[0]
            time.sleep(0.05)
        pytest.fail("node B did not observe the Maintenance job finish", pytrace=False)

    run_admin_maintenance(str(uuid.uuid4()))

    due_record = record_ids["expired_opted_in"]
    future_record = record_ids["not_due_opted_in"]
    disabled_record = record_ids["expired_unconsented"]
    graves = database.execute(
        "SELECT record_id,auto_purge_enabled,auto_purge_revision FROM record_graveyard \
         WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
        (tenant.vault_id, target_ids),
    ).fetchall()
    heads = database.execute(
        "SELECT record_id FROM record_heads WHERE vault_id=%s AND record_id=ANY(%s::text[]) \
         ORDER BY record_id",
        (tenant.vault_id, target_ids),
    ).fetchall()
    redactions = database.execute(
        "SELECT record_id,deleted_seq,redaction_seq FROM record_redactions \
         WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
        (tenant.vault_id, target_ids),
    ).fetchall()
    purge_audits = database.execute(
        "SELECT resource_id,actor_user_id,actor_device_id,source,result FROM audit_events \
         WHERE scope_type='vault' AND scope_id=%s AND action='vault.record_purged' \
           AND resource_id=ANY(%s::text[]) ORDER BY resource_id",
        (tenant.vault_id, target_ids),
    ).fetchall()
    first_outbox_sequence = database.execute(
        "SELECT requested_seq FROM notification_push_outbox WHERE endpoint_id=%s",
        (endpoint_id,),
    ).fetchone()
    first_final_sequence = database.execute(
        "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s",
        (tenant.vault_id,),
    ).fetchone()[0]
    scan_summary = database.execute(
        "SELECT last_scan_status,last_scan_candidates,last_scan_purged,last_scan_not_due \
         FROM record_auto_purge_scan_control WHERE singleton=1",
    ).fetchone()
    grave_by_record = {row[0]: (row[1], row[2]) for row in graves}
    _require(
        redactions == [(due_record, int(tombstones["expired_opted_in"][1]), 7)]
        and set(row[0] for row in heads) == {future_record, disabled_record}
        and grave_by_record
        == {
            due_record: (False, 2),
            future_record: (True, 1),
            disabled_record: (False, 0),
        }
        and purge_audits == [(due_record, None, None, "maintenance", "success")]
        and first_outbox_sequence == (1,)
        and first_final_sequence == before_sequence + 1
        and scan_summary == ("completed", 2, 1, 1),
        "Maintenance must purge only the expired opted-in tombstone with one proof, audit, sequence, and push hint",
    )
    scrubbed_due_version = database.execute(
        "SELECT envelope,digest,device_id FROM record_versions \
         WHERE vault_id=%s AND record_id=%s AND revision_id=%s",
        (tenant.vault_id, due_record, tombstones["expired_opted_in"][0]),
    ).fetchone()
    _require(
        scrubbed_due_version == ("{}", "", ""),
        "the purged synthetic tombstone payload must be scrubbed",
    )

    cross_node_changes = world.clients[1].request(
        "GET",
        f"/api/v1/vaults/{tenant.vault_id}/changes?limit=100",
        token=second_device.access_token,
        additional_headers=redaction_marker,
    )
    change_events = (cross_node_changes.json() or {}).get("events", [])
    _require(
        cross_node_changes.status == 200
        and any(
            event.get("record_id") == due_record
            and event.get("commit_seq") == "7"
            and event.get("event_type") == "record_redacted"
            for event in change_events
            if isinstance(event, dict)
        ),
        "node B must expose the committed redaction marker for the purged record",
    )

    run_admin_maintenance(str(uuid.uuid4()))
    repeated_state = (
        database.execute(
            "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s",
            (tenant.vault_id,),
        ).fetchone()[0],
        database.execute(
            "SELECT COUNT(*) FROM record_redactions WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (tenant.vault_id, target_ids),
        ).fetchone()[0],
        database.execute(
            "SELECT COUNT(*) FROM audit_events WHERE scope_type='vault' AND scope_id=%s \
             AND action='vault.record_purged' AND resource_id=ANY(%s::text[])",
            (tenant.vault_id, target_ids),
        ).fetchone()[0],
        database.execute(
            "SELECT requested_seq FROM notification_push_outbox WHERE endpoint_id=%s",
            (endpoint_id,),
        ).fetchone()[0],
    )
    _require(
        repeated_state == (first_final_sequence, 1, 1, 1),
        "a repeated Maintenance job must not duplicate proof, audit, sequence, or push-outbox effects",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_auto_purge_web_acceptance"],
    indirect=True,
    scope="module",
)
def test_pg_http_web_automatic_purge_consent_and_cross_device_redaction_acceptance(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    """Owner Web consent drives PG due-only purge and a second Web device applies redaction."""
    world = pg_http_world
    username = PG_ADMIN_AUTO_PURGE_USERNAME
    password = f"PgAutoPurge-{uuid.uuid4().hex}-A9"
    bootstrap_token = world.bootstrap_token()
    run_id = uuid.uuid4().hex[:8]
    ssh_username = f"pg-purge-{run_id}"
    host_address = "192.0.2.65"
    markers = [
        username,
        password,
        bootstrap_token,
        ssh_username,
        host_address,
        f"PG purge eligible {run_id}",
        f"PG purge future {run_id}",
        f"PG purge disabled {run_id}",
    ]
    for marker in markers:
        world.remember_secret(marker)

    node = shutil.which("node")
    _require(node is not None, "PG auto-purge Web acceptance requires Node.js")
    control_dir = tmp_path / "pg-auto-purge-control"
    control_dir.mkdir(mode=0o700)
    if os.name == "posix":
        os.chmod(control_dir, 0o700)
    output_path = tmp_path / "pg-auto-purge-web.log"
    runner_env = {
        key: os.environ[key]
        for key in (
            "PATH",
            "HOME",
            "TMPDIR",
            "TMP",
            "TEMP",
            "XDG_CACHE_HOME",
            "CI",
            "PLAYWRIGHT_BROWSERS_PATH",
            "PLAYWRIGHT_CHROMIUM_EXECUTABLE",
        )
        if key in os.environ
    }
    runner_env.update(
        {
            "ATERMIUS_PG_AUTO_PURGE_BASE_URL": world.runtime_env[
                "ATERMIUS_PUBLIC_ORIGIN"
            ],
            "ATERMIUS_PG_AUTO_PURGE_NODE_A_URL": world.clients[0].base_url,
            "ATERMIUS_PG_AUTO_PURGE_NODE_B_URL": world.clients[1].base_url,
            "ATERMIUS_PG_AUTO_PURGE_USERNAME": username,
            "ATERMIUS_PG_AUTO_PURGE_PASSWORD": password,
            "ATERMIUS_PG_AUTO_PURGE_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_AUTO_PURGE_CONTROL_DIR": str(control_dir),
            "ATERMIUS_PG_AUTO_PURGE_RUN_ID": run_id,
        }
    )

    process: subprocess.Popen[bytes] | None = None
    output_handle = None
    runner_output = ""

    def runner_log_tail() -> str:
        if output_handle is not None:
            output_handle.flush()
        try:
            raw = output_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return ""
        return redact_secrets(raw, *world.secrets)[-8000:]

    def wait_for_gate(filename: str, timeout_seconds: float = 240.0) -> dict[str, Any]:
        gate_path = control_dir / filename
        deadline = time.monotonic() + timeout_seconds
        while time.monotonic() < deadline:
            if gate_path.is_file():
                try:
                    value = json.loads(gate_path.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    time.sleep(0.05)
                    continue
                _require(isinstance(value, dict), "PG Web runner gate must contain a JSON object")
                return value
            if process is not None and process.poll() is not None:
                pytest.fail(
                    "PG auto-purge Chromium runner exited before a PostgreSQL gate; redacted output: "
                    + runner_log_tail(),
                    pytrace=False,
                )
            time.sleep(0.1)
        pytest.fail(
            f"PG auto-purge Chromium runner did not reach {filename}; redacted output: "
            + runner_log_tail(),
            pytrace=False,
        )

    def release_gate(name: str) -> None:
        release_path = control_dir / f"release_{name}"
        descriptor = os.open(release_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        os.close(descriptor)

    database = world.database_connection
    try:
        output_handle = output_path.open("wb")
        process = subprocess.Popen(
            [node, str(ROOT / "integration" / "web" / "pg_auto_purge.cjs")],
            cwd=ROOT,
            env=runner_env,
            stdout=output_handle,
            stderr=subprocess.STDOUT,
            start_new_session=(os.name == "posix"),
        )

        ready = wait_for_gate("consent_ready.json", timeout_seconds=360.0)
        _require(
            set(ready)
            == {
                "vault_id",
                "account_id",
                "owner_device_id",
                "second_device_id",
                "records",
                "capability_reports_observed",
            }
            and ready.get("capability_reports_observed") == {"A": True, "B": True}
            and ready.get("owner_device_id") != ready.get("second_device_id"),
            "Web journey must reach the due-date gate with two active reported devices",
        )
        vault_id = ready["vault_id"]
        account_id = ready["account_id"]
        record_map = ready["records"]
        _require(
            set(record_map) == {"eligible", "future", "disabled"}
            and all(
                set(item)
                == {
                    "record_id",
                    "create_revision_id",
                    "create_seq",
                    "deleted_revision_id",
                    "deleted_seq",
                    "auto_purge_enabled",
                }
                for item in record_map.values()
            ),
            "Web journey must report the three exact Host create/delete identities",
        )
        target_ids = [record_map[key]["record_id"] for key in ("eligible", "future", "disabled")]
        _require(
            all(
                isinstance(value, str)
                and re.fullmatch(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", value)
                for value in target_ids
            )
            and len(set(target_ids)) == 3,
            "Web Host record identities must be three distinct canonical UUIDs",
        )
        _require(
            record_map["eligible"]["auto_purge_enabled"] is True
            and record_map["future"]["auto_purge_enabled"] is True
            and record_map["disabled"]["auto_purge_enabled"] is False,
            "only the two tombstones explicitly consented to in the Web UI may be opted in",
        )

        devices = database.execute(
            "SELECT d.device_id,d.user_id,d.status,r.revision,r.sync_redaction_version,r.invalidated_at "
            "FROM devices d LEFT JOIN device_redaction_capability_reports r "
            "ON r.device_id=d.device_id AND r.account_id=d.user_id "
            "WHERE d.user_id=%s AND d.device_id=ANY(%s::text[]) ORDER BY d.device_id",
            (account_id, [ready["owner_device_id"], ready["second_device_id"]]),
        ).fetchall()
        device_capability_diagnostic = {
            "requested_device_rows": len(devices),
            "requested_devices_match": {row[0] for row in devices}
            == {ready["owner_device_id"], ready["second_device_id"]},
            "devices": [
                {
                    "active": row[2] == "active",
                    "report_present": row[3] is not None,
                    "revision": row[3],
                    "redaction_version": row[4],
                    "report_invalidated": row[5] is not None,
                }
                for row in devices
            ],
            "active_account_device_count": database.execute(
                "SELECT COUNT(*) FROM devices WHERE user_id=%s AND status='active'",
                (account_id,),
            ).fetchone()[0],
        }
        _require(
            len(devices) == 2
            and {row[0] for row in devices}
            == {ready["owner_device_id"], ready["second_device_id"]}
            and all(
                row[1] == account_id
                and row[2] == "active"
                and row[3] is not None
                and row[3] >= 1
                and row[4] == 1
                and row[5] is None
                for row in devices
            )
            and database.execute(
                "SELECT COUNT(*) FROM devices WHERE user_id=%s AND status='active'",
                (account_id,),
            ).fetchone()[0]
            == 2,
            "both and only active Web devices must have valid redaction-v1 capability reports before purge: "
            + json.dumps(device_capability_diagnostic, sort_keys=True),
        )

        endpoint_id = str(uuid.uuid4())
        endpoint_token = secrets.token_urlsafe(32)
        world.remember_secret(endpoint_token)
        now = int(time.time())
        database.execute(
            "INSERT INTO notification_push_endpoints("
            "endpoint_id,device_id,user_id,provider,token_hash,token_envelope,created_at,updated_at) "
            "VALUES (%s,%s,%s,'fcm_v1',%s,%s,%s,%s)",
            (
                endpoint_id,
                ready["owner_device_id"],
                account_id,
                hashlib.sha256(endpoint_token.encode("ascii")).hexdigest(),
                b64url(os.urandom(64)),
                now,
                now,
            ),
        )
        _require(
            database.execute(
                "SELECT COUNT(*) FROM notification_push_outbox WHERE endpoint_id=%s",
                (endpoint_id,),
            ).fetchone()[0]
            == 0,
            "the synthetic owner notification endpoint must start without a push hint",
        )

        grave_rows = database.execute(
            "SELECT record_id,deleted_revision,deleted_seq,auto_purge_enabled,auto_purge_revision "
            "FROM record_graveyard WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
            (vault_id, target_ids),
        ).fetchall()
        grave_by_id = {row[0]: row[1:] for row in grave_rows}
        expected_graves = {
            record_map["eligible"]["record_id"]: (
                record_map["eligible"]["deleted_revision_id"],
                int(record_map["eligible"]["deleted_seq"]),
                True,
                1,
            ),
            record_map["future"]["record_id"]: (
                record_map["future"]["deleted_revision_id"],
                int(record_map["future"]["deleted_seq"]),
                True,
                1,
            ),
            record_map["disabled"]["record_id"]: (
                record_map["disabled"]["deleted_revision_id"],
                int(record_map["disabled"]["deleted_seq"]),
                False,
                0,
            ),
        }
        _require(
            grave_by_id == expected_graves,
            "PostgreSQL owner consent must update only its exact tombstone rows and policy revisions",
        )
        versions_before = database.execute(
            "SELECT record_id,revision_id,commit_seq,restore_until>clock_timestamp() "
            "FROM record_versions WHERE vault_id=%s AND operation='delete' "
            "AND record_id=ANY(%s::text[]) ORDER BY record_id",
            (vault_id, target_ids),
        ).fetchall()
        version_by_record = {row[0]: row[1:] for row in versions_before}
        _require(
            len(version_by_record) == 3
            and all(
                version_by_record[record_map[key]["record_id"]]
                == (
                    record_map[key]["deleted_revision_id"],
                    int(record_map[key]["deleted_seq"]),
                    True,
                )
                for key in ("eligible", "future", "disabled")
            ),
            "each exact tombstone must still have a future restore deadline when UI consent is recorded",
        )
        _require(
            database.execute(
                "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s", (vault_id,)
            ).fetchone()[0]
            == 6
            and database.execute(
                "SELECT COUNT(*) FROM record_redactions WHERE vault_id=%s AND record_id=ANY(%s::text[])",
                (vault_id, target_ids),
            ).fetchone()[0]
            == 0,
            "the three Web tombstones must remain unredacted before the gated maintenance pass",
        )

        release_gate("invalidate")
        invalidated = wait_for_gate("report_invalidated.json", timeout_seconds=240.0)
        _require(
            set(invalidated)
            == {
                "account_id",
                "owner_device_id",
                "second_device_id",
                "report_revision_before",
                "markerless_sync_observed",
                "readiness",
            }
            and invalidated.get("account_id") == account_id
            and invalidated.get("owner_device_id") == ready["owner_device_id"]
            and invalidated.get("second_device_id") == ready["second_device_id"]
            and isinstance(invalidated.get("report_revision_before"), int)
            and invalidated.get("markerless_sync_observed") is True
            and invalidated.get("readiness") == "invalidated",
            "Web UI must observe the invalidated report after an authenticated markerless sync request",
        )
        invalidated_report = database.execute(
            "SELECT revision,sync_redaction_version,invalidated_at "
            "FROM device_redaction_capability_reports WHERE device_id=%s AND account_id=%s",
            (ready["second_device_id"], account_id),
        ).fetchone()
        _require(
            invalidated_report is not None
            and invalidated_report[0] == invalidated["report_revision_before"]
            and invalidated_report[1] == 1
            and invalidated_report[2] is not None,
            "the markerless sync request must invalidate device B's existing report without erasing its revision",
        )
        invalidated_revision = invalidated_report[0]

        eligible = record_map["eligible"]
        aged = database.execute(
            "UPDATE record_versions v SET restore_until=clock_timestamp()-INTERVAL '1 second' "
            "WHERE v.vault_id=%s AND v.record_id=%s AND v.revision_id=%s "
            "AND v.operation='delete' AND v.restore_until>clock_timestamp() "
            "AND EXISTS(SELECT 1 FROM record_graveyard g WHERE g.vault_id=v.vault_id "
            "AND g.record_id=v.record_id AND g.deleted_revision=v.revision_id "
            "AND g.deleted_seq=v.commit_seq AND g.auto_purge_enabled=TRUE) "
            "RETURNING v.restore_until",
            (vault_id, eligible["record_id"], eligible["deleted_revision_id"]),
        ).fetchone()
        _require(aged is not None, "pytest may age only the exact opted-in target tombstone")
        disabled = record_map["disabled"]
        disabled_aged = database.execute(
            "UPDATE record_versions v SET restore_until=clock_timestamp()-INTERVAL '1 second' "
            "WHERE v.vault_id=%s AND v.record_id=%s AND v.revision_id=%s "
            "AND v.operation='delete' AND v.restore_until>clock_timestamp() "
            "AND EXISTS(SELECT 1 FROM record_graveyard g WHERE g.vault_id=v.vault_id "
            "AND g.record_id=v.record_id AND g.deleted_revision=v.revision_id "
            "AND g.deleted_seq=v.commit_seq AND g.auto_purge_enabled=FALSE) "
            "RETURNING v.restore_until",
            (vault_id, disabled["record_id"], disabled["deleted_revision_id"]),
        ).fetchone()
        _require(
            disabled_aged is not None,
            "pytest may age the disabled control only after matching its opted-out graveyard tuple",
        )
        release_gate("blocked")

        blocked = wait_for_gate("blocked_purge.json", timeout_seconds=240.0)
        _require(
            set(blocked) == {"job_id", "request_id"}
            and isinstance(blocked.get("job_id"), str)
            and isinstance(blocked.get("request_id"), str),
            "Web Maintenance while a Vault report is invalidated must complete as a durable job",
        )
        blocked_scan = database.execute(
            "SELECT last_scan_status,last_scan_candidates,last_scan_purged,last_scan_not_due,"
            "last_scan_capability_blocked,last_scan_conflict_blocked,last_scan_reference_blocked "
            "FROM record_auto_purge_scan_control WHERE singleton=1"
        ).fetchone()
        blocked_sequence = database.execute(
            "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s", (vault_id,)
        ).fetchone()[0]
        blocked_redactions = database.execute(
            "SELECT COUNT(*) FROM record_redactions WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (vault_id, target_ids),
        ).fetchone()[0]
        blocked_audits = database.execute(
            "SELECT COUNT(*) FROM audit_events WHERE scope_type='vault' AND scope_id=%s "
            "AND action='vault.record_purged' AND resource_id=ANY(%s::text[])",
            (vault_id, target_ids),
        ).fetchone()[0]
        blocked_outbox = database.execute(
            "SELECT COUNT(*) FROM notification_push_outbox WHERE endpoint_id=%s", (endpoint_id,)
        ).fetchone()[0]
        _require(
            blocked_scan is not None
            and blocked_scan[0] == "completed"
            and blocked_scan[2] == 0
            and blocked_scan[4] >= 1
            and blocked_sequence == 6
            and blocked_redactions == 0
            and blocked_audits == 0
            and blocked_outbox == 0,
            "invalidated readiness must block Maintenance without redaction, sequence, purge audit, or push outbox effects: "
            + json.dumps(
                {
                    "scan": blocked_scan,
                    "sequence": blocked_sequence,
                    "redactions": blocked_redactions,
                    "purge_audits": blocked_audits,
                    "push_outbox": blocked_outbox,
                },
                sort_keys=True,
            ),
        )
        blocked_report = database.execute(
            "SELECT revision,invalidated_at FROM device_redaction_capability_reports "
            "WHERE device_id=%s AND account_id=%s",
            (ready["second_device_id"], account_id),
        ).fetchone()
        _require(
            blocked_report is not None
            and blocked_report[0] == invalidated_revision
            and blocked_report[1] is not None,
            "blocked Maintenance must leave device B's invalidated report revision unchanged",
        )

        release_gate("recovery")
        recovered = wait_for_gate("report_recovered.json", timeout_seconds=240.0)
        _require(
            set(recovered)
            == {"account_id", "second_device_id", "report_revision", "readiness"}
            and recovered.get("account_id") == account_id
            and recovered.get("second_device_id") == ready["second_device_id"]
            and isinstance(recovered.get("report_revision"), int)
            and recovered["report_revision"] > invalidated_revision
            and recovered.get("readiness") == "ready",
            "Web UI must verify readiness after device B publishes a higher report revision",
        )
        recovered_report = database.execute(
            "SELECT revision,sync_redaction_version,invalidated_at "
            "FROM device_redaction_capability_reports WHERE device_id=%s AND account_id=%s",
            (ready["second_device_id"], account_id),
        ).fetchone()
        _require(
            recovered_report is not None
            and recovered_report[0] == recovered["report_revision"]
            and recovered_report[0] > invalidated_revision
            and recovered_report[1] == 1
            and recovered_report[2] is None,
            "device B must republish a higher valid redaction-v1 report before Maintenance can proceed",
        )
        release_gate("purge")

        first = wait_for_gate("first_purge.json", timeout_seconds=240.0)
        _require(
            first.get("vault_id") == vault_id
            and first.get("target_record_id") == eligible["record_id"]
            and isinstance(first.get("job_id"), str)
            and isinstance(first.get("request_id"), str),
            "first Settings Maintenance completion must identify the target Vault and job",
        )

        def assert_first_purge_state() -> tuple[Any, ...]:
            sequence = database.execute(
                "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s", (vault_id,)
            ).fetchone()[0]
            redactions = database.execute(
                "SELECT redaction_id,record_id,deleted_revision_id,deleted_seq,redaction_seq "
                "FROM record_redactions "
                "WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
                (vault_id, target_ids),
            ).fetchall()
            heads = database.execute(
                "SELECT record_id FROM record_heads WHERE vault_id=%s AND record_id=ANY(%s::text[]) "
                "ORDER BY record_id",
                (vault_id, target_ids),
            ).fetchall()
            graves = database.execute(
                "SELECT record_id,auto_purge_enabled,auto_purge_revision FROM record_graveyard "
                "WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
                (vault_id, target_ids),
            ).fetchall()
            audits = database.execute(
                "SELECT resource_id,actor_user_id,actor_device_id,source,result FROM audit_events "
                "WHERE scope_type='vault' AND scope_id=%s AND action='vault.record_purged' "
                "AND resource_id=ANY(%s::text[]) ORDER BY resource_id",
                (vault_id, target_ids),
            ).fetchall()
            return sequence, redactions, heads, graves, audits

        sequence, redactions, heads, graves, purge_audits = assert_first_purge_state()
        grave_after = {row[0]: (row[1], row[2]) for row in graves}
        _require(
            sequence == 7
            and len(redactions) == 1
            and redactions[0][1:] == (
                eligible["record_id"],
                eligible["deleted_revision_id"],
                int(eligible["deleted_seq"]),
                7,
            )
            and {row[0] for row in heads}
            == {record_map["future"]["record_id"], record_map["disabled"]["record_id"]}
            and grave_after
            == {
                record_map["eligible"]["record_id"]: (False, 2),
                record_map["future"]["record_id"]: (True, 1),
                record_map["disabled"]["record_id"]: (False, 0),
            }
            and purge_audits == [(eligible["record_id"], None, None, "maintenance", "success")],
            "the first PG Maintenance pass must redact only the due consented tombstone",
        )

        scan = database.execute(
            "SELECT last_scan_status,last_scan_candidates,last_scan_purged,last_scan_not_due,"
            "last_scan_capability_blocked,last_scan_conflict_blocked,last_scan_reference_blocked "
            "FROM record_auto_purge_scan_control WHERE singleton=1"
        ).fetchone()
        _require(
            scan == ("completed", 2, 1, 1, 0, 0, 0),
            "the PG scan must count both opted-in rows, purge only the due row, and leave the future row not due",
        )
        _require(
            database.execute(
                "SELECT endpoint_id,requested_seq FROM notification_push_outbox WHERE endpoint_id=%s",
                (endpoint_id,),
            ).fetchall()
            == [(endpoint_id, 1)],
            "the eligible purge must enqueue one durable sync hint for the active owner device",
        )
        scrubbed = database.execute(
            "SELECT revision_id,envelope,digest,device_id FROM record_versions "
            "WHERE vault_id=%s AND record_id=%s ORDER BY commit_seq",
            (vault_id, eligible["record_id"]),
        ).fetchall()
        _require(
            scrubbed
            == [
                (eligible["create_revision_id"], "{}", "", ""),
                (eligible["deleted_revision_id"], "{}", "", ""),
            ],
            "purging must scrub both ciphertext revisions and retain exact ID-only history",
        )
        redacted_history = database.execute(
            "SELECT commit_seq,event_type,revision_id,envelope FROM change_events "
            "WHERE vault_id=%s AND record_id=%s ORDER BY commit_seq",
            (vault_id, eligible["record_id"]),
        ).fetchall()
        _require(
            redacted_history
            == [
                (int(eligible["create_seq"]), "redacted", "", "{}"),
                (int(eligible["deleted_seq"]), "redacted", "", "{}"),
                (7, "record_redacted", "", "{}"),
            ],
            "the PG feed ledger must preserve only redaction-safe history and one redaction marker",
        )
        _require(
            database.execute(
                "SELECT revision_id FROM record_redacted_revisions WHERE vault_id=%s "
                "AND record_id=%s ORDER BY revision_id",
                (vault_id, eligible["record_id"]),
            ).fetchall()
            == sorted(
                [
                    (eligible["create_revision_id"],),
                    (eligible["deleted_revision_id"],),
                ]
            ),
            "redaction history must retain both revision identifiers without their ciphertext",
        )
        still_encrypted = database.execute(
            "SELECT record_id,COUNT(*) FILTER (WHERE envelope<>'{}' AND digest<>'' AND device_id<>'') "
            "FROM record_versions WHERE vault_id=%s AND record_id=ANY(%s::text[]) "
            "GROUP BY record_id",
            (vault_id, [record_map["future"]["record_id"], record_map["disabled"]["record_id"]]),
        ).fetchall()
        _require(
            len(still_encrypted) == 2 and all(row[1] == 2 for row in still_encrypted),
            "future-consented and disabled tombstones must retain their encrypted revision history",
        )
        disabled_due_state = database.execute(
            "SELECT v.restore_until<=clock_timestamp(),h.deleted,g.deleted_revision,g.deleted_seq,"
            "g.auto_purge_enabled,g.auto_purge_revision "
            "FROM record_versions v JOIN record_heads h ON h.vault_id=v.vault_id "
            "AND h.record_id=v.record_id JOIN record_graveyard g ON g.vault_id=v.vault_id "
            "AND g.record_id=v.record_id WHERE v.vault_id=%s AND v.record_id=%s "
            "AND v.revision_id=%s",
            (vault_id, disabled["record_id"], disabled["deleted_revision_id"]),
        ).fetchone()
        _require(
            disabled_due_state
            == (
                True,
                True,
                disabled["deleted_revision_id"],
                int(disabled["deleted_seq"]),
                False,
                0,
            ),
            "the due but opted-out control must retain its current deleted head, payload and disabled policy",
        )
        ledger_text = database.execute(
            "SELECT COALESCE(string_agg(envelope,' '),'') FROM record_versions "
            "WHERE vault_id=%s AND record_id=ANY(%s::text[])",
            (vault_id, target_ids),
        ).fetchone()[0]
        _require(
            all(marker not in ledger_text for marker in markers),
            "synthetic Host plaintext must not appear in PostgreSQL revision envelopes",
        )

        def purge_ledger_snapshot() -> tuple[Any, ...]:
            return (
                database.execute(
                    "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s", (vault_id,)
                ).fetchone()[0],
                tuple(
                    database.execute(
                        "SELECT redaction_id,vault_id,record_id,deleted_revision_id,deleted_seq,"
                        "redaction_seq,created_at "
                        "FROM record_redactions "
                        "WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT record_id,revision_id,deleted,commit_seq FROM record_heads "
                        "WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT record_id,deleted_revision,deleted_seq,auto_purge_enabled,auto_purge_revision "
                        "FROM record_graveyard WHERE vault_id=%s AND record_id=ANY(%s::text[]) "
                        "ORDER BY record_id",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT record_id,revision_id,base_revision_id,envelope,digest,commit_seq,device_id,"
                        "operation,created_at,restore_until "
                        "FROM record_versions WHERE vault_id=%s AND record_id=ANY(%s::text[]) "
                        "ORDER BY record_id,commit_seq",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT commit_seq,event_type,record_id,revision_id,envelope,created_at FROM change_events "
                        "WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY commit_seq",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT record_id,revision_id FROM record_redacted_revisions "
                        "WHERE vault_id=%s AND record_id=ANY(%s::text[]) ORDER BY record_id,revision_id",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT event_id,scope_type,scope_id,actor_user_id,actor_device_id,action,"
                        "resource_type,resource_id,result,occurred_at,source FROM audit_events "
                        "WHERE scope_type='vault' AND scope_id=%s AND action='vault.record_purged' "
                        "AND resource_id=ANY(%s::text[]) ORDER BY resource_id",
                        (vault_id, target_ids),
                    ).fetchall()
                ),
                tuple(
                    database.execute(
                        "SELECT endpoint_id,requested_seq,delivered_seq,attempt_count,next_attempt_at,"
                        "lease_id,lease_until,dead_lettered,updated_at FROM notification_push_outbox "
                        "WHERE endpoint_id=%s ORDER BY endpoint_id",
                        (endpoint_id,),
                    ).fetchall()
                ),
            )

        first_ledger_snapshot = purge_ledger_snapshot()
        release_gate("repeat")

        _require(process is not None, "PG auto-purge browser runner did not start")
        try:
            process.wait(timeout=240)
        except subprocess.TimeoutExpired:
            _stop_acceptance_process(process)
            pytest.fail(
                "PG auto-purge Chromium runner timed out after the first purge; redacted output: "
                + runner_log_tail(),
                pytrace=False,
            )
        output_handle.flush()
        runner_output = runner_log_tail()
        _require(
            process.returncode == 0,
            "PG auto-purge Chromium acceptance failed; redacted output: " + runner_output,
        )
        result_match = re.search(
            r"^PG_AUTO_PURGE_RESULT:(\{[^\n]+\})$", runner_output, re.MULTILINE
        )
        _require(result_match is not None, "PG auto-purge browser runner omitted its safe result")
        result = json.loads(result_match.group(1))
        _require(
            result.get("vaultId") == vault_id
            and result.get("accountId") == account_id
            and result.get("ownerDeviceId") == ready["owner_device_id"]
            and result.get("secondDeviceId") == ready["second_device_id"]
            and result.get("capabilityReportsObserved") is True
            and result.get("secondDeviceAppliedRedaction") is True
            and result.get("privacyMarkersAbsent") is True
            and result.get("manualPurgeRequests") == 0
            and result.get("browserCleanupComplete") is True
            and result.get("pageErrors") == 0
            and result.get("apiRequestFailures") == 0,
            "Web acceptance must prove consent persistence, redaction-v1 sync, privacy, and cleanup",
        )
        feed = result.get("crossNodeFeed", {})
        proof = feed.get("proof", {})
        current_instances = [
            client.request("GET", "/api/v1/instance").json() for client in world.clients
        ]
        current_instance_keys = [
            current.get("signing_public_key") for current in current_instances
        ]
        stored_instance = database.execute(
            "SELECT signing_public_key,signing_key_transitions_json FROM instance_meta WHERE id=1"
        ).fetchone()
        stored_transitions = json.loads(stored_instance[1]) if stored_instance else []
        key_fingerprint = lambda value: hashlib.sha256(
            str(value or "").encode("utf-8")
        ).hexdigest()[:12]
        trusted_transition_keys = {
            key_fingerprint(key)
            for transition in stored_transitions
            if isinstance(transition, dict)
            for key in (transition.get("from_public_key"), transition.get("to_public_key"))
            if isinstance(key, str)
        }
        feed_checks = {
            "node_b": feed.get("node") == "B",
            "event_type": feed.get("eventType") == "record_redacted",
            "record_matches": feed.get("recordId") == eligible["record_id"]
            and proof.get("recordId") == eligible["record_id"],
            "commit_sequence": feed.get("commitSeq") == "7"
            and proof.get("redactionSeq") == "7",
            "redaction_id_matches_ledger": proof.get("redactionId") == redactions[0][0],
            "instance_matches": proof.get("instanceId") == world.instance["instance_id"],
            "server_space_matches": proof.get("serverSpaceId") == world.instance["server_space_id"],
            "vault_matches": proof.get("vaultId") == vault_id,
            "deleted_revision_matches": proof.get("deletedRevisionId")
            == eligible["deleted_revision_id"],
            "deleted_sequence_matches": proof.get("deletedSeq") == str(eligible["deleted_seq"]),
            "signing_key_matches": proof.get("signingPublicKeyFingerprint")
            == key_fingerprint(world.instance["signing_public_key"]),
            "signature_present": proof.get("signaturePresent") is True,
            "signature_valid": proof.get("signatureValid") is True,
            "marker_free": feed.get("markerFree") is True,
        }
        _require(
            all(feed_checks.values()),
            "B must receive the exact marker-free record_redacted feed event through PostgreSQL node B: "
            + json.dumps({
                "checks": feed_checks,
                "proof_signing_key_fingerprint": proof.get("signingPublicKeyFingerprint"),
                "startup_signing_key_fingerprint": key_fingerprint(
                    world.instance.get("signing_public_key")
                ),
                "current_node_key_matches_proof": [
                    key_fingerprint(key) == proof.get("signingPublicKeyFingerprint")
                    for key in current_instance_keys
                ],
                "proof_key_in_transition_chain": proof.get("signingPublicKeyFingerprint")
                in trusted_transition_keys,
                "transition_count": len(stored_transitions),
                "stored_instance_key_matches_proof": bool(stored_instance)
                and key_fingerprint(stored_instance[0])
                == proof.get("signingPublicKeyFingerprint"),
            }, sort_keys=True),
        )
        _require(
            proof.get("signaturePresent") is True,
            "the redaction feed must include the server-signed proof bound to the exact PG statement",
        )
        expected_consent_requests = {
            (record_map[key]["record_id"], record_map[key]["deleted_revision_id"],
             int(record_map[key]["deleted_seq"]))
            for key in ("eligible", "future")
        }
        actual_consent_requests = {
            (event.get("recordId"), event.get("deletedRevisionId"), int(event.get("deletedSeq")))
            for event in result.get("consentRequests", [])
            if event.get("status") == 200
            and event.get("enabled") is True
            and event.get("policyRevision") == "0"
        }
        _require(
            actual_consent_requests == expected_consent_requests,
            "the Web consent dialog must submit exact signed tombstone identity for both opted-in rows",
        )

        final_state = (
            database.execute(
                "SELECT last_committed_seq FROM vault_counters WHERE vault_id=%s", (vault_id,)
            ).fetchone()[0],
            database.execute(
                "SELECT COUNT(*) FROM record_redactions WHERE vault_id=%s AND record_id=ANY(%s::text[])",
                (vault_id, target_ids),
            ).fetchone()[0],
            database.execute(
                "SELECT COUNT(*) FROM audit_events WHERE scope_type='vault' AND scope_id=%s "
                "AND action='vault.record_purged' AND resource_id=ANY(%s::text[])",
                (vault_id, target_ids),
            ).fetchone()[0],
            database.execute(
                "SELECT COUNT(*) FROM change_events WHERE vault_id=%s AND record_id=%s "
                "AND event_type='record_redacted'",
                (vault_id, eligible["record_id"]),
            ).fetchone()[0],
        )
        _require(
            final_state == (7, 1, 1, 1),
            "a second Web-submitted Maintenance pass must not duplicate proof, audit, sequence, or feed marker",
        )
        _require(
            purge_ledger_snapshot() == first_ledger_snapshot,
            "the repeated Maintenance pass must leave the full proof, event, sequence, outbox, and graveyard ledger unchanged",
        )
        jobs = database.execute(
            "SELECT job_id,request_id,action,status,result_code FROM instance_admin_jobs "
            "WHERE job_id=ANY(%s::text[]) ORDER BY job_id",
            ([result["firstMaintenance"]["jobId"], result["secondMaintenance"]["jobId"]],),
        ).fetchall()
        _require(
            len(jobs) == 2
            and {row[0] for row in jobs}
            == {result["firstMaintenance"]["jobId"], result["secondMaintenance"]["jobId"]}
            and all(row[2:] == ("maintenance", "succeeded", "completed") for row in jobs)
            and len({row[1] for row in jobs}) == 2,
            "both distinct Settings Maintenance submissions must remain durable successful PG jobs",
        )
        final_scan = database.execute(
            "SELECT last_scan_status,last_scan_candidates,last_scan_purged,last_scan_not_due "
            "FROM record_auto_purge_scan_control WHERE singleton=1"
        ).fetchone()
        _require(
            final_scan == ("completed", 1, 0, 1),
            "the repeated pass must find only the future opted-in tombstone and purge nothing",
        )
        world.assert_secrets_not_in_local_files()
    except Exception:
        if process is not None and process.poll() is None:
            _stop_acceptance_process(process)
        raise
    finally:
        if process is not None and process.poll() is None:
            _stop_acceptance_process(process)
        if output_handle is not None:
            output_handle.flush()
            output_handle.close()


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_jobs"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_backup_jobs_are_shared_private_and_restore_sources_are_local(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin_tenant = pg_http_world.seed_tenant(tmp_path / "pg-admin-backup-admin")
    admin = admin_tenant.actors[0]
    pg_http_world.database_connection.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_JOBS_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-admin-backup-outsider").actors[0]

    schema_version = pg_http_world.database_connection.execute(
        "SELECT schema_version FROM atermius_instance_schema WHERE singleton=1"
    ).fetchone()[0]
    _require(schema_version == 38, "the PostgreSQL archive schema marker must match migration 0038")

    capabilities = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/jobs?limit=10&offset=0", token=admin.access_token
    )
    _require(capabilities.status == 200, "configured PostgreSQL backup capabilities must be readable")
    supported = capabilities.json().get("supported_actions")
    pg_dump = shutil.which("pg_dump")
    pg_restore = shutil.which("pg_restore")
    if pg_dump is None or pg_restore is None:
        _require(
            supported == [
                "maintenance",
                "backup_status",
                "backup_replication",
                "backup_schedule",
                "restore_stage_discard",
            ],
            "backup must stay unavailable when the configured PostgreSQL tools are missing",
        )
        return
    dump_version = subprocess.run([pg_dump, "--version"], capture_output=True, text=True, check=False)
    restore_version = subprocess.run([pg_restore, "--version"], capture_output=True, text=True, check=False)
    dump_match = re.search(r"\b([0-9]+)(?:\.[0-9]+)?\b", dump_version.stdout)
    restore_match = re.search(r"\b([0-9]+)(?:\.[0-9]+)?\b", restore_version.stdout)
    server_version = pg_http_world.database_connection.execute(
        "SELECT current_setting('server_version_num')::integer"
    ).fetchone()[0] // 10_000
    tools_ready = (
        dump_version.returncode == 0
        and restore_version.returncode == 0
        and dump_match is not None
        and restore_match is not None
        and int(dump_match.group(1)) >= server_version
        and int(restore_match.group(1)) >= int(dump_match.group(1))
    )
    if not tools_ready:
        _require(
            supported == [
                "maintenance",
                "backup_status",
                "backup_replication",
                "backup_schedule",
                "restore_stage_discard",
            ],
            "backup must stay unavailable when PostgreSQL tool versions are incompatible",
        )
        return
    target_restore_supported = (
        pg_http_world.restore_target_url is not None and "restore" in supported
    )
    expected_supported = [
        "maintenance",
        "backup_status",
        "backup_replication",
        "backup_schedule",
        "restore_stage_discard",
        "backup",
    ]
    if target_restore_supported:
        expected_supported.append("restore")
        expected_supported.append("restore_replica")
    _require(
        supported == expected_supported,
        "backup/restore readiness must be gated independently from durable stage discard",
    )
    replication_status = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/backup-replication", token=admin.access_token
    )
    replication_status_body = (
        replication_status.json() if replication_status.status == 200 else {}
    )
    _require(
        replication_status.status == 200
        and set(replication_status_body)
        == {"operation", "configured", "pending_count", "latest_attempt"}
        and replication_status_body.get("operation") == "backup_replication"
        and replication_status_body.get("configured") is True
        and replication_status_body.get("pending_count") == 0
        and replication_status_body.get("latest_attempt") is None,
        "the PostgreSQL replication route must read the empty shared outbox snapshot",
    )

    denied_sources = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/restore-sources", token=outsider.access_token
    )
    _require(
        denied_sources.status == 403
        and _error_code(denied_sources) == "INSTANCE_ADMIN_REQUIRED",
        "restore archive catalog must remain restricted to allowlisted admins",
    )

    request_id = str(uuid.uuid4())
    submitted = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={"request_id": request_id, "action": "backup"},
    )
    _require(
        submitted.status == 202,
        "a configured PostgreSQL administrator must be able to enqueue a server backup",
    )
    job = submitted.json().get("job", {})
    job_id = job.get("job_id")
    _require(
        isinstance(job_id, str)
        and job.get("action") == "backup"
        and job.get("archive_id") == job_id
        and job.get("archive_source") is None
        and job.get("status") in {"queued", "running", "succeeded", "failed", "interrupted"},
        "backup API must publish only its server-generated archive UUID and safe job state",
    )
    expected_job_keys = {
        "job_id",
        "request_id",
        "action",
        "archive_id",
        "archive_source",
        "status",
        "requested_at",
        "started_at",
        "finished_at",
        "result_code",
        "restore_stage_status",
    }
    _require(set(job) == expected_job_keys, "PostgreSQL backup DTO fields must stay explicitly bounded")
    serialized = json.dumps(submitted.json(), sort_keys=True)
    for private_value in pg_http_world.secrets:
        _require(not private_value or private_value not in serialized, "backup API leaked private configuration")

    replay = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={"request_id": request_id, "action": "backup"},
    )
    _require(
        replay.status == 202 and replay.json().get("job", {}).get("job_id") == job_id,
        "the second PostgreSQL node must return the same backup job for an idempotent retry",
    )

    deadline = time.monotonic() + 45
    terminal = None
    while time.monotonic() < deadline:
        page = pg_http_world.clients[1].request(
            "GET", "/api/v1/admin/jobs?limit=10&offset=0", token=admin.access_token
        )
        _require(page.status == 200, "the second PostgreSQL node must read backup progress")
        matches = [item for item in page.json().get("jobs", []) if item.get("job_id") == job_id]
        if matches and matches[0].get("status") in {"succeeded", "failed", "interrupted"}:
            terminal = matches[0]
            break
        time.sleep(0.1)
    _require(
        terminal is not None and terminal.get("status") == "succeeded",
        "the shared PG backup worker must publish a successful encrypted archive; "
        f"redacted logs: {pg_http_world.redacted_log_tail()}",
    )

    status_response = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/backup-status", token=admin.access_token
    )
    status_body = status_response.json() if status_response.status == 200 else {}
    last_attempt = status_body.get("last_attempt") if isinstance(status_body, dict) else None
    _require(
        status_response.status == 200
        and isinstance(last_attempt, dict)
        and last_attempt.get("result") == "succeeded"
        and last_attempt.get("migration_version") == 38
        and isinstance(last_attempt.get("archive_bytes"), int)
        and last_attempt["archive_bytes"] > 0
        and last_attempt.get("failure_category") is None,
        "a second PostgreSQL node must read the successful backup status from the shared job ledger",
    )

    row = pg_http_world.database_connection.execute(
        "SELECT archive_id,archive_timestamp,archive_sha256,status,result_code \
         FROM instance_admin_jobs WHERE job_id=%s",
        (job_id,),
    ).fetchone()
    _require(
        row is not None
        and row[0] == job_id
        and isinstance(row[1], str)
        and re.fullmatch(r"[0-9]{8}T[0-9]{6}\.[0-9]{3}Z", row[1]) is not None
        and isinstance(row[2], str)
        and re.fullmatch(r"[0-9a-f]{64}", row[2]) is not None
        and row[3:] == ("succeeded", "completed"),
        "backup identity, timestamp, and digest must be persisted privately before success",
    )
    replication_row = pg_http_world.database_connection.execute(
        "SELECT archive_id,origin,status,archive_bytes,archive_sha256,attempt_count, \
                next_attempt_at,last_attempt_at,failure_category,multipart_upload_id \
         FROM instance_backup_replications WHERE archive_id=%s",
        (job_id,),
    ).fetchone()
    _require(
        replication_row is not None
        and replication_row[0] == job_id
        and replication_row[1] == "manual"
        and replication_row[2] in {"pending", "running", "retry_wait"}
        and replication_row[3:5]
        == (status_body["last_attempt"]["archive_bytes"], row[2])
        and replication_row[5] >= 0
        and (
            (
                replication_row[2] == "pending"
                and replication_row[5] == 0
                and replication_row[6] is not None
                and replication_row[7:] == (None, None, None)
            )
            or (
                replication_row[2] == "running"
                and replication_row[5] > 0
                and replication_row[6] is None
                and replication_row[7] is not None
                and replication_row[8] is None
            )
            or (
                replication_row[2] == "retry_wait"
                and replication_row[5] > 0
                and replication_row[6] is not None
                and replication_row[7] is not None
                and replication_row[8] == "remote_unavailable"
            )
        ),
        "the PG producer must publish its exact encrypted archive to the shared outbox while a closed target stays pending, claimed, or retryable",
    )

    sources = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/restore-sources?limit=10&offset=0", token=admin.access_token
    )
    listed = sources.json() if sources.status == 200 else {}
    archive = next(
        (item for item in listed.get("sources", []) if item.get("archive_id") == job_id),
        None,
    )
    _require(
        sources.status == 200
        and archive is not None
        and archive.get("source") == "local"
        and archive.get("origin") == "manual"
        and isinstance(archive.get("created_at"), str)
        and isinstance(archive.get("archive_bytes"), int)
        and archive["archive_bytes"] > 0,
        "restore catalog must read the shared PG ledger and expose only local archive metadata",
    )
    _require(
        all(value not in json.dumps(listed, sort_keys=True) for value in pg_http_world.secrets if value),
        "restore archive catalog must not reveal configured paths, keys, or database URLs",
    )

    restore = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/jobs",
        token=admin.access_token,
        json_body={
            "request_id": str(uuid.uuid4()),
            "action": "restore",
            "archive_id": job_id,
            "archive_source": "local",
        },
    )
    expected_audit_actions = [
        "admin.backup_requested",
        "admin.backup_started",
        "admin.backup_completed",
    ]
    if not target_restore_supported:
        _require(
            restore.status == 503
            and _error_code(restore) == "PG_ADMIN_ACTION_UNSUPPORTED",
            "restore must remain unavailable until a separate isolated PG restore target is configured",
        )
    else:
        _require(
            restore.status == 202,
            "a ready isolated PostgreSQL target must accept a server-generated local restore source",
        )
        restore_job = restore.json().get("job", {})
        restore_job_id = restore_job.get("job_id")
        _require(
            isinstance(restore_job_id, str)
            and restore_job.get("action") == "restore"
            and restore_job.get("archive_id") == job_id
            and restore_job.get("archive_source") == "local",
            "restore job DTO must identify only its selected local archive and action",
        )
        restore_deadline = time.monotonic() + 90
        restore_terminal = None
        while time.monotonic() < restore_deadline:
            page = pg_http_world.clients[0].request(
                "GET", "/api/v1/admin/jobs?limit=20&offset=0", token=admin.access_token
            )
            _require(page.status == 200, "the online PG node must read isolated restore progress")
            matches = [
                item
                for item in page.json().get("jobs", [])
                if item.get("job_id") == restore_job_id
            ]
            if matches and matches[0].get("status") in {
                "succeeded",
                "failed",
                "interrupted",
            }:
                restore_terminal = matches[0]
                break
            time.sleep(0.1)
        _require(
            restore_terminal is not None
            and restore_terminal.get("status") == "succeeded"
            and restore_terminal.get("result_code") == "completed"
            and restore_terminal.get("restore_stage_status") == "ready",
            "the restore worker must publish a verified ready stage in the shared ledger",
        )
        restore_row = pg_http_world.database_connection.execute(
            "SELECT archive_id,archive_source,archive_sha256,status,result_code,"
            "restore_stage_status,restore_stage_generation "
            "FROM instance_admin_jobs WHERE job_id=%s",
            (restore_job_id,),
        ).fetchone()
        _require(
            restore_row is not None
            and restore_row[0] == job_id
            and restore_row[1] == "local"
            and restore_row[2] == row[2]
            and restore_row[3:6] == ("succeeded", "completed", "ready")
            and isinstance(restore_row[6], str)
            and restore_row[6] != pg_http_world.instance.get("generation"),
            "restore ledger must durably bind the source digest and a fresh staged generation",
        )

        restore_target = pg_http_world.psycopg.connect(
            pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
        )
        try:
            restore_target.execute(
                pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                    pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
                )
            )
            target_database = restore_target.execute("SELECT current_database()").fetchone()[0]
            target_generation = restore_target.execute(
                "SELECT generation FROM instance_meta WHERE id=1"
            ).fetchone()[0]
            active_target_sessions = restore_target.execute(
                "SELECT COUNT(*) FROM sessions WHERE revoked_at IS NULL"
            ).fetchone()[0]
        finally:
            restore_target.close()
        source_database = pg_http_world.database_connection.execute(
            "SELECT current_database()"
        ).fetchone()[0]
        source_generation = pg_http_world.database_connection.execute(
            "SELECT generation FROM instance_meta WHERE id=1"
        ).fetchone()[0]
        active_source_sessions = pg_http_world.database_connection.execute(
            "SELECT COUNT(*) FROM sessions WHERE user_id=%s AND revoked_at IS NULL",
            (admin.user_id,),
        ).fetchone()[0]
        online_source_me = pg_http_world.clients[1].request(
            "GET", "/api/v1/me", token=admin.access_token
        )
        _require(
            target_database != source_database
            and target_generation == restore_row[6]
            and target_generation != source_generation
            and active_target_sessions == 0
            and active_source_sessions > 0
            and online_source_me.status == 200,
            "isolated restore must rotate only the target generation and revoke restored sessions while the online source remains usable",
        )
        expected_audit_actions.extend(
            [
                "admin.restore_requested",
                "admin.restore_started",
                "admin.restore_completed",
            ]
        )

    audit = pg_http_world.database_connection.execute(
        "SELECT action,resource_id,result FROM audit_events \
         WHERE scope_type='instance' AND actor_user_id=%s AND resource_type='admin_job' \
         ORDER BY event_id",
        (admin.user_id,),
    ).fetchall()
    _require(
        [item[0] for item in audit] == expected_audit_actions
        and all(item[1] != job_id and item[2] == "success" for item in audit),
        "backup lifecycle audit must be atomic, attributable, and HMAC-only for its job resource",
    )

    expired_restore_job = str(uuid.uuid4())
    expired_restore_request = str(uuid.uuid4())
    pg_http_world.database_connection.execute(
        "INSERT INTO instance_admin_jobs( \
             job_id,request_id,requested_by_user_id,requested_by_device_id,action, \
             archive_id,archive_source,archive_sha256,status,started_at,worker_token,lease_expires_at \
         ) VALUES (%s,%s,%s,%s,'restore',%s,'local',%s,'running', \
                   clock_timestamp()-INTERVAL '10 minutes','expired-worker',clock_timestamp()-INTERVAL '1 second')",
        (expired_restore_job, expired_restore_request, admin.user_id, admin.device_id, job_id, row[2]),
    )
    deadline = time.monotonic() + 10
    interrupted = None
    while time.monotonic() < deadline:
        page = pg_http_world.clients[1].request(
            "GET", "/api/v1/admin/jobs?limit=10&offset=0", token=admin.access_token
        )
        _require(page.status == 200, "expired restore progress must be visible across PG nodes")
        matches = [
            item for item in page.json().get("jobs", []) if item.get("job_id") == expired_restore_job
        ]
        if matches and matches[0].get("status") in {"interrupted", "failed", "succeeded"}:
            interrupted = matches[0]
            break
        time.sleep(0.1)
    _require(
        interrupted is not None
        and interrupted.get("status") == "interrupted"
        and interrupted.get("result_code") == "interrupted"
        and interrupted.get("restore_stage_status") == "interrupted",
        "a restore whose worker lease expired must be interrupted instead of automatically replayed",
    )
    interrupted_audit = pg_http_world.database_connection.execute(
        "SELECT action,resource_id,result FROM audit_events \
         WHERE scope_type='instance' AND actor_user_id=%s AND resource_type='admin_job' \
           AND action='admin.restore_interrupted'",
        (admin.user_id,),
    ).fetchall()
    _require(
        len(interrupted_audit) == 1
        and interrupted_audit[0][1] != expired_restore_job
        and interrupted_audit[0][2] == "failure",
        "expired restore recovery must retain attributed HMAC-only interruption audit",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_restore_generation_cutover"],
    indirect=True,
    scope="module",
)
def test_pg_http_restore_generation_cutover_preserves_other_device_outbox(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    """A restored PG generation fences both nodes and replays a fixture-simulated signed outbox."""
    if pg_http_world.restore_target_url is None:
        pytest.skip("PG restore cutover acceptance requires a disposable restore database")
    if shutil.which("pg_dump") is None or shutil.which("pg_restore") is None:
        pytest.skip("PG restore cutover acceptance requires pg_dump and pg_restore")

    tenant = pg_http_world.seed_tenant(tmp_path / "pg-restore-cutover-device-keys")
    owner, other_device = tenant.actors
    pg_http_world.database_connection.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_JOBS_USERNAME, owner.user_id),
    )
    owner.username = PG_ADMIN_JOBS_USERNAME
    other_device.username = PG_ADMIN_JOBS_USERNAME
    _require(
        pg_http_world.database_connection.execute(
            "SELECT schema_version FROM atermius_instance_schema WHERE singleton=1"
        ).fetchone()[0]
        == 38,
        "restore cutover archive must use the current PostgreSQL schema",
    )

    initial = pg_http_world.make_envelope(tenant, owner)
    record_id = initial["header"]["record_id"]
    baseline_revision_id = initial["header"]["revision_id"]
    initial_push = _post_push(
        pg_http_world.clients[0], tenant, owner, [initial], batch_id=str(uuid.uuid4())
    )
    initial_result = (initial_push.json() or {}).get("results", [{}])[0]
    _require(
        initial_push.status == 200
        and initial_result.get("commit_seq") == "1"
        and initial_result.get("already_committed") is False,
        "the pre-archive baseline must be one committed record revision",
    )

    old_cursor_response = pg_http_world.clients[1].request(
        "GET",
        f"/api/v1/vaults/{tenant.vault_id}/changes?limit=10",
        token=other_device.access_token,
    )
    old_cursor_body = old_cursor_response.json()
    old_cursor = old_cursor_body.get("next_cursor") if isinstance(old_cursor_body, dict) else None
    _require(
        old_cursor_response.status == 200
        and isinstance(old_cursor, str)
        and bool(old_cursor)
        and [event.get("commit_seq") for event in old_cursor_body.get("events", [])]
        == ["1"],
        "the second device must persist a cursor through the baseline on node B",
    )
    old_snapshot_response = pg_http_world.clients[0].request(
        "POST",
        f"/api/v1/vaults/{tenant.vault_id}/snapshots",
        token=owner.access_token,
    )
    old_snapshot_body = old_snapshot_response.json()
    old_snapshot_id = (
        old_snapshot_body.get("snapshot_id")
        if isinstance(old_snapshot_body, dict)
        else None
    )
    old_snapshot_row = (
        pg_http_world.database_connection.execute(
            "SELECT server_generation,high_watermark FROM snapshots WHERE snapshot_id=%s",
            (old_snapshot_id,),
        ).fetchone()
        if isinstance(old_snapshot_id, str)
        else None
    )
    _require(
        old_snapshot_response.status == 200
        and isinstance(old_snapshot_id, str)
        and bool(old_snapshot_id)
        and old_snapshot_body.get("high_watermark") == "1"
        and isinstance(old_snapshot_body.get("next_cursor"), str)
        and bool(old_snapshot_body.get("next_cursor"))
        and old_snapshot_row == (tenant.generation, 1),
        "the source generation must issue a readable snapshot before the backup "
        f"(HTTP {old_snapshot_response.status}, code={_error_code(old_snapshot_response)})",
    )

    # Preserve a signed envelope as a fixture-simulated local outbox record.
    # This server-level case does not exercise the Web client's IndexedDB queue.
    # The private fixture file lets the test compare its exact bytes after cutover.
    pending_outbox = pg_http_world.make_envelope(
        tenant,
        other_device,
        operation="update",
        record_id=record_id,
        base_revision_id=baseline_revision_id,
    )
    pending_outbox_bytes = jcs(pending_outbox)
    pending_outbox_sha256 = hashlib.sha256(pending_outbox_bytes).hexdigest()
    pending_batch_id = str(uuid.uuid4())
    outbox_dir = tmp_path / "pg-restore-cutover-device-b"
    outbox_dir.mkdir(mode=0o700)
    outbox_path = outbox_dir / "pending-operation.json"
    _write_private(outbox_path, pending_outbox_bytes)

    capabilities = pg_http_world.clients[0].request(
        "GET", "/api/v1/admin/jobs?limit=10&offset=0", token=owner.access_token
    )
    supported = (capabilities.json() or {}).get("supported_actions")
    if capabilities.status != 200 or not isinstance(supported, list) or "restore" not in supported:
        pytest.skip("PG restore cutover acceptance requires compatible PG tools and target permissions")

    backup_response = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        token=owner.access_token,
        json_body={"request_id": str(uuid.uuid4()), "action": "backup"},
    )
    backup_job_id = (backup_response.json() or {}).get("job", {}).get("job_id")
    _require(
        backup_response.status == 202
        and isinstance(backup_job_id, str)
        and str(uuid.UUID(backup_job_id)) == backup_job_id,
        "an allowlisted administrator must enqueue the baseline PostgreSQL backup",
    )

    def wait_for_job(job_id: str, timeout_seconds: float) -> dict[str, Any]:
        deadline = time.monotonic() + timeout_seconds
        while time.monotonic() < deadline:
            page = pg_http_world.clients[1].request(
                "GET", "/api/v1/admin/jobs?limit=20&offset=0", token=owner.access_token
            )
            _require(page.status == 200, "the peer PostgreSQL node must read shared restore progress")
            jobs = (page.json() or {}).get("jobs", [])
            match = next((job for job in jobs if job.get("job_id") == job_id), None)
            if match and match.get("status") in {"succeeded", "failed", "interrupted"}:
                return match
            time.sleep(0.1)
        pytest.fail("PostgreSQL backup or restore job did not reach a terminal state", pytrace=False)

    backup_job = wait_for_job(backup_job_id, 90)
    _require(
        backup_job.get("status") == "succeeded"
        and backup_job.get("archive_id") == backup_job_id,
        "the server must publish a succeeded backup of the baseline state",
    )
    backup_row = pg_http_world.database_connection.execute(
        "SELECT archive_sha256,status,result_code FROM instance_admin_jobs WHERE job_id=%s",
        (backup_job_id,),
    ).fetchone()
    _require(
        backup_row is not None
        and isinstance(backup_row[0], str)
        and re.fullmatch(r"[0-9a-f]{64}", backup_row[0]) is not None
        and backup_row[1:] == ("succeeded", "completed"),
        "the baseline archive digest and successful result must be durable before the later commit",
    )

    later = pg_http_world.make_envelope(
        tenant,
        owner,
        operation="update",
        record_id=record_id,
        base_revision_id=baseline_revision_id,
    )
    later_push = _post_push(
        pg_http_world.clients[1], tenant, owner, [later], batch_id=str(uuid.uuid4())
    )
    later_result = (later_push.json() or {}).get("results", [{}])[0]
    _require(
        later_push.status == 200
        and later_result.get("commit_seq") == "2"
        and later_result.get("already_committed") is False,
        "a second-node commit must be newer than the backup being restored",
    )

    restore_response = pg_http_world.clients[1].request(
        "POST",
        "/api/v1/admin/jobs",
        token=owner.access_token,
        json_body={
            "request_id": str(uuid.uuid4()),
            "action": "restore",
            "archive_id": backup_job_id,
            "archive_source": "local",
        },
    )
    restore_job_id = (restore_response.json() or {}).get("job", {}).get("job_id")
    _require(
        restore_response.status == 202
        and isinstance(restore_job_id, str)
        and str(uuid.UUID(restore_job_id)) == restore_job_id,
        "the peer node must accept restore of the pre-commit archive into the isolated PG target",
    )
    restore_job = wait_for_job(restore_job_id, 180)
    _require(
        restore_job.get("status") == "succeeded"
        and restore_job.get("archive_id") == backup_job_id
        and restore_job.get("restore_stage_status") == "ready",
        "the pre-commit archive must produce a verified ready PostgreSQL restore stage",
    )
    restore_row = pg_http_world.database_connection.execute(
        "SELECT restore_stage_generation,status,result_code,restore_stage_status "
        "FROM instance_admin_jobs WHERE job_id=%s",
        (restore_job_id,),
    ).fetchone()
    old_generation = tenant.generation
    _require(
        restore_row is not None
        and isinstance(restore_row[0], str)
        and restore_row[0] != old_generation
        and restore_row[1:] == ("succeeded", "completed", "ready"),
        "the staged restored generation must be fresh while the source generation remains active",
    )

    target = pg_http_world.psycopg.connect(
        pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
    )
    try:
        target.execute(
            pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
            )
        )
        target_generation = target.execute(
            "SELECT generation FROM instance_meta WHERE id=1"
        ).fetchone()[0]
        target_baseline = target.execute(
            "SELECT c.last_committed_seq,h.revision_id,h.commit_seq "
            "FROM vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE c.vault_id=%s AND h.record_id=%s",
            (tenant.vault_id, record_id),
        ).fetchone()
        _require(
            target_generation == restore_row[0]
            and target_baseline == (1, baseline_revision_id, 1),
            "the restore stage must contain the old baseline and its fresh generation, without the later commit",
        )

        # Promote the isolated target as one cutover: stop both source workers
        # before either node starts against the restored shared database.
        for process in pg_http_world.processes:
            _stop_acceptance_process(process)
        for index in range(2):
            pg_http_world.restart_node(index, pg_url=pg_http_world.restore_target_url)

        instance_bodies = []
        for client in pg_http_world.clients:
            instance = client.request("GET", "/api/v1/instance")
            body = instance.json() if instance.status == 200 else {}
            instance_bodies.append(body)
        _require(
            all(body.get("generation") == target_generation for body in instance_bodies)
            and target.execute("SELECT generation FROM instance_meta WHERE id=1").fetchone()[0]
            == target_generation,
            "both restarted PostgreSQL nodes must serve the same fresh restored generation",
        )

        owner_login = _login(pg_http_world.clients[0], owner)
        other_login = _login(pg_http_world.clients[1], other_device)
        owner_access = (owner_login.json() or {}).get("access_token")
        other_access = (other_login.json() or {}).get("access_token")
        _require(
            owner_login.status == 200
            and other_login.status == 200
            and isinstance(owner_access, str)
            and isinstance(other_access, str),
            "both restored device profiles must reauthenticate after restore revoked archived sessions",
        )
        owner.access_token = owner_access
        other_device.access_token = other_access
        pg_http_world.remember_secret(owner_access)
        pg_http_world.remember_secret(other_access)

        old_cursor_response = pg_http_world.clients[0].request(
            "GET",
            f"/api/v1/vaults/{tenant.vault_id}/changes?"
            + urllib.parse.urlencode({"cursor": old_cursor, "limit": "10"}),
            token=other_access,
        )
        old_snapshot_read = pg_http_world.clients[1].request(
            "GET",
            f"/api/v1/snapshots/{old_snapshot_id}",
            token=owner_access,
        )
        _require(
            old_cursor_response.status == 410
            and _error_code(old_cursor_response) == "CURSOR_EXPIRED"
            and old_snapshot_read.status == 404
            and _error_code(old_snapshot_read) == "NOT_FOUND",
            "the restored cluster must reject the old-generation cursor and the snapshot removed by restore",
        )

        old_generation_push = pg_http_world.clients[0].request(
            "POST",
            f"/api/v1/vaults/{tenant.vault_id}/sync/push",
            token=other_access,
            json_body=pg_http_world.push_body(
                tenant, other_device, [pending_outbox], batch_id=pending_batch_id
            ),
        )
        _require(
            old_generation_push.status == 410
            and _error_code(old_generation_push) == "SERVER_GENERATION_CHANGED"
            and outbox_path.read_bytes() == pending_outbox_bytes
            and hashlib.sha256(jcs(pending_outbox)).hexdigest() == pending_outbox_sha256,
            "a stale-generation push must be rejected without mutating the exact pending device envelope",
        )

        after_rejected_push = target.execute(
            "SELECT c.last_committed_seq,h.revision_id,h.commit_seq, "
            "(SELECT count(*) FROM op_receipts r WHERE r.vault_id=c.vault_id AND r.op_id=%s), "
            "(SELECT count(*) FROM record_versions v WHERE v.vault_id=c.vault_id AND v.revision_id=%s), "
            "(SELECT count(*) FROM change_events e WHERE e.vault_id=c.vault_id) "
            "FROM vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE c.vault_id=%s AND h.record_id=%s",
            (
                pending_outbox["header"]["op_id"],
                pending_outbox["header"]["revision_id"],
                tenant.vault_id,
                record_id,
            ),
        ).fetchone()
        _require(
            after_rejected_push == (1, baseline_revision_id, 1, 0, 0, 1),
            "a rejected stale-generation push must leave the restored commit ledger unchanged",
        )

        recovery_snapshot_response = pg_http_world.clients[1].request(
            "POST",
            f"/api/v1/vaults/{tenant.vault_id}/snapshots",
            token=other_access,
        )
        recovery_snapshot = recovery_snapshot_response.json()
        recovery_snapshot_id = (
            recovery_snapshot.get("snapshot_id")
            if isinstance(recovery_snapshot, dict)
            else None
        )
        recovery_snapshot_row = (
            target.execute(
                "SELECT server_generation,high_watermark FROM snapshots WHERE snapshot_id=%s",
                (recovery_snapshot_id,),
            ).fetchone()
            if isinstance(recovery_snapshot_id, str)
            else None
        )
        recovery_page_response = pg_http_world.clients[0].request(
            "GET",
            f"/api/v1/snapshots/{recovery_snapshot_id}?limit=10",
            token=other_access,
        )
        recovery_page = recovery_page_response.json()
        recovery_manifest = (
            recovery_page.get("manifest") if isinstance(recovery_page, dict) else None
        )
        _require(
            recovery_snapshot_response.status == 200
            and isinstance(recovery_snapshot_id, str)
            and recovery_snapshot.get("high_watermark") == "1"
            and isinstance(recovery_snapshot.get("next_cursor"), str)
            and recovery_snapshot_row == (target_generation, 1)
            and recovery_page_response.status == 200
            and recovery_page.get("server_generation") == target_generation
            and isinstance(recovery_manifest, list)
            and len(recovery_manifest) == 1
            and recovery_manifest[0].get("record_id") == record_id
            and recovery_manifest[0].get("revision_id") == baseline_revision_id,
            "the other device must verify a fresh-generation snapshot of the restored baseline before replay",
        )

        tenant.generation = target_generation
        before_replay = target.execute(
            "SELECT c.last_committed_seq,h.revision_id, "
            "(SELECT count(*) FROM op_receipts r WHERE r.vault_id=c.vault_id AND r.op_id=%s), "
            "(SELECT count(*) FROM change_events e WHERE e.vault_id=c.vault_id) "
            "FROM vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE c.vault_id=%s AND h.record_id=%s",
            (pending_outbox["header"]["op_id"], tenant.vault_id, record_id),
        ).fetchone()
        _require(
            before_replay == (1, baseline_revision_id, 0, 1),
            "the target must still contain only the pre-archive baseline before outbox replay",
        )

        _require(
            outbox_path.read_bytes() == pending_outbox_bytes
            and hashlib.sha256(outbox_path.read_bytes()).hexdigest() == pending_outbox_sha256,
            "the second device's pending envelope bytes changed during restore recovery",
        )
        recovered_outbox = json.loads(outbox_path.read_bytes())
        replay = _post_push(
            pg_http_world.clients[1],
            tenant,
            other_device,
            [recovered_outbox],
            batch_id=pending_batch_id,
        )
        replay_result = (replay.json() or {}).get("results", [{}])[0]
        _require(
            replay.status == 200
            and replay_result.get("op_id") == recovered_outbox["header"]["op_id"]
            and replay_result.get("revision_id") == recovered_outbox["header"]["revision_id"]
            and replay_result.get("commit_seq") == "2"
            and replay_result.get("already_committed") is False,
            "the unchanged device outbox must commit once against the restored baseline",
        )
        retry = _post_push(
            pg_http_world.clients[0],
            tenant,
            other_device,
            [recovered_outbox],
            batch_id=pending_batch_id,
        )
        retry_result = (retry.json() or {}).get("results", [{}])[0]
        recovered_changes = pg_http_world.clients[0].request(
            "GET",
            f"/api/v1/vaults/{tenant.vault_id}/changes?"
            + urllib.parse.urlencode(
                {"cursor": recovery_snapshot["next_cursor"], "limit": "10"}
            ),
            token=other_access,
        )
        recovered_events = (recovered_changes.json() or {}).get("events", [])
        final_rows = target.execute(
            "SELECT c.last_committed_seq,h.revision_id,h.commit_seq, "
            "(SELECT count(*) FROM op_receipts r WHERE r.vault_id=c.vault_id AND r.op_id=%s), "
            "(SELECT count(*) FROM record_versions v WHERE v.vault_id=c.vault_id AND v.revision_id=%s), "
            "(SELECT count(*) FROM change_events e WHERE e.vault_id=c.vault_id), "
            "(SELECT count(*) FROM record_heads h2 WHERE h2.vault_id=c.vault_id AND h2.record_id=%s) "
            "FROM vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE c.vault_id=%s AND h.record_id=%s",
            (
                recovered_outbox["header"]["op_id"],
                recovered_outbox["header"]["revision_id"],
                record_id,
                tenant.vault_id,
                record_id,
            ),
        ).fetchone()
        _require(
            retry.status == 200
            and retry_result.get("already_committed") is True
            and retry_result.get("commit_seq") == "2"
            and recovered_changes.status == 200
            and len(recovered_events) == 1
            and recovered_events[0].get("commit_seq") == "2"
            and recovered_events[0].get("revision_id") == recovered_outbox["header"]["revision_id"]
            and final_rows
            == (2, recovered_outbox["header"]["revision_id"], 2, 1, 1, 2, 1)
            and hashlib.sha256(outbox_path.read_bytes()).hexdigest() == pending_outbox_sha256,
            "cross-node retry must converge on one receipt, version, head, and change event",
        )
    finally:
        target.close()


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_restore_generation_web_cutover"],
    indirect=True,
    scope="module",
)
def test_pg_http_web_restore_generation_cutover_preserves_indexeddb_outbox(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    """A real Chromium IndexedDB outbox survives offline PG restore and replays once."""
    if pg_http_world.restore_target_url is None:
        pytest.skip("PG Web restore cutover acceptance requires a disposable restore database")
    if shutil.which("pg_dump") is None or shutil.which("pg_restore") is None:
        pytest.skip("PG Web restore cutover acceptance requires pg_dump and pg_restore")
    if not (ROOT / "apps" / "client" / "build" / "web" / "index.html").is_file():
        pytest.skip("PG Web restore cutover acceptance requires a built Flutter Web bundle")

    run_id = uuid.uuid4().hex
    username = PG_WEB_RESTORE_GENERATION_USERNAME
    password = f"PgWebRestore-{run_id}-Secure9!"
    host_name = f"PG restore pending host {run_id[:8]}"
    host_address = f"198.51.100.{int(run_id[:2], 16) % 254 + 1}"
    ssh_username = f"pg-restore-{run_id[:12]}"
    bootstrap_token = pg_http_world.bootstrap_token()
    for secret in (username, password, host_name, host_address, ssh_username, bootstrap_token):
        pg_http_world.remember_secret(secret)

    control_dir = tmp_path / f"pg-web-restore-cutover-{run_id}"
    control_dir.mkdir(mode=0o700)
    if os.name == "posix":
        os.chmod(control_dir, 0o700)
    browser_work_root = control_dir / "browser-work"
    browser_work_root.mkdir(mode=0o700)
    if os.name == "posix":
        os.chmod(browser_work_root, 0o700)
    ready_path = control_dir / "browser-ready.json"
    continue_path = control_dir / "continue.json"
    runner_env = {
        key: os.environ[key]
        for key in (
            "PATH",
            "HOME",
            "TMPDIR",
            "TMP",
            "TEMP",
            "XDG_CACHE_HOME",
            "CI",
            "PLAYWRIGHT_BROWSERS_PATH",
            "PLAYWRIGHT_CHROMIUM_EXECUTABLE",
        )
        if key in os.environ
    }
    runner_env.update(
        {
            "ATERMIUS_PG_RESTORE_RECOVERY_BASE_URL": pg_http_world.runtime_env[
                "ATERMIUS_PUBLIC_ORIGIN"
            ],
            "ATERMIUS_PG_RESTORE_RECOVERY_NODE_A_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_RESTORE_RECOVERY_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_RESTORE_RECOVERY_USERNAME": username,
            "ATERMIUS_PG_RESTORE_RECOVERY_PASSWORD": password,
            "ATERMIUS_PG_RESTORE_RECOVERY_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_RESTORE_RECOVERY_HOST_NAME": host_name,
            "ATERMIUS_PG_RESTORE_RECOVERY_HOST_ADDRESS": host_address,
            "ATERMIUS_PG_RESTORE_RECOVERY_SSH_USERNAME": ssh_username,
            "ATERMIUS_PG_RESTORE_RECOVERY_READY_FILE": str(ready_path),
            "ATERMIUS_PG_RESTORE_RECOVERY_CONTINUE_FILE": str(continue_path),
            "ATERMIUS_PG_RESTORE_RECOVERY_WORK_ROOT": str(browser_work_root),
        }
    )

    process: subprocess.Popen[str] | None = None
    runner_output = ""
    target = None
    ready: dict[str, Any] | None = None
    browser_work_clean = True
    target_close_clean = True
    try:
        process = subprocess.Popen(
            ["node", str(ROOT / "integration" / "web" / "pg_restore_generation_recovery.cjs")],
            cwd=ROOT,
            env=runner_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            start_new_session=(os.name == "posix"),
        )
        ready_deadline = time.monotonic() + 300
        while time.monotonic() < ready_deadline:
            if ready_path.is_file():
                break
            if process.poll() is not None:
                runner_output, _ = process.communicate(timeout=5)
                break
            time.sleep(0.1)
        _require(
            ready_path.is_file(),
            "PG restore-generation Chromium runner did not reach its staged-restore barrier; "
            + redact_secrets(runner_output, *pg_http_world.secrets)[-5000:],
        )
        try:
            loaded = json.loads(ready_path.read_text(encoding="utf-8"))
            ready = loaded if isinstance(loaded, dict) else None
        except (OSError, json.JSONDecodeError):
            pytest.fail("PG restore-generation runner wrote invalid barrier evidence", pytrace=False)
        assert ready is not None

        canonical_id = re.compile(
            r"[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}",
            re.IGNORECASE,
        )
        for key in (
            "vaultId",
            "recordId",
            "baselineRevisionId",
            "laterRevisionId",
            "backupJobId",
            "restoreJobId",
            "oldSnapshotId",
            "branchOpId",
            "branchRevisionId",
            "branchBaseRevisionId",
        ):
            _require(
                isinstance(ready.get(key), str) and canonical_id.fullmatch(ready[key]) is not None,
                f"PG restore-generation runner omitted valid {key} barrier evidence",
            )
        _require(
            ready.get("profileRestarted") is True
            and ready.get("baselineCommitSeq") == "1"
            and ready.get("laterCommitSeq") == "2"
            and ready.get("branchBaseRevisionId") == ready.get("baselineRevisionId")
            and isinstance(ready.get("branchEnvelopeSha256"), str)
            and re.fullmatch(r"[0-9a-f]{64}", ready["branchEnvelopeSha256"]) is not None,
            "PG restore-generation runner's pre-cutover Chromium evidence was incomplete",
        )

        database = pg_http_world.database_connection
        old_generation = database.execute(
            "SELECT generation FROM instance_meta WHERE id=1"
        ).fetchone()[0]
        jobs = database.execute(
            "SELECT job_id,action,archive_id,status,result_code,restore_stage_status,"
            "restore_stage_generation FROM instance_admin_jobs WHERE job_id=ANY(%s)",
            ([ready["backupJobId"], ready["restoreJobId"]],),
        ).fetchall()
        backup_job = next((row for row in jobs if row[1] == "backup"), None)
        restore_job = next((row for row in jobs if row[1] == "restore"), None)
        _require(
            backup_job is not None
            and backup_job[0] == ready["backupJobId"]
            and backup_job[2] == ready["backupJobId"]
            and backup_job[3:5] == ("succeeded", "completed")
            and restore_job is not None
            and restore_job[0] == ready["restoreJobId"]
            and restore_job[2] == ready["backupJobId"]
            and restore_job[3:6] == ("succeeded", "completed", "ready")
            and isinstance(restore_job[6], str)
            and restore_job[6] != old_generation
            and ready.get("oldGeneration") == old_generation
            and ready.get("oldSnapshotGeneration") == old_generation,
            "PG source database did not retain successful backup and fresh-generation restore-stage evidence",
        )
        target_generation = restore_job[6]
        target = pg_http_world.psycopg.connect(
            pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
        )
        target.execute(
            pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
            )
        )
        target_state = target.execute(
            "SELECT m.generation,c.last_committed_seq,h.revision_id,h.commit_seq,"
            "(SELECT count(*) FROM record_versions v WHERE v.vault_id=h.vault_id AND v.record_id=h.record_id) "
            "FROM instance_meta m CROSS JOIN vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE m.id=1 AND c.vault_id=%s AND h.record_id=%s",
            (ready["vaultId"], ready["recordId"]),
        ).fetchone()
        restored_old_snapshot = target.execute(
            "SELECT server_generation FROM snapshots WHERE snapshot_id=%s",
            (ready["oldSnapshotId"],),
        ).fetchone()
        source_state = database.execute(
            "SELECT c.last_committed_seq,h.revision_id,h.commit_seq,"
            "(SELECT count(*) FROM record_versions v WHERE v.vault_id=h.vault_id AND v.record_id=h.record_id) "
            "FROM vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE c.vault_id=%s AND h.record_id=%s",
            (ready["vaultId"], ready["recordId"]),
        ).fetchone()
        _require(
            target_state == (target_generation, 1, ready["baselineRevisionId"], 1, 1)
            and restored_old_snapshot is None
            and source_state
            == (2, ready["laterRevisionId"], 2, 2),
            "the isolated target must contain only the archived baseline while source retains the later commit",
        )
        target.close()
        target = None

        # This is the documented offline cutover: stop both writers, then
        # start each node against the same staged database before the browser reconnects.
        for acceptance_process in pg_http_world.processes:
            _stop_acceptance_process(acceptance_process)
        for index in range(2):
            pg_http_world.restart_node(index, pg_url=pg_http_world.restore_target_url)
        instance_bodies = []
        for client in pg_http_world.clients:
            response = client.request("GET", "/api/v1/instance")
            instance_bodies.append(response.json() if response.status == 200 else {})
        _require(
            all(body.get("generation") == target_generation for body in instance_bodies),
            "both PG nodes must serve the fresh restored generation before ingress resumes",
        )
        continue_path.write_text(
            json.dumps(
                {
                    "nodeAUrl": pg_http_world.clients[0].base_url,
                    "nodeBUrl": pg_http_world.clients[1].base_url,
                    "generation": target_generation,
                },
                sort_keys=True,
                separators=(",", ":"),
            )
            + "\n",
            encoding="utf-8",
        )
        if os.name == "posix":
            os.chmod(continue_path, 0o600)

        try:
            runner_output, _ = process.communicate(timeout=360)
        except subprocess.TimeoutExpired:
            if process.poll() is None:
                if os.name == "posix":
                    try:
                        os.killpg(process.pid, signal.SIGTERM)
                    except ProcessLookupError:
                        pass
                else:
                    process.terminate()
                try:
                    runner_output, _ = process.communicate(timeout=5)
                except subprocess.TimeoutExpired:
                    if os.name == "posix":
                        try:
                            os.killpg(process.pid, signal.SIGKILL)
                        except ProcessLookupError:
                            pass
                    else:
                        process.kill()
                    runner_output, _ = process.communicate()
            pytest.fail("PG restore-generation Chromium runner timed out and was stopped", pytrace=False)
    except OSError:
        pytest.fail("PG restore-generation Chromium runner could not start", pytrace=False)
    finally:
        if process is not None and process.poll() is None:
            if not continue_path.exists():
                try:
                    continue_path.write_text(
                        json.dumps({"continue": False}), encoding="utf-8"
                    )
                    if os.name == "posix":
                        os.chmod(continue_path, 0o600)
                except OSError:
                    pass
            if os.name == "posix":
                try:
                    os.killpg(process.pid, signal.SIGTERM)
                except ProcessLookupError:
                    pass
            else:
                process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                if os.name == "posix":
                    try:
                        os.killpg(process.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                else:
                    process.kill()
                process.wait(timeout=10)
        if target is not None:
            try:
                target.close()
            except Exception:
                target_close_clean = False
        if browser_work_root.exists():
            try:
                shutil.rmtree(browser_work_root)
            except OSError:
                browser_work_clean = False

    _require(
        browser_work_clean and target_close_clean and not browser_work_root.exists(),
        "PG restore-generation Chromium work root was not removed after runner exit",
    )

    redacted_output = redact_secrets(runner_output, *pg_http_world.secrets)[-9000:]
    _require(
        process is not None and process.returncode == 0,
        "PG restore-generation Chromium acceptance failed; redacted output: " + redacted_output,
    )
    result_match = re.search(
        r"^PG-RESTORE-GENERATION-RECOVERY-RESULT (\{[^\n]+\})$",
        runner_output,
        re.MULTILINE,
    )
    if not result_match:
        pytest.fail(
            "PG restore-generation runner omitted its safe result summary; redacted output: "
            + redacted_output,
            pytrace=False,
        )
    try:
        browser_result = json.loads(result_match.group(1))
    except json.JSONDecodeError:
        pytest.fail("PG restore-generation runner returned invalid safe JSON", pytrace=False)

    expected = {
        "passed": True,
        "nodeAAndBShareRestoredGeneration": True,
        "generationChanged": True,
        "staleCursorRejected": True,
        "staleSnapshotRejected": True,
        "staleSnapshotCreatedBeforeCutover": True,
        "staleGenerationRejected": True,
        "staleGenerationGateVisible": True,
        "noPreSnapshotPush": True,
        "outboxIdenticalAcrossRestartAndRejection": True,
        "snapshotVerified": True,
        "snapshotAppliedBeforeReplay": True,
        "pendingOutboxCleared": True,
        "pushAfterSnapshotVerified": True,
        "pendingReplayCountExactlyOne": True,
        "idempotentCrossNodeRetryPassed": True,
        "readyBarrierUsed": True,
        "profileRestarted": True,
        "baselineCommitSeq": "1",
        "laterCommitSeq": "2",
        "archivedHeadSeq": "1",
        "replayCommitSeq": "2",
        "expectedReplaySeq": "2",
        "replayStatus": 200,
        "replayReceiptStatus": 200,
        "browserPageErrors": {"A": 0, "B": 0},
        "browserApiFailures": {"A": 0, "B": 0},
        "cleanupPassed": True,
    }
    _require(
        all(browser_result.get(key) == value for key, value in expected.items())
        and browser_result.get("vaultId") == ready["vaultId"]
        and browser_result.get("recordId") == ready["recordId"]
        and browser_result.get("pendingOperationId") == ready["branchOpId"]
        and browser_result.get("pendingEnvelopeSha256") == ready["branchEnvelopeSha256"]
        and browser_result.get("restoreStageGeneration") == target_generation
        and browser_result.get("replayOperationId") == ready["branchOpId"]
        and browser_result.get("replayReceiptCommitSeq") == "2"
        and browser_result.get("backupJobId") == ready["backupJobId"]
        and browser_result.get("restoreJobId") == ready["restoreJobId"],
        "Chromium generation-recovery evidence did not match the pending IndexedDB operation; "
        + redacted_output,
    )
    expected_offline_api = browser_result.get("expectedOfflineApiFailures")
    _require(
        isinstance(expected_offline_api, dict)
        and all(
            isinstance(expected_offline_api.get(profile), int)
            and expected_offline_api[profile] >= 0
            for profile in ("A", "B")
        )
        and expected_offline_api["A"] <= 16
        and expected_offline_api["B"] == 0
        and isinstance(browser_result.get("expectedOfflinePushAborts"), int)
        and browser_result["expectedOfflinePushAborts"] >= 1,
        "Chromium runner omitted safe expected-offline failure counts",
    )

    ledger_connection = pg_http_world.psycopg.connect(
        pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
    )
    try:
        ledger_connection.execute(
            pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
            )
        )
        ledger = ledger_connection.execute(
            "SELECT c.last_committed_seq,h.revision_id,h.commit_seq,"
            "(SELECT count(*) FROM op_receipts r WHERE r.vault_id=c.vault_id AND r.op_id=%s),"
            "(SELECT count(*) FROM record_versions v WHERE v.vault_id=c.vault_id AND v.revision_id=%s),"
            "(SELECT count(*) FROM change_events e WHERE e.vault_id=c.vault_id),"
            "(SELECT count(*) FROM record_heads h2 WHERE h2.vault_id=c.vault_id AND h2.record_id=%s) "
            "FROM vault_counters c JOIN record_heads h USING(vault_id) "
            "WHERE c.vault_id=%s AND h.record_id=%s",
            (
                ready["branchOpId"],
                ready["branchRevisionId"],
                ready["recordId"],
                ready["vaultId"],
                ready["recordId"],
            ),
        ).fetchone()
    finally:
        ledger_connection.close()
    _require(
        ledger
        == (2, ready["branchRevisionId"], 2, 1, 1, 2, 1),
        "the Chromium pending operation must produce exactly one PG receipt, revision, head, and event",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_replication_preflight"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_backup_replication_preflight_is_shared_and_redacted(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin = pg_http_world.seed_tenant(tmp_path / "pg-preflight-admin").actors[0]
    pg_http_world.database_connection.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_WEB_BACKUP_PREFLIGHT_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-preflight-outsider").actors[0]
    route = "/api/v1/admin/backup-replication/preflight"
    success_body = {"check": "bucket_access", "result": "passed"}

    response_a = pg_http_world.clients[0].request(
        "POST", route, token=admin.access_token, json_body={}
    )
    response_b = pg_http_world.clients[1].request(
        "POST", route, token=admin.access_token, json_body={}
    )
    _require(
        response_a.status == response_b.status == 200
        and response_a.json() == response_b.json() == success_body,
        "both PostgreSQL nodes must return the exact configured bucket-access success DTO",
    )
    _require(
        pg_http_world.backup_replica_fixture_control_token is not None
        and pg_http_world.backup_replica_endpoint_url is not None,
        "configured preflight fixture must expose its private loopback control",
    )
    fixture_control = HttpClient(pg_http_world.backup_replica_endpoint_url)
    stats_headers = {
        "x-fixture-control-token": pg_http_world.backup_replica_fixture_control_token
    }
    stats_after_success = fixture_control.request(
        "GET", "/__fixture/stats", additional_headers=stats_headers
    )
    _require(
        stats_after_success.status == 200
        and (stats_after_success.json() or {}).get("bucketHeadCount") == 2,
        "each successful node preflight must issue one authenticated bucket-level HEAD",
    )

    denied = pg_http_world.clients[1].request(
        "POST", route, token=outsider.access_token, json_body={}
    )
    _require(
        denied.status == 403 and _error_code(denied) == "INSTANCE_ADMIN_REQUIRED",
        "a non-admin must not start the configured backup bucket preflight",
    )
    anonymous = pg_http_world.clients[0].request(
        "POST", route, json_body={}
    )
    _require(
        anonymous.status == 401 and _error_code(anonymous) == "AUTH_REQUIRED",
        "an unauthenticated caller must not start the configured backup bucket preflight",
    )

    caller_target = {
        "endpoint_url": "https://caller-target.invalid",
        "bucket": "caller-target-bucket",
        "access_key_id": "caller-target-access-key",
        "secret_access_key": "caller-target-secret-value",
    }
    invalid_target = pg_http_world.clients[0].request(
        "POST", route, token=admin.access_token, json_body=caller_target
    )
    _require(
        invalid_target.status == 400
        and _error_code(invalid_target) == "INVALID_BACKUP_REPLICATION_PREFLIGHT_REQUEST",
        "preflight must reject caller-supplied endpoint, bucket, and credentials",
    )
    stats_after_denials = fixture_control.request(
        "GET", "/__fixture/stats", additional_headers=stats_headers
    )
    _require(
        stats_after_denials.status == 200
        and (stats_after_denials.json() or {}).get("bucketHeadCount") == 2,
        "anonymous, non-admin, and caller-target requests must not reach the configured bucket",
    )

    fixture_process = pg_http_world.backup_replica_fixture_process
    _require(fixture_process is not None, "configured preflight fixture must expose its loopback S3 process")
    _stop_acceptance_process(fixture_process)
    provider_failure = pg_http_world.clients[1].request(
        "POST", route, token=admin.access_token, json_body={}
    )
    provider_error = provider_failure.json()
    provider_error_body = provider_error.get("error") if isinstance(provider_error, dict) else None
    _require(
        provider_failure.status == 502
        and isinstance(provider_error_body, dict)
        and set(provider_error_body) == {"code", "message", "request_id"}
        and provider_error_body.get("code") == "BACKUP_REPLICATION_CHECK_FAILED"
        and provider_error_body.get("message")
        == "configured backup bucket access could not be verified",
        "an unavailable configured provider must return only its fixed generic failure",
    )

    responses = (
        response_a,
        response_b,
        denied,
        anonymous,
        invalid_target,
        provider_failure,
    )
    private_markers = [
        pg_http_world.backup_replica_endpoint_url or "",
        PG_REPLICA_BUCKET,
        PG_REPLICA_ACCESS_KEY_ID,
        PG_REPLICA_SECRET_ACCESS_KEY,
        "https://caller-target.invalid",
        "caller-target-bucket",
        "caller-target-access-key",
        "caller-target-secret-value",
        "connection refused",
        "dispatch failure",
        "signaturedoesnotmatch",
        "accessdenied",
    ]
    for response in responses:
        rendered = response.body.decode("utf-8", errors="replace").lower()
        _require(
            all(marker.lower() not in rendered for marker in private_markers if marker),
            "preflight response exposed configured S3 details or raw provider diagnostics",
        )
    logs = "\n".join(
        path.read_text(encoding="utf-8", errors="replace")
        for path in pg_http_world.log_paths
        if path.exists()
    ).lower()
    _require(
        all(marker.lower() not in logs for marker in private_markers if marker),
        "preflight server logs exposed configured S3 details or raw provider diagnostics",
    )
    pg_http_world.assert_secrets_not_in_local_files()


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_replication_preflight_unconfigured"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_backup_replication_preflight_fails_closed_when_unconfigured(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    admin = pg_http_world.seed_tenant(tmp_path / "pg-preflight-unconfigured-admin").actors[0]
    pg_http_world.database_connection.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_WEB_BACKUP_PREFLIGHT_USERNAME, admin.user_id),
    )
    route = "/api/v1/admin/backup-replication/preflight"
    for client in pg_http_world.clients:
        response = client.request("POST", route, token=admin.access_token, json_body={})
        error = response.json()
        error_body = error.get("error") if isinstance(error, dict) else None
        _require(
            response.status == 503
            and isinstance(error_body, dict)
            and set(error_body) == {"code", "message", "request_id"}
            and error_body.get("code") == "BACKUP_REPLICATION_NOT_CONFIGURED"
            and error_body.get("message")
            == "encrypted backup replication is not configured",
            "both PostgreSQL nodes must return the fixed generic unconfigured response",
        )
        rendered = response.body.decode("utf-8", errors="replace").lower()
        _require(
            "endpoint_url" not in rendered
            and "bucket" not in rendered
            and "credentials" not in rendered,
            "unconfigured response must not disclose provider settings",
        )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_replication_web"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_backup_replication_settings_browser_acceptance(
    pg_http_world: PgHttpWorld,
) -> None:
    """Verify one real PG archive reaches loopback S3 and shared Web status."""
    pg_dump = shutil.which("pg_dump")
    pg_restore = shutil.which("pg_restore")
    if pg_dump is None or pg_restore is None:
        pytest.skip("PG backup replication acceptance requires pg_dump and pg_restore")
    dump_version = subprocess.run(
        [pg_dump, "--version"], capture_output=True, text=True, check=False
    )
    restore_version = subprocess.run(
        [pg_restore, "--version"], capture_output=True, text=True, check=False
    )
    dump_match = re.search(r"\b([0-9]+)(?:\.[0-9]+)?\b", dump_version.stdout)
    restore_match = re.search(r"\b([0-9]+)(?:\.[0-9]+)?\b", restore_version.stdout)
    server_version = pg_http_world.database_connection.execute(
        "SELECT current_setting('server_version_num')::integer"
    ).fetchone()[0] // 10_000
    if not (
        dump_version.returncode == 0
        and restore_version.returncode == 0
        and dump_match is not None
        and restore_match is not None
        and int(dump_match.group(1)) >= server_version
        and int(restore_match.group(1)) >= int(dump_match.group(1))
    ):
        pytest.skip("PG backup replication acceptance requires version-compatible PostgreSQL tools")

    bootstrap_token = pg_http_world.bootstrap_token()
    password = f"PgBackupReplication-{uuid.uuid4().hex}"
    for value in (bootstrap_token, password, PG_WEB_BACKUP_REPLICATION_USERNAME):
        pg_http_world.remember_secret(value)

    # Give npm/Node only browser/runtime settings and explicit account/node
    # inputs. The PG URL, S3 credentials, archive key, and key-file paths stay
    # in the pytest/fixture processes and cannot be inherited by Chromium.
    runner_env = {
        key: os.environ[key]
        for key in (
            "PATH",
            "HOME",
            "TMPDIR",
            "TMP",
            "TEMP",
            "XDG_CACHE_HOME",
            "CI",
            "PLAYWRIGHT_BROWSERS_PATH",
            "PLAYWRIGHT_CHROMIUM_EXECUTABLE",
        )
        if key in os.environ
    }
    runner_env.update(
        {
            "ATERMIUS_PG_BACKUP_REPLICATION_NODE_A_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_BACKUP_REPLICATION_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_BACKUP_REPLICATION_USERNAME": PG_WEB_BACKUP_REPLICATION_USERNAME,
            "ATERMIUS_PG_BACKUP_REPLICATION_PASSWORD": password,
            "ATERMIUS_PG_BACKUP_REPLICATION_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_HTTP_SERVER_BIN": str(pg_http_world.binary),
        }
    )
    _require(
        not any(
            key.startswith("ATERMIUS_BACKUP_")
            or key in {"ATERMIUS_SYNC_PG_URL", "ATERMIUS_DATABASE_URL"}
            for key in runner_env
        ),
        "PG or S3 configuration must not be passed to the browser runner",
    )
    try:
        result = subprocess.run(
            [
                "npm",
                "run",
                "test:pg-backup-replication",
                "--prefix",
                str(ROOT / "integration" / "web"),
            ],
            cwd=ROOT,
            env=runner_env,
            capture_output=True,
            text=True,
            timeout=240,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        pytest.fail("PostgreSQL backup replication Settings runner did not complete", pytrace=False)
    raw_runner_output = result.stdout + "\n" + result.stderr
    _require(
        all(not value or value not in raw_runner_output for value in pg_http_world.secrets),
        "PostgreSQL or S3 fixture secrets appeared in browser-runner output",
    )
    output = redact_secrets(raw_runner_output, *pg_http_world.secrets)[-6000:]
    failed_job = pg_http_world.database_connection.execute(
        "SELECT j.status,j.result_code,r.status,r.failure_category "
        "FROM instance_admin_jobs AS j "
        "JOIN users AS u ON u.user_id=j.requested_by_user_id "
        "LEFT JOIN instance_backup_replications AS r ON r.archive_id=j.job_id "
        "WHERE u.username=%s AND j.action='backup' "
        "ORDER BY j.requested_at DESC,j.job_id DESC LIMIT 1",
        (PG_WEB_BACKUP_REPLICATION_USERNAME,),
    ).fetchone()
    allowed_job_states = {"queued", "running", "succeeded", "failed", "interrupted"}
    allowed_result_codes = {"completed", "backup_failed", "interrupted"}
    allowed_replication_states = {
        "pending_archive", "pending", "running", "retry_wait", "succeeded", "failed", "interrupted"
    }
    allowed_failure_categories = {
        "archive_unavailable", "credentials_invalid", "remote_unavailable",
        "remote_integrity_mismatch", "replication_failed",
    }
    safe_failed_job = None
    if failed_job is not None:
        safe_failed_job = tuple(
            value if value in allowed else ("unknown" if value is not None else None)
            for value, allowed in zip(
                failed_job,
                (
                    allowed_job_states,
                    allowed_result_codes,
                    allowed_replication_states,
                    allowed_failure_categories,
                ),
            )
        )
    allowed_backup_phases = {
        "prepare",
        "read_backup_key",
        "create_private_work_dir",
        "write_postgres_service_file",
        "begin_snapshot_transaction",
        "validate_postgres_schema_marker",
        "read_postgres_server_version",
        "export_snapshot_and_pin_objects",
        "run_pg_dump",
        "validate_pg_dump",
        "commit_snapshot_and_object_pins",
        "copy_and_verify_external_objects",
        "release_object_pins",
        "build_archive_metadata",
        "write_archive_key_material",
        "build_archive_manifest",
        "encrypt_archive",
        "publish_archive",
        "hash_published_archive",
    }
    allowed_backup_error_codes = {
        "INTERNAL",
        "BACKUP_ARCHIVE_EXISTS",
        "BACKUP_TOOL_UNSUPPORTED",
        "BACKUP_SCHEMA_UNSUPPORTED",
        "BACKUP_MANIFEST_INVALID",
        "BACKUP_DATABASE_MISSING",
        "UNSUPPORTED_DATABASE_URL",
        "BACKUP_ALREADY_RUNNING",
        "MAINTENANCE_ALREADY_RUNNING",
    }
    safe_backup_diagnostics: dict[str, list[dict[str, str]]] = {
        "node_a": [],
        "node_b": [],
    }
    for node_name, log_path in zip(("node_a", "node_b"), pg_http_world.log_paths):
        if not log_path.exists():
            continue
        for line in log_path.read_text(encoding="utf-8", errors="replace").splitlines():
            is_backup_phase_failure = "PostgreSQL instance backup failed" in line
            is_backup_job_failure = (
                "PostgreSQL instance-admin job operation failed" in line
                and "action=backup" in line
            )
            if not (is_backup_phase_failure or is_backup_job_failure):
                continue
            phase_match = re.search(
                r"(?:^|\s)(?:backup_phase|phase)=(?:\"([^\"]+)\"|([A-Za-z0-9_]+))",
                line,
            )
            error_match = re.search(
                r"(?:^|\s)error_code=(?:\"([^\"]+)\"|([A-Za-z0-9_]+))",
                line,
            )
            raw_phase = (
                next((value for value in phase_match.groups() if value), None)
                if phase_match
                else None
            )
            raw_error = (
                next((value for value in error_match.groups() if value), None)
                if error_match
                else None
            )
            safe_backup_diagnostics[node_name].append(
                {
                    "backup_phase": (
                        raw_phase if raw_phase in allowed_backup_phases else "unavailable"
                    ),
                    "error_code": (
                        raw_error if raw_error in allowed_backup_error_codes else "unavailable"
                    ),
                }
            )
    for node_records in safe_backup_diagnostics.values():
        unique_records: list[dict[str, str]] = []
        for record in node_records:
            if record not in unique_records:
                unique_records.append(record)
        node_records[:] = unique_records
    _require(
        result.returncode == 0,
        "PostgreSQL backup replication Chromium runner failed; "
        f"safe_job_state={safe_failed_job}; "
        f"safe_backup_diagnostics={safe_backup_diagnostics}; redacted output: {output}",
    )
    required_assertions = (
        "assert: admin_profile_registered=true",
        "assert: replication_card_capability_advertised=true",
        "assert: initial_status_shared_across_nodes=true",
        "assert: settings_loaded_safe_empty_status=true",
        "assert: backup_job_created=true",
        "assert: pg_node_b_shared_success=true",
        "assert: safe_dto_and_ui=true",
        "assert: settings_rendered_verified_replica=true",
        "assert: browser_storage_contains_no_bootstrap_or_password=true",
        "assert: pg_backup_replication_web_pass=true",
        "assert: browser_cleanup_complete=true",
        "assert: page_errors=0",
        "assert: request_failures=0",
        "assert: relay_requests=0",
        "assert: web_release_sha256=",
    )
    missing_assertions = [item for item in required_assertions if item not in result.stdout]
    _require(
        not missing_assertions,
        "PostgreSQL replication browser assertions were incomplete; "
        f"missing={','.join(missing_assertions)}; redacted output: {output}",
    )

    database = pg_http_world.database_connection
    job_row = database.execute(
        "SELECT j.job_id,j.status,j.result_code,j.archive_bytes,j.archive_sha256,"
        "j.archive_timestamp,j.requested_by_user_id,j.requested_by_device_id "
        "FROM instance_admin_jobs AS j JOIN users AS u "
        "ON u.user_id=j.requested_by_user_id "
        "WHERE u.username=%s AND j.action='backup' "
        "ORDER BY j.requested_at DESC,j.job_id DESC LIMIT 1",
        (PG_WEB_BACKUP_REPLICATION_USERNAME,),
    ).fetchone()
    _require(
        job_row is not None
        and job_row[1:3] == ("succeeded", "completed")
        and isinstance(job_row[0], str)
        and isinstance(job_row[3], int)
        and job_row[3] > 0
        and isinstance(job_row[4], str)
        and re.fullmatch(r"[0-9a-f]{64}", job_row[4]) is not None
        and isinstance(job_row[5], str)
        and job_row[6] is not None
        and job_row[7] is not None,
        "the browser-triggered PG archive must finish with exact private metadata and a real actor",
    )
    replication_row = database.execute(
        "SELECT origin,status,archive_bytes,archive_sha256,attempt_count,"
        "failure_category,next_attempt_at,completed_at "
        "FROM instance_backup_replications WHERE archive_id=%s",
        (job_row[0],),
    ).fetchone()
    _require(
        replication_row is not None
        and replication_row[0:4] == ("manual", "succeeded", job_row[3], job_row[4])
        and replication_row[4] >= 1
        and replication_row[5] is None
        and replication_row[6] is None
        and replication_row[7] is not None,
        "the shared PostgreSQL outbox must verify the uploaded archive digest before success",
    )

    archive_dir = pg_http_world.root / "shared" / "backup-archives"
    archive_paths = list(archive_dir.glob(f"atermius-backup-*-{job_row[0]}.atb"))
    _require(
        len(archive_paths) == 1 and archive_paths[0].is_file(),
        "the PG worker must create exactly one local encrypted archive",
    )
    local_archive = archive_paths[0].read_bytes()
    local_digest = hashlib.sha256(local_archive).hexdigest()
    _require(
        len(local_archive) == job_row[3]
        and local_digest == job_row[4]
        and local_digest == replication_row[3],
        "local encrypted archive bytes and SHA-256 must match both PG ledgers",
    )

    endpoint = pg_http_world.backup_replica_endpoint_url
    _require(endpoint is not None, "the PG replication fixture must expose its private loopback endpoint")
    object_key = (
        f"{PG_REPLICA_PREFIX}/atermius/v1/"
        f"{pg_http_world.instance['instance_id']}/{job_row[0]}.atb"
    )
    remote_url = (
        f"{endpoint}/{PG_REPLICA_BUCKET}/"
        f"{urllib.parse.quote(object_key, safe='/')}"
    )
    request = urllib.request.Request(
        remote_url,
        headers={
            "Authorization": (
                "AWS4-HMAC-SHA256 Credential="
                f"{PG_REPLICA_ACCESS_KEY_ID}/fixture/s3/aws4_request"
            )
        },
        method="GET",
    )
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            remote_archive = response.read()
            remote_sha256_header = response.headers.get("x-amz-meta-atermius-sha256")
            remote_content_length = response.headers.get("content-length")
            remote_status = response.status
    except (OSError, urllib.error.URLError, TimeoutError):
        pytest.fail("loopback S3 fixture did not return the replicated archive", pytrace=False)
    _require(
        remote_status == 200
        and remote_content_length == str(job_row[3])
        and remote_sha256_header == job_row[4]
        and len(remote_archive) == len(local_archive)
        and hashlib.sha256(remote_archive).hexdigest() == job_row[4]
        and remote_archive == local_archive,
        "the S3 replica must contain the byte-exact encrypted archive with the persisted SHA-256",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_replica_restore_web"],
    indirect=True,
    scope="module",
)
def test_pg_http_replica_restore_settings_stage_acceptance(
    pg_http_world: PgHttpWorld, tmp_path: Path, request: pytest.FixtureRequest
) -> None:
    """Restore a shared S3 replica into an isolated PG stage from a second node."""
    pg_dump = shutil.which("pg_dump")
    pg_restore = shutil.which("pg_restore")
    if pg_dump is None or pg_restore is None:
        pytest.skip("PG replica restore acceptance requires pg_dump and pg_restore")
    dump_version = subprocess.run(
        [pg_dump, "--version"], capture_output=True, text=True, check=False
    )
    restore_version = subprocess.run(
        [pg_restore, "--version"], capture_output=True, text=True, check=False
    )
    server_version = pg_http_world.database_connection.execute(
        "SELECT current_setting('server_version_num')::integer"
    ).fetchone()[0] // 10_000
    dump_match = re.search(r"\b([0-9]+)(?:\.[0-9]+)?\b", dump_version.stdout)
    restore_match = re.search(r"\b([0-9]+)(?:\.[0-9]+)?\b", restore_version.stdout)
    if not (
        dump_version.returncode == 0
        and restore_version.returncode == 0
        and dump_match is not None
        and restore_match is not None
        and int(dump_match.group(1)) >= server_version
        and int(restore_match.group(1)) >= int(dump_match.group(1))
    ):
        pytest.skip("PG replica restore acceptance requires version-compatible PostgreSQL tools")
    _require(
        pg_http_world.restore_target_url is not None
        and pg_http_world.backup_replica_endpoint_url is not None
        and pg_http_world.backup_replica_fixture_control_token is not None,
        "the replica restore fixture must configure an isolated target and private loopback S3 control",
    )

    bootstrap_token = pg_http_world.bootstrap_token()
    password = f"PgReplicaRestore-{uuid.uuid4().hex}"
    for value in (bootstrap_token, password, PG_WEB_BACKUP_REPLICATION_USERNAME):
        pg_http_world.remember_secret(value)

    handoff_dir = tmp_path / "pg-replica-restore-handoff"
    handoff_dir.mkdir(mode=0o700)
    if os.name == "posix":
        os.chmod(handoff_dir, 0o700)
    runner_env = {
        key: os.environ[key]
        for key in (
            "PATH",
            "HOME",
            "TMPDIR",
            "TMP",
            "TEMP",
            "XDG_CACHE_HOME",
            "CI",
            "PLAYWRIGHT_BROWSERS_PATH",
            "PLAYWRIGHT_CHROMIUM_EXECUTABLE",
        )
        if key in os.environ
    }
    runner_env.update(
        {
            "ATERMIUS_PG_REPLICA_RESTORE_NODE_A_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_REPLICA_RESTORE_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_REPLICA_RESTORE_USERNAME": PG_WEB_BACKUP_REPLICATION_USERNAME,
            "ATERMIUS_PG_REPLICA_RESTORE_PASSWORD": password,
            "ATERMIUS_PG_REPLICA_RESTORE_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_REPLICA_RESTORE_HANDOFF_DIR": str(handoff_dir),
        }
    )
    _require(
        not any(
            key.startswith("ATERMIUS_BACKUP_")
            or key.startswith("ATERMIUS_SYNC_")
            or key in {"ATERMIUS_DATABASE_URL", "ATERMIUS_TEST_PG_URL"}
            for key in runner_env
        ),
        "PG URLs, S3 settings, and fixture-control secrets must stay outside the browser runner",
    )

    browser_runner: subprocess.Popen[str] | None = None

    def stop_browser_runner() -> None:
        if browser_runner is not None and browser_runner.poll() is None:
            try:
                os.killpg(browser_runner.pid, signal.SIGTERM)
            except ProcessLookupError:
                return
            try:
                browser_runner.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(browser_runner.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                browser_runner.communicate(timeout=5)

    def wait_for_handoff(name: str, timeout: float = 300.0) -> dict[str, str]:
        marker = handoff_dir / name
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if marker.is_file() and not marker.is_symlink():
                value = json.loads(marker.read_text(encoding="utf-8"))
                return value
            if browser_runner is not None and browser_runner.poll() is not None:
                stdout, stderr = browser_runner.communicate(timeout=5)
                detail = redact_secrets(
                    stdout + "\n" + stderr, *pg_http_world.secrets
                )[-5000:]
                pytest.fail(
                    "PG replica restore Chromium runner exited before its private handoff; "
                    "redacted output: " + detail,
                    pytrace=False,
                )
            time.sleep(0.05)
        pytest.fail("PG replica restore Chromium runner did not reach its private handoff", pytrace=False)

    def write_handoff_signal(name: str) -> None:
        signal_path = handoff_dir / name
        descriptor = os.open(signal_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "wb") as handle:
            handle.flush()
            os.fsync(handle.fileno())

    try:
        browser_runner = subprocess.Popen(
            ["npm", "run", "test:pg-backup-replica-restore", "--prefix", str(ROOT / "integration" / "web")],
            cwd=ROOT,
            env=runner_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            start_new_session=True,
        )
        request.addfinalizer(stop_browser_runner)

        replica_ready = wait_for_handoff("replica-ready.json")
        archive_id = replica_ready.get("archive_id")
        _require(
            set(replica_ready) == {"archive_id"}
            and isinstance(archive_id, str)
            and str(uuid.UUID(archive_id)) == archive_id,
            "browser handoff must contain only the canonical replica archive ID",
        )
        database = pg_http_world.database_connection
        backup_row = database.execute(
            "SELECT j.job_id,j.archive_timestamp,j.status,j.result_code,j.request_origin,"
            "j.archive_bytes,j.archive_sha256,r.status,r.archive_bytes,r.archive_sha256 "
            "FROM instance_admin_jobs AS j "
            "JOIN instance_backup_replications AS r ON r.archive_id=j.job_id "
            "WHERE j.job_id=%s AND j.action='backup' AND j.archive_id=%s",
            (archive_id, archive_id),
        ).fetchone()
        _require(
            backup_row is not None
            and backup_row[0] == archive_id
            and backup_row[2:5] == ("succeeded", "completed", "manual")
            and isinstance(backup_row[1], str)
            and isinstance(backup_row[5], int)
            and backup_row[5] > 0
            and isinstance(backup_row[6], str)
            and re.fullmatch(r"[0-9a-f]{64}", backup_row[6]) is not None
            and backup_row[7:10] == ("succeeded", backup_row[5], backup_row[6]),
            "the replica source must match a succeeded manual backup and its shared outbox metadata",
        )

        endpoint = pg_http_world.backup_replica_endpoint_url
        object_key = (
            f"{PG_REPLICA_PREFIX}/atermius/v1/"
            f"{pg_http_world.instance['instance_id']}/{archive_id}.atb"
        )
        remote_url = (
            f"{endpoint}/{PG_REPLICA_BUCKET}/"
            f"{urllib.parse.quote(object_key, safe='/')}"
        )
        remote_request = urllib.request.Request(
            remote_url,
            headers={
                "Authorization": (
                    "AWS4-HMAC-SHA256 Credential="
                    f"{PG_REPLICA_ACCESS_KEY_ID}/fixture/s3/aws4_request"
                )
            },
            method="GET",
        )
        try:
            with urllib.request.urlopen(remote_request, timeout=20) as response:
                remote_archive = response.read()
                remote_sha256 = response.headers.get("x-amz-meta-atermius-sha256")
                remote_length = response.headers.get("content-length")
                remote_status = response.status
        except (OSError, urllib.error.URLError, TimeoutError):
            pytest.fail("the loopback S3 replica was unavailable at the first handoff", pytrace=False)
        _require(
            remote_status == 200
            and remote_length == str(backup_row[5])
            and remote_sha256 == backup_row[6]
            and len(remote_archive) == backup_row[5]
            and hashlib.sha256(remote_archive).hexdigest() == backup_row[6],
            "the handoff replica bytes must match the shared outbox size and digest",
        )
        local_archive_path = (
            Path(pg_http_world.runtime_env["ATERMIUS_BACKUP_ARCHIVE_DIR"])
            / f"atermius-backup-{backup_row[1]}-{archive_id}.atb"
        )
        _require(
            local_archive_path.is_file()
            and local_archive_path.stat().st_size == backup_row[5]
            and hashlib.sha256(local_archive_path.read_bytes()).hexdigest() == backup_row[6],
            "the producer archive must match its shared metadata before the local copy is removed",
        )
        local_archive_path.unlink()
        _require(not local_archive_path.exists(), "the local producer archive must be absent for remote restore")
        source_before = database.execute(
            "SELECT instance_id,generation,signing_public_key,"
            "(SELECT COUNT(*) FROM blob_objects),(SELECT COUNT(*) FROM users),"
            "(SELECT COUNT(*) FROM vaults) FROM instance_meta WHERE id=1"
        ).fetchone()
        _require(source_before is not None, "the live source identity must exist before restore")
        write_handoff_signal("continue-replica")

        stage_ready = wait_for_handoff("stage-ready.json")
        restore_job_id = stage_ready.get("job_id")
        _require(
            set(stage_ready) == {"job_id", "archive_id"}
            and stage_ready.get("archive_id") == archive_id
            and isinstance(restore_job_id, str)
            and str(uuid.UUID(restore_job_id)) == restore_job_id,
            "stage handoff must contain only its canonical restore and archive IDs",
        )
        restore_row = database.execute(
            "SELECT archive_id,archive_source,archive_sha256,status,result_code,"
            "restore_stage_status,restore_stage_generation,restore_stage_binding_id::text,"
            "restore_stage_target_fingerprint,restore_stage_target_database_oid,"
            "restore_stage_target_database_name,restore_stage_schema,"
            "restore_stage_object_store_id,restore_stage_object_count "
            "FROM instance_admin_jobs WHERE job_id=%s AND action='restore'",
            (restore_job_id,),
        ).fetchone()
        _require(
            restore_row is not None
            and restore_row[:6] == (
                archive_id, "replica", backup_row[6], "succeeded", "completed", "ready"
            )
            and isinstance(restore_row[6], str)
            and str(uuid.UUID(restore_row[6])) == restore_row[6]
            and isinstance(restore_row[7], str)
            and str(uuid.UUID(restore_row[7])) == restore_row[7]
            and isinstance(restore_row[8], str)
            and re.fullmatch(r"[0-9a-f]{64}", restore_row[8]) is not None
            and isinstance(restore_row[9], int)
            and restore_row[9] > 0
            and isinstance(restore_row[10], str)
            and restore_row[11] == pg_http_world.schema
            and isinstance(restore_row[12], str)
            and isinstance(restore_row[13], int)
            and restore_row[13] >= 0,
            "the shared PG restore job must bind the replica digest to a ready isolated target",
        )
        stage_dir = (
            Path(pg_http_world.runtime_env["ATERMIUS_BACKUP_ARCHIVE_DIR"])
            / "restore-staging"
            / f"atermius-pg-restore-{restore_job_id}"
        )
        receipt = json.loads(
            (stage_dir / "postgres-restore-receipt.json").read_text(encoding="utf-8")
        )
        _require(
            receipt.get("job_id") == restore_job_id
            and receipt.get("archive_id") == archive_id
            and receipt.get("archive_sha256") == backup_row[6]
            and receipt.get("generation") == restore_row[6]
            and receipt.get("binding_id") == restore_row[7]
            and receipt.get("target_database_oid") == restore_row[9]
            and receipt.get("target_database_name") == restore_row[10]
            and receipt.get("schema") == pg_http_world.schema
            and receipt.get("restored_objects") == restore_row[13],
            "the private receipt must bind the replica digest, job and isolated target metadata",
        )
        target = pg_http_world.psycopg.connect(
            pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
        )
        try:
            target.execute(
                pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                    pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
                )
            )
            target_state = target.execute(
                "SELECT s.schema_version,m.instance_id,m.generation,m.signing_public_key,"
                "(SELECT COUNT(*) FROM users),(SELECT COUNT(*) FROM vaults),"
                "(SELECT COUNT(*) FROM blob_objects),"
                "(SELECT COUNT(*) FROM sessions WHERE revoked_at IS NULL) "
                "FROM atermius_instance_schema s CROSS JOIN instance_meta m "
                "WHERE s.singleton=1 AND m.id=1"
            ).fetchone()
            target_name, target_oid = target.execute(
                "SELECT current_database(),(SELECT oid FROM pg_database "
                "WHERE datname=current_database())"
            ).fetchone()
        finally:
            target.close()
        _require(
            target_state is not None
            and target_state[0] == 38
            and target_state[1] == source_before[0]
            and target_state[2] == restore_row[6]
            and target_state[2] != source_before[1]
            and target_state[3] == source_before[2]
            and target_state[4] == source_before[4]
            and target_state[5] == source_before[5]
            and target_state[6] == source_before[3]
            and target_state[7] == 0
            and target_oid == restore_row[9]
            and target_name == restore_row[10],
            "replica restore must populate only the distinct isolated target at current schema 38",
        )
        _require(
            not (stage_dir / "postgres.dump").exists()
            and not (stage_dir / "postgres-metadata.json").exists()
            and not (stage_dir / "object-00000000.blob").exists()
            and not (Path(pg_http_world.runtime_env["ATERMIUS_BACKUP_ARCHIVE_DIR"])
                     / "restore-staging" / f"atermius-pg-restore-{restore_job_id}.source.atb").exists(),
            "a prepared replica stage must contain no extracted payload or remote source archive",
        )
        write_handoff_signal("continue")

        discarded = wait_for_handoff("discarded.json", timeout=120)
        _require(
            set(discarded) == {"archive_id"} and discarded["archive_id"] == archive_id,
            "discard handoff must contain only the canonical archive ID",
        )
        discarded_row = database.execute(
            "SELECT status,result_code,archive_source,restore_stage_status "
            "FROM instance_admin_jobs WHERE job_id=%s",
            (restore_job_id,),
        ).fetchone()
        _require(
            discarded_row == ("succeeded", "completed", "replica", "discarded")
            and not stage_dir.exists(),
            "Settings discard must remove the isolated restore files and retain shared outcome",
        )
        target = pg_http_world.psycopg.connect(
            pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
        )
        try:
            schemas_left = target.execute(
                "SELECT to_regnamespace(%s) IS NOT NULL,"
                "to_regnamespace('atermius_restore_control') IS NOT NULL",
                (pg_http_world.schema,),
            ).fetchone()
        finally:
            target.close()
        _require(
            schemas_left == (False, False),
            "discard must remove both the restored application schema and its target control marker",
        )
        source_after_discard = database.execute(
            "SELECT instance_id,generation,signing_public_key,"
            "(SELECT COUNT(*) FROM blob_objects),(SELECT COUNT(*) FROM users),"
            "(SELECT COUNT(*) FROM vaults) FROM instance_meta WHERE id=1"
        ).fetchone()
        _require(
            source_after_discard == source_before,
            "replica prepare and discard must leave the live source database unchanged",
        )

        delete_url = (
            f"{endpoint}/__fixture/object?key={urllib.parse.quote(object_key, safe='')}"
        )
        delete_request = urllib.request.Request(
            delete_url,
            headers={
                "x-fixture-control-token": pg_http_world.backup_replica_fixture_control_token
            },
            method="DELETE",
        )
        try:
            with urllib.request.urlopen(delete_request, timeout=10) as response:
                delete_status = response.status
        except (OSError, urllib.error.URLError, TimeoutError):
            pytest.fail("private loopback S3 control could not remove the replica object", pytrace=False)
        _require(delete_status == 204, "the controlled S3 fixture must remove the exact replica object")
        write_handoff_signal("try-missing")

        missing_failed = wait_for_handoff("missing-failed.json", timeout=120)
        _require(
            set(missing_failed) == {"archive_id"}
            and missing_failed["archive_id"] == archive_id,
            "missing-object failure handoff must contain only the canonical archive ID",
        )
        restore_object = urllib.request.Request(
            delete_url,
            data=remote_archive,
            headers={
                "x-fixture-control-token": pg_http_world.backup_replica_fixture_control_token,
                "content-type": "application/octet-stream",
            },
            method="PUT",
        )
        try:
            with urllib.request.urlopen(restore_object, timeout=20) as response:
                restore_object_status = response.status
        except (OSError, urllib.error.URLError, TimeoutError):
            pytest.fail("private loopback S3 control could not restore the replica fixture bytes", pytrace=False)
        _require(
            restore_object_status == 204,
            "the controlled S3 fixture must restore the exact encrypted object before tampering",
        )
        corrupt_object = urllib.request.Request(
            delete_url,
            headers={
                "x-fixture-control-token": pg_http_world.backup_replica_fixture_control_token
            },
            method="PATCH",
        )
        try:
            with urllib.request.urlopen(corrupt_object, timeout=10) as response:
                corrupt_object_status = response.status
        except (OSError, urllib.error.URLError, TimeoutError):
            pytest.fail("private loopback S3 control could not tamper with the test object", pytrace=False)
        _require(
            corrupt_object_status == 204,
            "the controlled S3 fixture must tamper with one byte while preserving remote HEAD metadata",
        )
        try:
            with urllib.request.urlopen(remote_request, timeout=20) as response:
                tampered_archive = response.read()
                tampered_sha256_header = response.headers.get("x-amz-meta-atermius-sha256")
                tampered_length = response.headers.get("content-length")
                tampered_status = response.status
        except (OSError, urllib.error.URLError, TimeoutError):
            pytest.fail("the tampered loopback S3 fixture object could not be read", pytrace=False)
        _require(
            tampered_status == 200
            and tampered_length == str(backup_row[5])
            and tampered_sha256_header == backup_row[6]
            and len(tampered_archive) == backup_row[5]
            and hashlib.sha256(tampered_archive).hexdigest() != backup_row[6],
            "content-mismatch fixture must retain correct length/HEAD metadata but change the actual digest",
        )
        write_handoff_signal("corrupt-replica")

        try:
            stdout, stderr = browser_runner.communicate(timeout=360)
        except subprocess.TimeoutExpired:
            stop_browser_runner()
            pytest.fail("PG replica restore Chromium runner exceeded its bounded timeout", pytrace=False)
        raw_output = stdout + "\n" + stderr
        _require(
            all(not secret or secret not in raw_output for secret in pg_http_world.secrets),
            "PostgreSQL, S3, bootstrap, or password secrets appeared in browser-runner output",
        )
        output = redact_secrets(raw_output, *pg_http_world.secrets)[-7000:]
        _require(
            browser_runner.returncode == 0,
            "PostgreSQL replica restore Chromium runner failed; redacted output: " + output,
        )
        required_assertions = (
            "assert: pg_restore_replica_capability_advertised=true",
            "assert: manual_encrypted_backup_accepted=true",
            "assert: node_b_verified_replication_success=true",
            "assert: safe_replica_catalogs_match_across_nodes=true",
            "assert: settings_selected_remote_replica=true",
            "assert: settings_submitted_replica_restore_once=true",
            "assert: node_b_observed_ready_replica_restore_stage=true",
            "assert: settings_rendered_prepared_replica_stage=true",
            "assert: node_b_observed_discarded_replica_restore_stage=true",
            "assert: missing_replica_restore_failed_safely_on_both_nodes=true",
            "assert: missing_replica_public_job_dto_has_no_binding_or_provider_diagnostics=true",
            "assert: mismatched_replica_digest_failed_safely_on_both_nodes=true",
            "assert: browser_storage_credentials_absent=true",
            "assert: browser_cleanup_complete=true",
            "assert: page_errors=0",
            "assert: request_failures=0",
            "assert: relay_requests=0",
            "assert: external_requests=0",
            "assert: web_release_sha256=",
            "WEB-PG-BACKUP-REPLICA-RESTORE-01 passed",
        )
        missing_assertions = [item for item in required_assertions if item not in stdout]
        _require(
            not missing_assertions,
            "PostgreSQL replica restore browser assertions were incomplete; "
            f"missing={','.join(missing_assertions)}; redacted output: {output}",
        )

        restore_jobs = database.execute(
            "SELECT job_id,archive_source,archive_sha256,status,result_code,restore_stage_status,"
            "restore_stage_ready_at,restore_stage_generation,restore_stage_binding_id,"
            "restore_stage_target_fingerprint,restore_stage_target_database_oid,"
            "restore_stage_target_database_name,restore_stage_schema,"
            "restore_stage_object_store_id,restore_stage_object_count "
            "FROM instance_admin_jobs WHERE action='restore' AND archive_id=%s "
            "ORDER BY requested_at,job_id",
            (archive_id,),
        ).fetchall()
        _require(
            len(restore_jobs) == 3
            and restore_jobs[0][0] == restore_job_id
            and restore_jobs[0][1:6] == ("replica", backup_row[6], "succeeded", "completed", "discarded")
            and restore_jobs[1][1:6] == ("replica", None, "failed", "restore_failed", "failed")
            and restore_jobs[2][1:6] == ("replica", None, "failed", "restore_failed", "failed")
            and all(value is None for value in restore_jobs[1][6:])
            and all(value is None for value in restore_jobs[2][6:]),
            "missing or digest-mismatched replicas must fail without publishing restore-stage binding metadata",
        )
        missing_job_id = restore_jobs[1][0]
        mismatched_job_id = restore_jobs[2][0]
        staging_root = (
            Path(pg_http_world.runtime_env["ATERMIUS_BACKUP_ARCHIVE_DIR"]) / "restore-staging"
        )
        _require(
            not (staging_root / f"atermius-pg-restore-{missing_job_id}.source.atb").exists()
            and not (staging_root / f"atermius-pg-restore-{missing_job_id}").exists()
            and not (staging_root / f"atermius-pg-restore-{mismatched_job_id}.source.atb").exists()
            and not (staging_root / f"atermius-pg-restore-{mismatched_job_id}").exists()
            and not local_archive_path.exists(),
            "failed remote downloads must leave no local fallback or private staging artifact",
        )
        outbox_after = database.execute(
            "SELECT status,archive_bytes,archive_sha256 FROM instance_backup_replications "
            "WHERE archive_id=%s",
            (archive_id,),
        ).fetchone()
        _require(
            outbox_after == ("succeeded", backup_row[5], backup_row[6]),
            "remote object loss must not rewrite the immutable successful replica ledger",
        )
        source_after_failure = database.execute(
            "SELECT instance_id,generation,signing_public_key,"
            "(SELECT COUNT(*) FROM blob_objects),(SELECT COUNT(*) FROM users),"
            "(SELECT COUNT(*) FROM vaults) FROM instance_meta WHERE id=1"
        ).fetchone()
        _require(
            source_after_failure == source_before,
            "failed replica restore must leave the live source database unchanged",
        )
        server_logs = pg_http_world.redacted_log_tail(limit=100_000)
        _require(
            remote_url not in server_logs and object_key not in server_logs,
            "the S3 endpoint or deterministic archive key must not appear in PostgreSQL node logs",
        )
    finally:
        stop_browser_runner()


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_v25_restore_web"],
    indirect=True,
    scope="module",
)
def test_pg_http_v25_encrypted_restore_settings_stage_acceptance(
    pg_http_world: PgHttpWorld, tmp_path: Path, request: pytest.FixtureRequest
) -> None:
    """Submit a historical encrypted PostgreSQL archive through current Web Settings."""
    _require(
        pg_http_world.restore_target_url is not None
        and pg_http_world.v25_archive_url is not None,
        "the PG17 Web restore acceptance requires disposable archive and isolated target databases",
    )

    source_before = pg_http_world.database_connection.execute(
        "SELECT instance_id,generation,signing_public_key,"
        "(SELECT COUNT(*) FROM blob_objects) FROM instance_meta WHERE id=1"
    ).fetchone()
    _require(source_before is not None, "the PostgreSQL source identity must be initialized")
    _require(
        pg_http_world.clients[0].request("GET", "/api/v1/admin/restore-sources?limit=10&offset=0").status
        == 401,
        "unauthenticated restore-source listing must be rejected",
    )
    no_auth_restore = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        json_body={
            "request_id": str(uuid.uuid4()),
            "action": "restore",
            "archive_id": str(uuid.uuid4()),
            "archive_source": "local",
        },
    )
    _require(
        no_auth_restore.status == 401,
        "unauthenticated historical restore submission must be rejected",
    )

    publisher_env = pg_http_world.runtime_env.copy()
    publisher_tmp = pg_http_world.root / "publisher-tmp"
    publisher_tmp.mkdir(mode=0o700)
    publisher_env.update(
        {
            "ATERMIUS_TEST_PG_URL": pg_http_world.pg_url,
            "ATERMIUS_TEST_PG_V25_ARCHIVE_URL": pg_http_world.v25_archive_url,
            "ATERMIUS_TEST_PG_SCHEMA": pg_http_world.schema,
            "ATERMIUS_PG_RESTORE_TARGET_URL": pg_http_world.restore_target_url,
            "CARGO_TARGET_DIR": os.environ.get(
                "CARGO_TARGET_DIR", str(pg_http_world.binary.parent.parent)
            ),
            "TMPDIR": str(publisher_tmp),
            "CARGO_INCREMENTAL": "0",
        }
    )
    publish = subprocess.run(
        [
            "cargo",
            "test",
            "--locked",
            "--manifest-path",
            str(ROOT / "server" / "Cargo.toml"),
            "--lib",
            "backup::tests::postgres_publish_encrypted_schema_25_archive_for_http_acceptance",
            "--",
            "--ignored",
            "--exact",
            "--nocapture",
            "--test-threads=1",
        ],
        cwd=ROOT,
        env=publisher_env,
        capture_output=True,
        text=True,
        timeout=900,
        check=False,
    )
    publish_output = redact_secrets(
        publish.stdout + "\n" + publish.stderr,
        *pg_http_world.secrets,
        pg_http_world.v25_archive_url,
        pg_http_world.restore_target_url,
    )
    _require(
        publish.returncode == 0,
        "Rust marker-25 encrypted archive publisher failed; redacted output: "
        + publish_output[-6000:],
    )
    fixture_match = re.search(r"PG-V25-HTTP-FIXTURE archive_id=([0-9a-f-]{36})", publish_output)
    _require(fixture_match is not None, "the Rust publisher omitted its safe archive identity")
    archive_id = str(uuid.UUID(fixture_match.group(1)))
    archive_row = pg_http_world.database_connection.execute(
        "SELECT archive_id,archive_timestamp,archive_sha256,archive_bytes,status,result_code "
        "FROM instance_admin_jobs WHERE action='backup' AND archive_id=%s",
        (archive_id,),
    ).fetchone()
    _require(
        archive_row is not None
        and archive_row[0] == archive_id
        and re.fullmatch(r"[0-9]{8}T[0-9]{6}\.[0-9]{3}Z", archive_row[1]) is not None
        and re.fullmatch(r"[0-9a-f]{64}", archive_row[2]) is not None
        and archive_row[3] > 0
        and archive_row[4:] == ("succeeded", "completed"),
        "the historical archive must have a durable successful source row",
    )
    archive_path = (
        Path(pg_http_world.runtime_env["ATERMIUS_BACKUP_ARCHIVE_DIR"])
        / f"atermius-backup-{archive_row[1]}-{archive_id}.atb"
    )
    _require(
        archive_path.is_file() and archive_path.stat().st_size == archive_row[3],
        "the encrypted v25 archive file must match its private source ledger metadata",
    )

    bootstrap_result = pg_http_world.run_cli_result("bootstrap")
    if bootstrap_result.returncode != 0:
        detail = redact_secrets(
            bootstrap_result.stderr or bootstrap_result.stdout,
            *pg_http_world.secrets,
        )[-1600:]
        pytest.fail("PG v25 restore browser bootstrap failed; redacted detail: " + detail, pytrace=False)
    bootstrap_match = re.search(
        r"one-time setup token[^\n]*:\s*([A-Za-z0-9_-]{43})",
        bootstrap_result.stdout,
    )
    _require(bootstrap_match is not None, "PG v25 restore bootstrap omitted its one-time token")
    bootstrap_token = bootstrap_match.group(1)
    password = f"PgV25Restore-{uuid.uuid4().hex}"
    for value in (bootstrap_token, password, PG_WEB_V25_RESTORE_USERNAME):
        pg_http_world.remember_secret(value)

    discard_gate_dir = tmp_path / "pg-v25-restore-discard-gate"
    discard_gate_dir.mkdir(mode=0o700)
    runner_env = pg_http_world.runtime_env.copy()
    runner_env.update(
        {
            "ATERMIUS_PG_V25_RESTORE_NODE_A_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_V25_RESTORE_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_V25_RESTORE_ARCHIVE_ID": archive_id,
            "ATERMIUS_PG_V25_RESTORE_ADMIN_USERNAME": PG_WEB_V25_RESTORE_USERNAME,
            "ATERMIUS_PG_V25_RESTORE_ADMIN_PASSWORD": password,
            "ATERMIUS_PG_V25_RESTORE_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_V25_RESTORE_DISCARD_GATE_DIR": str(discard_gate_dir),
            "ATERMIUS_PG_HTTP_SERVER_BIN": str(pg_http_world.binary),
        }
    )
    browser_runner: subprocess.Popen[str] | None = None
    def stop_browser_runner() -> None:
        if browser_runner is not None and browser_runner.poll() is None:
            try:
                os.killpg(browser_runner.pid, signal.SIGTERM)
            except ProcessLookupError:
                return
            try:
                browser_runner.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(browser_runner.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                browser_runner.communicate(timeout=5)

    try:
        browser_runner = subprocess.Popen(
            ["node", str(ROOT / "integration" / "web" / "pg_admin_restore_v25.cjs")],
            cwd=ROOT,
            env=runner_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            start_new_session=True,
        )
        request.addfinalizer(stop_browser_runner)
        ready_marker = discard_gate_dir / "stage-ready"
        ready_deadline = time.monotonic() + 180
        while not ready_marker.exists() and browser_runner.poll() is None and time.monotonic() < ready_deadline:
            time.sleep(0.05)
        if not ready_marker.exists():
            stdout, stderr = browser_runner.communicate(timeout=10)
            detail = redact_secrets(stdout + "\n" + stderr, *pg_http_world.secrets)[-6000:]
            server_detail = pg_http_world.redacted_log_tail(limit=4000)
            pytest.fail(
                "PG v25 restore Settings runner did not publish its prepared review gate; "
                "redacted output: " + detail + "\nredacted server log tail: " + server_detail,
                pytrace=False,
            )
    except (OSError, subprocess.TimeoutExpired):
        if browser_runner is not None and browser_runner.poll() is None:
            try:
                os.killpg(browser_runner.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        pytest.fail("PG v25 restore Settings Chromium runner did not reach stage review", pytrace=False)

    restore_rows = pg_http_world.database_connection.execute(
        "SELECT job_id,archive_id,archive_source,archive_sha256,status,result_code,"
        "restore_stage_status,restore_stage_generation FROM instance_admin_jobs "
        "WHERE action='restore' AND archive_id=%s",
        (archive_id,),
    ).fetchall()
    _require(len(restore_rows) == 1, "authorized Settings request must create one restore job")
    restore_row = restore_rows[0]
    restore_job_id = str(uuid.UUID(restore_row[0]))

    outsider = pg_http_world.seed_tenant(tmp_path / "pg-v25-restore-outsider").actors[0]
    denied_sources = pg_http_world.clients[1].request(
        "GET", "/api/v1/admin/restore-sources?limit=10&offset=0", token=outsider.access_token
    )
    denied_restore = pg_http_world.clients[0].request(
        "POST",
        "/api/v1/admin/jobs",
        token=outsider.access_token,
        json_body={
            "request_id": str(uuid.uuid4()),
            "action": "restore",
            "archive_id": archive_id,
            "archive_source": "local",
        },
    )
    discard_path = f"/api/v1/admin/restore-stages/{restore_job_id}/discard"
    unauthenticated_discard = pg_http_world.clients[0].request(
        "POST",
        discard_path,
        json_body={"request_id": str(uuid.uuid4())},
    )
    denied_discard = pg_http_world.clients[1].request(
        "POST",
        discard_path,
        token=outsider.access_token,
        json_body={"request_id": str(uuid.uuid4())},
    )
    _require(
        denied_sources.status == 403
        and _error_code(denied_sources) == "INSTANCE_ADMIN_REQUIRED"
        and denied_restore.status == 403
        and _error_code(denied_restore) == "INSTANCE_ADMIN_REQUIRED"
        and unauthenticated_discard.status == 401
        and denied_discard.status == 403
        and _error_code(denied_discard) == "INSTANCE_ADMIN_REQUIRED",
        "authenticated non-admins must not list, submit, or discard a historical restore",
    )

    restore_row = pg_http_world.database_connection.execute(
        "SELECT archive_id,archive_source,archive_sha256,status,result_code,"
        "restore_stage_status,restore_stage_generation FROM instance_admin_jobs WHERE job_id=%s",
        (restore_job_id,),
    ).fetchone()
    restore_count = pg_http_world.database_connection.execute(
        "SELECT COUNT(*) FROM instance_admin_jobs WHERE action='restore' AND archive_id=%s",
        (archive_id,),
    ).fetchone()[0]
    _require(
        restore_row is not None
        and restore_row[0] == archive_id
        and restore_row[1] == "local"
        and restore_row[2] == archive_row[2]
        and restore_row[3:6] == ("succeeded", "completed", "ready")
        and isinstance(restore_row[6], str)
        and restore_count == 1,
        "only the authorized Settings request must create the succeeded shared restore job",
    )

    stage_dir = (
        Path(pg_http_world.runtime_env["ATERMIUS_BACKUP_ARCHIVE_DIR"])
        / "restore-staging"
        / f"atermius-pg-restore-{restore_job_id}"
    )
    receipt = json.loads((stage_dir / "postgres-restore-receipt.json").read_text(encoding="utf-8"))
    _require(
        receipt.get("job_id") == restore_job_id
        and receipt.get("archive_id") == archive_id
        and receipt.get("archive_sha256") == archive_row[2]
        and receipt.get("generation") == restore_row[6]
        and receipt.get("schema") == pg_http_world.schema
        and receipt.get("restored_objects") == 1,
        "the stage receipt must bind the exact archive, digest, generation, and object count",
    )

    target = pg_http_world.psycopg.connect(
        pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
    )
    try:
        target.execute(
            pg_http_world.psycopg.sql.SQL("SET search_path TO {}").format(
                pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
            )
        )
        target_state = target.execute(
            "SELECT s.schema_version,m.instance_id,m.generation,m.signing_public_key,"
            "b.vault_id,b.object_id,b.size,b.sha256,b.storage_backend,b.storage_store_id,b.storage_key,"
            "(SELECT COUNT(*) FROM sessions WHERE revoked_at IS NULL),"
            "(SELECT COUNT(*) FROM object_references r WHERE r.vault_id=b.vault_id AND r.object_id=b.object_id),"
            "(SELECT interval_hours FROM instance_backup_schedule WHERE schedule_id=1),"
            "(SELECT next_run_at FROM instance_backup_schedule WHERE schedule_id=1) "
            "FROM atermius_instance_schema s CROSS JOIN instance_meta m "
            "CROSS JOIN blob_objects b WHERE s.singleton=1 AND m.id=1 AND b.storage_state='available'"
        ).fetchone()
        archived_sessions = target.execute("SELECT COUNT(*) FROM sessions").fetchone()[0]
        target_database = target.execute("SELECT current_database()").fetchone()[0]
    finally:
        target.close()
    expected_object = b"pg-schema-25-restore-object-bytes\0opaque"
    expected_object_digest = hashlib.sha256(expected_object).hexdigest()
    _require(
        target_state is not None
        and target_state[0] == 38
        and target_state[1] == source_before[0]
        and target_state[2] == restore_row[6]
        and target_state[2] != source_before[1]
        and target_state[3] == source_before[2]
        and target_state[6] == len(expected_object)
        and target_state[7] == expected_object_digest
        and target_state[8] == "filesystem"
        and target_state[9] == receipt["object_store_id"]
        and target_state[10].startswith("atermius/objects/v1/")
        and target_state[11] == 0
        and archived_sessions == 1
        and target_state[12] == 1
        and target_state[13] is None
        and target_state[14] is None,
        "the isolated target must contain migrated v25 data with revoked sessions and disabled schedule",
    )
    object_relative_path = Path(target_state[10])
    _require(
        not object_relative_path.is_absolute()
        and ".." not in object_relative_path.parts,
        "restored object metadata must use a safe relative storage key",
    )
    restored_object_path = stage_dir / "object-store" / object_relative_path
    _require(
        restored_object_path.is_file() and restored_object_path.read_bytes() == expected_object,
        "staged filesystem object bytes must match the archive object metadata and digest",
    )
    _require(
        all(
            not (stage_dir / name).exists()
            for name in ("postgres.dump", "postgres-metadata.json", "object-00000000.blob")
        ),
        "the published stage must remove extracted archive payload files",
    )

    source_after = pg_http_world.database_connection.execute(
        "SELECT instance_id,generation,signing_public_key,"
        "(SELECT COUNT(*) FROM blob_objects),"
        "(SELECT COUNT(*) FROM sessions WHERE revoked_at IS NULL) "
        "FROM instance_meta WHERE id=1"
    ).fetchone()
    admin_user_id = pg_http_world.database_connection.execute(
        "SELECT user_id FROM users WHERE username=%s", (PG_WEB_V25_RESTORE_USERNAME,)
    ).fetchone()
    restore_audit = pg_http_world.database_connection.execute(
        "SELECT action,actor_user_id,actor_device_id,result FROM audit_events "
        "WHERE scope_type='instance' AND resource_type='admin_job' AND actor_user_id=%s "
        "AND action IN ('admin.restore_requested','admin.restore_started','admin.restore_completed') "
        "ORDER BY event_id",
        (admin_user_id[0],) if admin_user_id else (None,),
    ).fetchall()
    _require(
        source_after is not None
        and source_after[0:3] == source_before[0:3]
        and source_after[3] == source_before[3]
        and source_after[4] > 0
        and admin_user_id is not None
        and [event[0] for event in restore_audit]
        == ["admin.restore_requested", "admin.restore_started", "admin.restore_completed"]
        and all(event[1] == admin_user_id[0] and event[2] is not None and event[3] == "success"
                for event in restore_audit),
        "restore must preserve the online source identity/data and write the admin lifecycle audit",
    )
    _require(
        archive_path.is_file() and archive_path.stat().st_size == archive_row[3],
        "the historical source archive must remain unchanged after staging",
    )

    archive_sha256_before_discard = hashlib.sha256(archive_path.read_bytes()).hexdigest()
    _require(
        archive_sha256_before_discard == archive_row[2],
        "the source archive bytes must match the durable digest before stage discard",
    )
    (discard_gate_dir / "continue-discard").write_text("continue\n", encoding="utf-8")
    try:
        browser_stdout, browser_stderr = browser_runner.communicate(timeout=240)
    except subprocess.TimeoutExpired:
        stop_browser_runner()
        pytest.fail("PG v25 restore-stage discard Web runner timed out", pytrace=False)
    browser_output = redact_secrets(
        browser_stdout + "\n" + browser_stderr,
        *pg_http_world.secrets,
    )
    _require(
        browser_runner.returncode == 0,
        "PG v25 restore-stage discard Web runner failed; redacted output: "
        + browser_output[-7000:]
        + "\nredacted server log tail: "
        + pg_http_world.redacted_log_tail(limit=4000),
    )
    required_assertions = (
        "assert: admin_profile_registered=true",
        "assert: unauthorized_restore_routes_denied=true",
        "assert: pg_v25_restore_source_loaded=true",
        "assert: pg_v25_restore_submitted_once=true",
        "assert: restore_job_shared_from_node_b=true",
        "assert: settings_restore_prepared_stage_id_rendered=true",
        "assert: source_instance_remains_usable=true",
        "assert: settings_restore_stage_discarded=true",
        "assert: restore_stage_discard_rejects_untrusted_target_and_missing_job=true",
        "assert: restore_stage_discard_shared_from_node_b=true",
        "assert: restore_stage_discard_idempotent_across_nodes=true",
        "assert: source_instance_remains_usable_after_stage_discard=true",
        "assert: browser_cleanup_complete=true",
        "assert: page_errors=0",
        "assert: request_failures=0",
        "assert: web_release_sha256=",
    )
    missing = [value for value in required_assertions if value not in browser_stdout]
    _require(
        not missing,
        "PG v25 restore-stage discard browser evidence was incomplete; missing="
        + ",".join(missing)
        + "; redacted output: "
        + browser_output[-7000:],
    )
    job_match = re.search(r"assert: pg_v25_restore_job_id=([0-9a-f-]{36})", browser_stdout)
    _require(
        job_match is not None and str(uuid.UUID(job_match.group(1))) == restore_job_id,
        "the restore runner omitted or changed the safe submitted job identity",
    )

    discarded_row = pg_http_world.database_connection.execute(
        "SELECT status,result_code,restore_stage_status,restore_stage_target_cleaned_at,"
        "restore_stage_discard_next_retry_at FROM instance_admin_jobs WHERE job_id=%s",
        (restore_job_id,),
    ).fetchone()
    _require(
        discarded_row is not None
        and discarded_row[0:3] == ("succeeded", "completed", "discarded")
        and discarded_row[3] is not None
        and discarded_row[4] is None,
        "the durable PG ledger must record completed target cleanup and clear retry scheduling",
    )
    _require(
        not stage_dir.exists()
        and not restored_object_path.exists(),
        "discard must remove the isolated stage directory and restored filesystem object",
    )

    target_after_discard = pg_http_world.psycopg.connect(
        pg_http_world.restore_target_url, autocommit=True, connect_timeout=10
    )
    try:
        target_schema_exists = target_after_discard.execute(
            "SELECT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname=%s)",
            (pg_http_world.schema,),
        ).fetchone()[0]
        target_control_schema_exists = target_after_discard.execute(
            "SELECT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='atermius_restore_control')"
        ).fetchone()[0]
        target_database_after_discard = target_after_discard.execute(
            "SELECT current_database()"
        ).fetchone()[0]
    finally:
        target_after_discard.close()
    _require(
        not target_schema_exists
        and not target_control_schema_exists
        and target_database_after_discard == target_database,
        "discard must remove its application schema and binding marker while preserving the target database",
    )

    source_after_discard = pg_http_world.database_connection.execute(
        "SELECT instance_id,generation,signing_public_key,"
        "(SELECT COUNT(*) FROM blob_objects),"
        "(SELECT COUNT(*) FROM sessions WHERE user_id=%s AND revoked_at IS NULL) "
        "FROM instance_meta WHERE id=1",
        (admin_user_id[0],),
    ).fetchone()
    archive_bytes_after_discard = archive_path.read_bytes()
    _require(
        source_after_discard is not None
        and source_after_discard[0:3] == source_before[0:3]
        and source_after_discard[3] == source_before[3]
        and source_after_discard[4] > 0
        and hashlib.sha256(archive_bytes_after_discard).hexdigest() == archive_sha256_before_discard
        and len(archive_bytes_after_discard) == archive_row[3],
        "discard must preserve the live source database, online owner session, and encrypted source archive bytes",
    )

    discard_audit = pg_http_world.database_connection.execute(
        "SELECT actor_user_id,actor_device_id,resource_id,result FROM audit_events "
        "WHERE scope_type='instance' AND resource_type='admin_job' "
        "AND action='admin.restore_stage_discarded'",
    ).fetchall()
    _require(
        admin_user_id is not None
        and len(discard_audit) == 1
        and discard_audit[0][0] == admin_user_id[0]
        and discard_audit[0][1] is not None
        and isinstance(discard_audit[0][2], str)
        and discard_audit[0][2] != restore_job_id
        and len(discard_audit[0][2]) == 64
        and re.fullmatch(r"[0-9a-f]{64}", discard_audit[0][2]) is not None
        and discard_audit[0][3] == "success",
        "stage discard must write one attributed HMAC-only successful audit event",
    )

    # Reuse the same explicitly disposable PG fixture after the Web discard
    # has emptied its target. The HTTP publisher above intentionally leaves a
    # v25 schema in the separate archive source database; remove only that
    # fixture schema so the full worker/activation-fence acceptance can build
    # its own historical archive from the already-migrated live source.
    archive_connection = pg_http_world.psycopg.connect(
        pg_http_world.v25_archive_url, autocommit=True, connect_timeout=10
    )
    try:
        archive_connection.execute(
            pg_http_world.psycopg.sql.SQL("DROP SCHEMA IF EXISTS {} CASCADE").format(
                pg_http_world.psycopg.sql.Identifier(pg_http_world.schema)
            )
        )
    finally:
        archive_connection.close()
    full_restore = subprocess.run(
        [
            "cargo",
            "test",
            "--locked",
            "--manifest-path",
            str(ROOT / "server" / "Cargo.toml"),
            "--lib",
            "backup::tests::postgres_restore_full_encrypted_schema_25_archive",
            "--",
            "--ignored",
            "--exact",
            "--nocapture",
            "--test-threads=1",
        ],
        cwd=ROOT,
        env=publisher_env,
        capture_output=True,
        text=True,
        timeout=900,
        check=False,
    )
    full_restore_output = redact_secrets(
        full_restore.stdout + "\n" + full_restore.stderr,
        *pg_http_world.secrets,
        pg_http_world.v25_archive_url,
        pg_http_world.restore_target_url,
    )
    _require(
        full_restore.returncode == 0
        and "PG-V25-RESTORE-01 passed" in full_restore_output,
        "real PostgreSQL activation/discard-fence acceptance failed; redacted output: "
        + full_restore_output[-7000:],
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_recovery_full_loss_web_acceptance"],
    indirect=True,
    scope="module",
)
def test_pg_http_account_recovery_full_loss_web_acceptance(
    pg_http_world: PgHttpWorld,
) -> None:
    """Run real Web device-loss recovery across the two-node PostgreSQL fixture."""
    world = pg_http_world
    connection = world.database_connection
    proxy_origin = world.runtime_env.get("ATERMIUS_PUBLIC_ORIGIN", "")
    _require(proxy_origin.startswith("http://127.0.0.1:"), "PG Recovery proxy Origin was not configured")
    bootstrap_token = world.bootstrap_token()
    connection.execute(
        "CREATE TABLE pg_test_recovery_challenge_deletions ("
        "challenge_id_hash TEXT NOT NULL,challenge_hash TEXT NOT NULL,user_id TEXT NOT NULL,"
        "recovery_generation BIGINT NOT NULL,consumed_at BIGINT)"
    )
    connection.execute(
        "CREATE FUNCTION pg_test_capture_recovery_challenge_delete() RETURNS trigger "
        "LANGUAGE plpgsql AS $$ BEGIN INSERT INTO pg_test_recovery_challenge_deletions "
        "(challenge_id_hash,challenge_hash,user_id,recovery_generation,consumed_at) "
        "VALUES(OLD.challenge_id_hash,OLD.challenge_hash,OLD.user_id,OLD.recovery_generation,OLD.consumed_at); "
        "RETURN OLD; END $$"
    )
    connection.execute(
        "CREATE TRIGGER pg_test_capture_recovery_challenge_delete BEFORE DELETE "
        "ON account_recovery_challenges FOR EACH ROW "
        "EXECUTE FUNCTION pg_test_capture_recovery_challenge_delete()"
    )
    probe = PgRecoveryWebProbe(world)
    world.remember_secret(probe.token)
    runner_env = {
        key: os.environ[key]
        for key in (
            "PATH",
            "HOME",
            "TMPDIR",
            "PLAYWRIGHT_CHROMIUM_EXECUTABLE",
            "PLAYWRIGHT_BROWSERS_PATH",
        )
        if key in os.environ
    }
    runner_env.update(
        {
            "ATERMIUS_PG_RECOVERY_WEB_BASE_URL": proxy_origin,
            "ATERMIUS_PG_RECOVERY_WEB_NODE_A_URL": world.clients[0].base_url,
            "ATERMIUS_PG_RECOVERY_WEB_NODE_B_URL": world.clients[1].base_url,
            "ATERMIUS_PG_RECOVERY_WEB_PROBE_URL": probe.url,
            "ATERMIUS_PG_RECOVERY_WEB_PROBE_TOKEN": probe.token,
            "ATERMIUS_PG_RECOVERY_WEB_USERNAME": PG_WEB_RECOVERY_USERNAME,
            "ATERMIUS_PG_RECOVERY_WEB_BOOTSTRAP_TOKEN": bootstrap_token,
        }
    )
    runner = None
    try:
        runner = subprocess.Popen(
            [
                "npm",
                "run",
                "test:pg-recovery:full-loss",
                "--prefix",
                str(ROOT / "integration" / "web"),
            ],
            cwd=ROOT,
            env=runner_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            start_new_session=True,
        )
        try:
            output, _ = runner.communicate(timeout=360)
        except subprocess.TimeoutExpired:
            runner.terminate()
            try:
                output, _ = runner.communicate(timeout=12)
            except subprocess.TimeoutExpired:
                try:
                    os.killpg(runner.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                output, _ = runner.communicate(timeout=5)
            pytest.fail(
                "PostgreSQL Recovery Chromium runner timed out; redacted output: "
                + redact_secrets(output or "", *world.secrets)[-5000:],
                pytrace=False,
            )
    except OSError:
        pytest.fail("PostgreSQL Recovery Chromium runner could not start", pytrace=False)
    finally:
        probe.close()

    output = output or ""
    redacted_output = redact_secrets(output, *world.secrets)[-7000:]
    _require(
        runner is not None and runner.returncode == 0,
        "PostgreSQL Recovery Chromium runner failed; redacted output: " + redacted_output,
    )
    required_assertions = (
        "WEB-RECOVERY-FULL-LOSS-01 passed",
        "assert: pg_recovery_complete_node=B",
        "assert: pg_replacement_login_node=A",
        "assert: pg_preserved_host_read_on_node_a=true",
        "assert: pg_plaintext_secret_match=false",
        "assert: pg_challenge_consumed_immediately=true",
        "assert: pg_old_session_statuses=[401,401]",
        "assert: recovered_required_vault_epoch_contexts=3",
        "assert: recovered_distinct_vault_count=2",
        "assert: recovered_shared_historical_and_current_epochs=true",
        "assert: signed_full_recovery_mfa_cleared=true",
        "assert: replacement_login_mfa_required=false",
        "assert: browser_persistence_secret_match=false",
        "assert: flutter_page_errors=0",
    )
    _require(
        all(assertion in output for assertion in required_assertions),
        "PostgreSQL Recovery browser assertions were incomplete; redacted output: "
        + redacted_output,
    )

    web_bundle = ROOT / "apps" / "client" / "build" / "web" / "main.dart.js"
    web_bundle_hash = hashlib.sha256(web_bundle.read_bytes()).hexdigest()
    _require(
        web_bundle_hash == "7f95eb3045577acbb88a4e06ccc9f199ee6c92153bca18ab056247b6bd5107fa",
        "PostgreSQL Recovery browser acceptance did not use the recorded current Web Release bundle",
    )

    challenge_id_match = re.search(r"assert: pg_recovery_challenge_id_hash=([0-9a-f]{64})", output)
    challenge_match = re.search(r"assert: pg_recovery_challenge_hash=([0-9a-f]{64})", output)
    recovered_device_match = re.search(r"assert: pg_recovery_device_id=([0-9a-f-]{36})", output)
    _require(
        challenge_id_match is not None and challenge_match is not None and recovered_device_match is not None,
        "Recovery browser runner omitted hash-only challenge or replacement device evidence",
    )
    challenge_id_hash = challenge_id_match.group(1)
    challenge_hash = challenge_match.group(1)
    recovered_device_id = recovered_device_match.group(1)
    context_line = re.search(r"assert: recovery_context_tuples=(\[[^\n]*\])", output)
    _require(context_line is not None, "Recovery browser runner omitted its exact signed context tuples")
    recovery_contexts = json.loads(context_line.group(1))
    _require(
        len(recovery_contexts) == 3
        and all(
            isinstance(item, dict)
            and set(item) == {"vault_id", "key_epoch", "membership_version"}
            and re.fullmatch(r"[0-9a-f-]{36}", str(item["vault_id"]))
            and isinstance(item["key_epoch"], int)
            and isinstance(item["membership_version"], int)
            for item in recovery_contexts
        ),
        "Recovery browser did not expose three fixed, valid Vault/key contexts",
    )
    user_row = connection.execute(
        "SELECT user_id FROM users WHERE username=%s", (PG_WEB_RECOVERY_USERNAME,)
    ).fetchone()
    _require(user_row is not None, "the Web-created Recovery account is missing from PostgreSQL")
    user_id = user_row[0]

    recovery = connection.execute(
        "SELECT r.recovery_generation,g.last_generation FROM account_recovery r "
        "JOIN account_recovery_generation g USING(user_id) WHERE r.user_id=%s",
        (user_id,),
    ).fetchone()
    _require(recovery == (2, 2), "Recovery generation did not advance monotonically from one to two")
    recovery_boxes = connection.execute(
        "SELECT recovery_generation,vault_id,key_epoch,envelope FROM account_recovery_key_envelopes "
        "WHERE user_id=%s ORDER BY recovery_generation,vault_id,key_epoch",
        (user_id,),
    ).fetchall()
    recovery_box_pairs = sorted((str(row[1]), int(row[2])) for row in recovery_boxes)
    expected_recovery_pairs = sorted(
        (str(item["vault_id"]), int(item["key_epoch"])) for item in recovery_contexts
    )
    _require(
        len(recovery_boxes) == 3
        and all(row[0] == 2 for row in recovery_boxes)
        and recovery_box_pairs == expected_recovery_pairs,
        "Recovery did not replace the generation-one boxes with exactly three expected Vault/key epoch boxes",
    )
    descriptor = connection.execute(
        "SELECT recovery_public_signing_key,recovery_public_encryption_key,recovery_envelope,"
        "recovery_identity_envelope FROM account_recovery WHERE user_id=%s",
        (user_id,),
    ).fetchone()
    _require(descriptor is not None, "the generation-two Recovery descriptor is missing")
    recovery_public_keys_are_32_bytes = all(
        len(unb64url(value)) == 32 for value in descriptor[:2]
    )
    encrypted_identity_packages_are_opaque = True
    for value in descriptor[2:]:
        package = json.loads(value)
        encrypted_identity_packages_are_opaque &= (
            set(package) == {"version", "suite", "nonce", "ciphertext"}
            and package.get("version") == 1
            and package.get("suite") == "xchacha20-poly1305-ietf"
            and len(unb64url(package.get("nonce", ""))) == 24
            and len(unb64url(package.get("ciphertext", ""))) >= 16
        )
    recovery_keybox_payloads = [json.loads(row[3]) for row in recovery_boxes]
    _require(
        recovery_public_keys_are_32_bytes
        and encrypted_identity_packages_are_opaque
        and all(
            set(payload) == {"version", "suite", "ciphertext"}
            and payload.get("version") == 1
            and payload.get("suite") == "crypto_box_seal"
            and len(unb64url(payload.get("ciphertext", ""))) >= 16
            for payload in recovery_keybox_payloads
        ),
        "PostgreSQL Recovery identity and Vault key rows must contain public keys and opaque ciphertext only",
    )
    _require(
        connection.execute("SELECT count(*) FROM auth_mfa WHERE user_id=%s", (user_id,)).fetchone()[0] == 0
        and connection.execute(
            "SELECT count(*) FROM auth_mfa_recovery_codes WHERE user_id=%s", (user_id,)
        ).fetchone()[0] == 0
        and connection.execute(
            "SELECT count(*) FROM auth_mfa_login_challenges WHERE user_id=%s", (user_id,)
        ).fetchone()[0] == 0,
        "full Recovery did not clear MFA state, one-time codes and MFA challenges",
    )

    challenge_rows = connection.execute(
        "SELECT user_id,recovery_generation,challenge_id_hash,challenge_hash,consumed_at "
        "FROM account_recovery_challenges WHERE user_id=%s UNION ALL "
        "SELECT user_id,recovery_generation,challenge_id_hash,challenge_hash,consumed_at "
        "FROM pg_test_recovery_challenge_deletions WHERE user_id=%s",
        (user_id, user_id),
    ).fetchall()
    matching_challenge = [
        row for row in challenge_rows if row[2] == challenge_id_hash and row[3] == challenge_hash
    ]
    _require(
        len(challenge_rows) == 1 and len(matching_challenge) == 1
        and matching_challenge[0][1] == 1 and matching_challenge[0][4] is not None,
        "Recovery must consume exactly one challenge, retaining only its hashes before or after maintenance pruning",
    )
    recovery_receipts = connection.execute(
        "SELECT operation_id,request_digest,response_json FROM account_recovery_receipts WHERE user_id=%s",
        (user_id,),
    ).fetchall()
    parsed_recovery_receipts = [json.loads(row[2]) for row in recovery_receipts]
    completion_receipts = [
        (row, body) for row, body in zip(recovery_receipts, parsed_recovery_receipts)
        if body.get("status") == "recovered"
    ]
    setup_receipts = [body for body in parsed_recovery_receipts if body.get("recovery_status") == "current"]
    _require(
        len(recovery_receipts) == 2
        and len(completion_receipts) == 1
        and len(setup_receipts) == 1
        and all(re.fullmatch(r"[0-9a-f]{64}", row[1]) is not None for row in recovery_receipts),
        "Recovery setup and full completion must each create one SHA-256 idempotency receipt",
    )
    receipt_response = completion_receipts[0][1]
    _require(
        receipt_response.get("status") == "recovered"
        and receipt_response.get("recovery_generation") == 2
        and receipt_response.get("device_id") == recovered_device_id,
        "the durable Recovery receipt does not describe the successful Web completion",
    )
    recovery_audits = connection.execute(
        "SELECT scope_type,scope_id,actor_user_id,actor_device_id,action,result FROM audit_events "
        "WHERE actor_user_id=%s AND action='auth.account_recovered'",
        (user_id,),
    ).fetchall()
    _require(
        len(recovery_audits) == 1
        and recovery_audits[0][0] == "account"
        and re.fullmatch(r"[0-9a-f]{64}", recovery_audits[0][1]) is not None
        and recovery_audits[0][1] != user_id
        and recovery_audits[0][2] == user_id
        and recovery_audits[0][3] == recovered_device_id
        and recovery_audits[0][4:] == ("auth.account_recovered", "success"),
        "full Recovery must write exactly one attributable account audit event",
    )

    device_rows = connection.execute(
        "SELECT d.device_id,d.status,count(s.session_id) FILTER (WHERE s.revoked_at IS NULL) "
        "FROM devices d LEFT JOIN sessions s ON s.device_id=d.device_id AND s.user_id=d.user_id "
        "WHERE d.user_id=%s GROUP BY d.device_id,d.status ORDER BY d.device_id",
        (user_id,),
    ).fetchall()
    _require(
        len(device_rows) == 2
        and sum(1 for row in device_rows if row[1] == "active") == 1
        and sum(1 for row in device_rows if row[1] == "revoked") == 1
        and any(row[0] == recovered_device_id and row[1] == "active" for row in device_rows)
        and all(row[2] == 0 for row in device_rows if row[1] == "revoked")
        and sum(row[2] for row in device_rows) == 1,
        "Recovery must revoke the lost device and all its sessions while replacement login creates one live session",
    )

    owner_vaults = connection.execute(
        "SELECT v.vault_id,v.active_epoch,v.membership_version FROM vaults v "
        "JOIN vault_members vm ON vm.vault_id=v.vault_id "
        "WHERE vm.user_id=%s AND vm.role='owner' AND vm.state='active' "
        "AND v.state='active' ORDER BY v.created_at,v.vault_id",
        (user_id,),
    ).fetchall()
    _require(len(owner_vaults) == 2, "the synthetic Web account must retain its personal and shared owner Vaults")
    vault_ids = [row[0] for row in owner_vaults]
    context_counts: dict[str, int] = {}
    for item in recovery_contexts:
        context_counts[str(item["vault_id"])] = context_counts.get(str(item["vault_id"]), 0) + 1
    personal_vault_ids = [vault_id for vault_id, count in context_counts.items() if count == 1]
    shared_vault_ids = [vault_id for vault_id, count in context_counts.items() if count == 2]
    _require(
        set(context_counts) == set(vault_ids)
        and len(personal_vault_ids) == len(shared_vault_ids) == 1,
        "the signed Recovery context set must contain one personal and two shared epochs",
    )
    personal_vault_id = personal_vault_ids[0]
    shared_vault_id = shared_vault_ids[0]
    current_vault_metadata = {row[0]: (int(row[1]), int(row[2])) for row in owner_vaults}
    _require(
        current_vault_metadata[personal_vault_id][0] == 1
        and current_vault_metadata[shared_vault_id][0] == 2,
        "the PG fixture must retain personal epoch 1 and rotated shared epoch 2",
    )
    shared_role_rows = connection.execute(
        "SELECT role,state,count(*) FROM vault_members WHERE vault_id=%s "
        "GROUP BY role,state ORDER BY role,state",
        (shared_vault_id,),
    ).fetchall()
    personal_role_rows = connection.execute(
        "SELECT role,state,count(*) FROM vault_members WHERE vault_id=%s "
        "GROUP BY role,state ORDER BY role,state",
        (personal_vault_id,),
    ).fetchall()
    _require(
        personal_role_rows == [("owner", "active", 1)]
        and shared_role_rows == [("owner", "active", 1), ("viewer", "active", 1)],
        "the PG Recovery fixture must preserve one personal Owner and one shared Owner/Viewer membership set",
    )

    all_vault_versions = connection.execute(
        "SELECT vault_id,record_id,revision_id,digest,envelope,commit_seq,operation "
        "FROM record_versions WHERE vault_id=ANY(%s) ORDER BY vault_id,commit_seq",
        (vault_ids,),
    ).fetchall()
    all_vault_heads = connection.execute(
        "SELECT vault_id,record_id,revision_id,deleted,commit_seq FROM record_heads "
        "WHERE vault_id=ANY(%s)",
        (vault_ids,),
    ).fetchall()
    all_vault_events = connection.execute(
        "SELECT vault_id,commit_seq,event_type,record_id,revision_id,envelope "
        "FROM change_events WHERE vault_id=ANY(%s) ORDER BY vault_id,commit_seq",
        (vault_ids,),
    ).fetchall()
    all_vault_receipts = connection.execute(
        "SELECT vault_id,record_id,revision_id,commit_seq FROM op_receipts WHERE vault_id=ANY(%s)",
        (vault_ids,),
    ).fetchall()
    _require(
        len(all_vault_versions) == len(all_vault_heads) == len(all_vault_events)
        == len(all_vault_receipts) == 3,
        "personal and shared Vault ledgers must contain exactly three Host revisions and matching heads/events/receipts",
    )
    head_by_revision = {(row[0], row[1], row[2]): row for row in all_vault_heads}
    event_by_revision = {(row[0], row[3], row[4]): row for row in all_vault_events}
    receipt_by_revision = {(row[0], row[1], row[2]): row for row in all_vault_receipts}
    for version in all_vault_versions:
        key = (version[0], version[1], version[2])
        head = head_by_revision.get(key)
        event = event_by_revision.get(key)
        receipt = receipt_by_revision.get(key)
        _require(
            head is not None and event is not None and receipt is not None
            and version[5] == head[4] == event[1] == receipt[3]
            and head[3] is False
            and event[5] == version[4]
            and version[6] == "create"
            and re.fullmatch(r"[0-9a-f]{64}", version[3]) is not None,
            "a Web-created Host revision must remain one unchanged opaque revision/head/event/receipt",
        )
    version_counts = {
        vault_id: sum(1 for row in all_vault_versions if row[0] == vault_id)
        for vault_id in vault_ids
    }
    _require(
        version_counts == {personal_vault_id: 1, shared_vault_id: 2},
        "personal and shared PG Vaults must retain the expected one/two Host revision split",
    )
    shared_headers = []
    for version in all_vault_versions:
        try:
            header = json.loads(version[4]).get("header", {})
        except (TypeError, json.JSONDecodeError):
            header = {}
        _require(isinstance(header, dict), "PG Host envelope omitted its clear signed header")
        if version[0] == shared_vault_id:
            shared_headers.append((int(header.get("key_epoch", 0)), int(header.get("membership_version", 0))))
    shared_contexts = sorted(
        (int(item["key_epoch"]), int(item["membership_version"]))
        for item in recovery_contexts if str(item["vault_id"]) == shared_vault_id
    )
    historical_shared_headers = [item for item in shared_headers if item[0] == 1]
    current_shared_headers = [item for item in shared_headers if item[0] == 2]
    _require(
        len(historical_shared_headers) == 1 and len(current_shared_headers) == 1
        and historical_shared_headers[0][1] < shared_contexts[0][1]
        and current_shared_headers[0] == shared_contexts[1]
        and shared_contexts[0][0] == 1 and shared_contexts[1][0] == 2
        and shared_contexts[1][1] == current_vault_metadata[shared_vault_id][1],
        "shared PG Host headers or historical/current Recovery membership contexts do not match the rotated ledger",
    )
    personal_header = next(
        json.loads(row[4]).get("header", {}) for row in all_vault_versions
        if row[0] == personal_vault_id
    )
    _require(
        int(personal_header.get("key_epoch", 0)) == 1
        and int(personal_header.get("membership_version", 0)) == current_vault_metadata[personal_vault_id][1],
        "personal PG Host header must remain bound to its current epoch and membership",
    )

    recovered_keyboxes = connection.execute(
        "SELECT vault_id,epoch,membership_version,envelope FROM vault_key_envelopes "
        "WHERE recipient_user_id=%s AND recipient_device_id=%s ORDER BY vault_id,epoch",
        (user_id, recovered_device_id),
    ).fetchall()
    recovered_device_contexts = [
        {"vault_id": row[0], "key_epoch": int(row[1]), "membership_version": int(row[2])}
        for row in recovered_keyboxes
    ]
    expected_device_contexts = sorted(
        recovery_contexts, key=lambda item: (str(item["vault_id"]), int(item["key_epoch"]))
    )
    recovered_envelopes_are_opaque = True
    for row in recovered_keyboxes:
        payload = row[3] if isinstance(row[3], dict) else json.loads(row[3])
        recovered_envelopes_are_opaque &= (
            set(payload) == {"version", "suite", "ciphertext"}
            and payload.get("version") == 1
            and payload.get("suite") == "crypto_box_seal"
            and len(unb64url(payload.get("ciphertext", ""))) >= 16
        )
    _require(
        recovered_device_contexts == expected_device_contexts
        and recovered_envelopes_are_opaque,
        "replacement Web device must receive exactly the three signed key contexts as opaque envelopes",
    )

    world.assert_secrets_not_in_local_files()
    _require(
        (world.root / "shared" / "mfa-encryption.key").stat().st_mode & 0o777 == 0o600,
        "PG MFA encryption key file must be owner-only",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_schedule"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_backup_schedule_is_shared_durable_and_admin_only(
    pg_http_world: PgHttpWorld, tmp_path: Path
) -> None:
    _assert_postgres_v25_schema_upgrades_to_v38(pg_http_world)
    tenant = pg_http_world.seed_tenant(tmp_path / "pg-backup-schedule-admin")
    admin = tenant.actors[0]
    pg_http_world.database_connection.execute(
        "UPDATE users SET username=%s WHERE user_id=%s",
        (PG_ADMIN_BACKUP_SCHEDULE_USERNAME, admin.user_id),
    )
    outsider = pg_http_world.seed_tenant(tmp_path / "pg-backup-schedule-outsider").actors[0]
    first = pg_http_world.clients[0]
    second = pg_http_world.clients[1]

    missing = first.request("GET", "/api/v1/admin/backup-schedule")
    missing_put = first.request(
        "PUT", "/api/v1/admin/backup-schedule", json_body={"interval_hours": None}
    )
    denied = second.request(
        "GET", "/api/v1/admin/backup-schedule", token=outsider.access_token
    )
    denied_put = second.request(
        "PUT",
        "/api/v1/admin/backup-schedule",
        token=outsider.access_token,
        json_body={"interval_hours": 1},
    )
    _require(
        missing.status == 401
        and missing_put.status == 401
        and denied.status == 403
        and denied_put.status == 403
        and _error_code(denied) == _error_code(denied_put) == "INSTANCE_ADMIN_REQUIRED",
        "PostgreSQL backup schedule reads and writes must require an allowlisted administrator",
    )

    for method, path in (
        ("POST", "/api/v1/admin/backup-schedule"),
        ("GET", "/api/v1/admin/backup-schedule/"),
        ("PUT", "/api/v1/admin/backup-schedule/"),
    ):
        rejected = first.request(
            method,
            path,
            token=admin.access_token,
            json_body={"interval_hours": 1} if method == "POST" or method == "PUT" else None,
        )
        _require(
            rejected.status == 503 and _error_code(rejected) == "PG_SYNC_SCOPE_LIMITED",
            "PostgreSQL schedule routes must accept only exact GET and PUT paths",
        )

    initial = first.request("GET", "/api/v1/admin/backup-schedule", token=admin.access_token)
    initial_body = initial.json() if initial.status == 200 else {}
    _require(
        initial.status == 200
        and set(initial_body)
        == {"operation", "backup_configured", "interval_hours", "next_run_at", "last_run"}
        and initial_body.get("operation") == "backup_schedule"
        and initial_body.get("interval_hours") is None
        and initial_body.get("next_run_at") is None
        and initial_body.get("last_run") is None,
        "the PostgreSQL schedule endpoint must return the existing bounded schedule DTO",
    )
    jobs = first.request("GET", "/api/v1/admin/jobs?limit=10&offset=0", token=admin.access_token)
    supported = jobs.json().get("supported_actions", []) if jobs.status == 200 else []
    _require(
        jobs.status == 200 and "backup_schedule" in supported,
        "PostgreSQL must advertise schedule management once shared schema readiness passes",
    )

    invalid_bodies = (
        {},
        {"interval_hours": 0},
        {"interval_hours": 721},
        {"interval_hours": 1.5},
        {"interval_hours": "1"},
        {"interval_hours": True},
        {"interval_hours": 1, "extra": False},
    )
    for body in invalid_bodies:
        invalid = first.request(
            "PUT", "/api/v1/admin/backup-schedule", token=admin.access_token, json_body=body
        )
        _require(
            invalid.status == 400
            and _error_code(invalid)
            in {"INVALID_BACKUP_SCHEDULE_REQUEST", "INVALID_BACKUP_INTERVAL"},
            "PostgreSQL schedule updates must enforce the exact bounded request contract",
        )

    if "backup" not in supported:
        unavailable = first.request(
            "PUT",
            "/api/v1/admin/backup-schedule",
            token=admin.access_token,
            json_body={"interval_hours": 1},
        )
        _require(
            unavailable.status == 503
            and _error_code(unavailable) == "BACKUP_NOT_CONFIGURED",
            "schedule management must remain visible while enabling fails closed without a ready backup worker",
        )
        return

    database = pg_http_world.database_connection
    reject_function = f"pg_test_reject_backup_schedule_audit_{uuid.uuid4().hex}"
    reject_trigger = f"pg_test_reject_backup_schedule_audit_{uuid.uuid4().hex}"
    database.execute(
        pg_http_world.psycopg.sql.SQL(
            "CREATE FUNCTION {}() RETURNS trigger LANGUAGE plpgsql AS $$ \
             BEGIN RAISE EXCEPTION 'injected schedule audit failure'; END $$"
        ).format(pg_http_world.psycopg.sql.Identifier(reject_function))
    )
    database.execute(
        pg_http_world.psycopg.sql.SQL(
            "CREATE TRIGGER {} BEFORE INSERT ON audit_events FOR EACH ROW \
             WHEN (NEW.action='admin.backup_schedule_updated') EXECUTE FUNCTION {}()"
        ).format(
            pg_http_world.psycopg.sql.Identifier(reject_trigger),
            pg_http_world.psycopg.sql.Identifier(reject_function),
        )
    )
    rolled_back = first.request(
        "PUT", "/api/v1/admin/backup-schedule", token=admin.access_token, json_body={"interval_hours": 2}
    )
    after_rollback = database.execute(
        "SELECT interval_hours,next_run_at FROM instance_backup_schedule WHERE schedule_id=1"
    ).fetchone()
    database.execute(
        pg_http_world.psycopg.sql.SQL("DROP TRIGGER {} ON audit_events").format(
            pg_http_world.psycopg.sql.Identifier(reject_trigger)
        )
    )
    database.execute(
        pg_http_world.psycopg.sql.SQL("DROP FUNCTION {}()").format(
            pg_http_world.psycopg.sql.Identifier(reject_function)
        )
    )
    _require(
        rolled_back.status == 500 and after_rollback == (None, None),
        "a schedule audit failure must roll back the cadence update in the same PostgreSQL transaction",
    )

    enabled = first.request(
        "PUT", "/api/v1/admin/backup-schedule", token=admin.access_token, json_body={"interval_hours": 1}
    )
    enabled_body = enabled.json() if enabled.status == 200 else {}
    _require(
        enabled.status == 200
        and enabled_body.get("backup_configured") is True
        and enabled_body.get("interval_hours") == 1
        and isinstance(enabled_body.get("next_run_at"), str),
        "a configured PostgreSQL backup schedule must persist a one-hour interval",
    )
    same_interval = second.request(
        "PUT", "/api/v1/admin/backup-schedule", token=admin.access_token, json_body={"interval_hours": 1}
    )
    _require(
        same_interval.status == 200
        and same_interval.json().get("next_run_at") == enabled_body.get("next_run_at"),
        "idempotently saving the current interval must preserve its due time across nodes",
    )

    held_job = str(uuid.uuid4())
    database.execute("BEGIN")
    database.execute(
        "UPDATE instance_backup_schedule SET next_run_at=clock_timestamp()-INTERVAL '5 minutes' WHERE schedule_id=1"
    )
    due_slot = database.execute(
        "SELECT next_run_at FROM instance_backup_schedule WHERE schedule_id=1"
    ).fetchone()[0]
    database.execute(
        "INSERT INTO instance_admin_jobs( \
             job_id,request_id,requested_by_user_id,requested_by_device_id,action,status, \
             requested_at,started_at,worker_token,lease_expires_at \
         ) VALUES (%s,%s,%s,%s,'maintenance','running',clock_timestamp(), \
                   clock_timestamp(),'schedule-contention-hold',clock_timestamp()+INTERVAL '1 hour')",
        (held_job, str(uuid.uuid4()), admin.user_id, admin.device_id),
    )
    database.execute("COMMIT")
    pg_http_world.restart_node(0)
    first = pg_http_world.clients[0]
    time.sleep(0.3)
    unchanged_slot = database.execute(
        "SELECT next_run_at FROM instance_backup_schedule WHERE schedule_id=1"
    ).fetchone()[0]
    scheduled_before_release = database.execute(
        "SELECT COUNT(*) FROM instance_admin_jobs WHERE request_origin='scheduled' AND scheduled_for=%s",
        (due_slot,),
    ).fetchone()[0]
    _require(
        unchanged_slot == due_slot and scheduled_before_release == 0,
        "a due schedule slot must remain unconsumed while maintenance owns the shared admission fence",
    )
    database.execute("DELETE FROM instance_admin_jobs WHERE job_id=%s", (held_job,))
    pg_http_world.restart_node(1)
    second = pg_http_world.clients[1]

    scheduled_run = None
    deadline = time.monotonic() + 60
    while time.monotonic() < deadline:
        response = second.request(
            "GET", "/api/v1/admin/backup-schedule", token=admin.access_token, timeout=5
        )
        body = response.json() if response.status == 200 else {}
        candidate = body.get("last_run") if isinstance(body, dict) else None
        if isinstance(candidate, dict) and candidate.get("status") in {
            "succeeded",
            "failed",
            "interrupted",
        }:
            scheduled_run = candidate
            break
        time.sleep(0.2)
    _require(
        scheduled_run is not None and scheduled_run.get("status") == "succeeded",
        "one PostgreSQL node must claim the due slot and create a real encrypted scheduled archive; "
        f"redacted logs: {pg_http_world.redacted_log_tail()}",
    )
    due_iso = due_slot.isoformat(timespec="milliseconds").replace("+00:00", "Z")
    _require(
        scheduled_run.get("scheduled_for") == due_iso
        and scheduled_run.get("result_code") == "completed"
        and scheduled_run.get("migration_version") == 38
        and isinstance(scheduled_run.get("archive_bytes"), int)
        and scheduled_run["archive_bytes"] > 0
        and set(scheduled_run)
        == {
            "run_id",
            "scheduled_for",
            "started_at",
            "finished_at",
            "status",
            "result_code",
            "archive_bytes",
            "migration_version",
        },
        "the shared schedule DTO must publish only safe, durable completion metadata",
    )
    row = database.execute(
        "SELECT job_id,requested_by_user_id,requested_by_device_id,scheduled_for,archive_timestamp,archive_bytes,status \
         FROM instance_admin_jobs WHERE request_origin='scheduled' AND scheduled_for=%s",
        (due_slot,),
    ).fetchall()
    _require(
        len(row) == 1
        and row[0][0] == scheduled_run["run_id"]
        and row[0][1] is None
        and row[0][2] is None
        and row[0][3] == due_slot
        and row[0][4] is not None
        and row[0][5] == scheduled_run["archive_bytes"]
        and row[0][6] == "succeeded",
        "the durable scheduled slot must have exactly one system-origin job with no invented human actor",
    )
    archive_dir = pg_http_world.root / "shared" / "backup-archives"
    archive_paths = list(archive_dir.glob(f"atermius-backup-*-{scheduled_run['run_id']}.atb"))
    _require(
        len(archive_paths) == 1 and archive_paths[0].stat().st_size == scheduled_run["archive_bytes"],
        "the scheduled PG worker must publish exactly one encrypted archive in the shared private directory",
    )
    replication_row = database.execute(
        "SELECT origin,status,archive_bytes,archive_sha256,attempt_count,next_attempt_at, \
                last_attempt_at,failure_category,multipart_upload_id \
         FROM instance_backup_replications WHERE archive_id=%s",
        (scheduled_run["run_id"],),
    ).fetchone()
    job_digest = database.execute(
        "SELECT archive_sha256 FROM instance_admin_jobs WHERE job_id=%s",
        (scheduled_run["run_id"],),
    ).fetchone()
    _require(
        replication_row is not None
        and job_digest is not None
        and replication_row[:3] == ("scheduled", "pending", scheduled_run["archive_bytes"])
        and replication_row[3] == job_digest[0]
        and replication_row[4] == 0
        and replication_row[5] is not None
        and replication_row[6:] == (None, None, None),
        "the scheduled PostgreSQL archive must publish matching shared outbox metadata without attempting a transfer",
    )
    sources_response = first.request(
        "GET", "/api/v1/admin/restore-sources?limit=10&offset=0", token=admin.access_token
    )
    sources_body = sources_response.json() if sources_response.status == 200 else {}
    source = next(
        (item for item in sources_body.get("sources", []) if item.get("archive_id") == scheduled_run["run_id"]),
        None,
    )
    _require(
        sources_response.status == 200
        and source is not None
        and source.get("origin") == "scheduled"
        and source.get("source") == "local"
        and source.get("archive_bytes") == scheduled_run["archive_bytes"],
        "the other PostgreSQL node must expose the scheduled encrypted archive as a restore source",
    )

    disabled = second.request(
        "PUT", "/api/v1/admin/backup-schedule", token=admin.access_token, json_body={"interval_hours": None}
    )
    _require(
        disabled.status == 200
        and disabled.json().get("interval_hours") is None
        and disabled.json().get("next_run_at") is None
        and disabled.json().get("last_run", {}).get("run_id") == scheduled_run["run_id"],
        "disabling PostgreSQL scheduling must preserve the last durable scheduled-run result",
    )

    expired_job = str(uuid.uuid4())
    database.execute(
        "INSERT INTO instance_admin_jobs( \
             job_id,request_id,requested_by_user_id,requested_by_device_id,action,archive_id, \
             request_origin,scheduled_for,status,started_at,worker_token,lease_expires_at \
         ) VALUES (%s,%s,NULL,NULL,'backup',%s,'scheduled',clock_timestamp()-INTERVAL '1 minute', \
                   'running',clock_timestamp()-INTERVAL '10 minutes','expired-schedule-worker', \
                   clock_timestamp()-INTERVAL '1 second')",
        (expired_job, str(uuid.uuid4()), expired_job),
    )
    pg_http_world.restart_node(0)
    first = pg_http_world.clients[0]
    interrupted = None
    deadline = time.monotonic() + 10
    while time.monotonic() < deadline:
        response = first.request(
            "GET", "/api/v1/admin/backup-schedule", token=admin.access_token, timeout=5
        )
        body = response.json() if response.status == 200 else {}
        candidate = body.get("last_run") if isinstance(body, dict) else None
        if (
            isinstance(candidate, dict)
            and candidate.get("run_id") == expired_job
            and candidate.get("status") in {"succeeded", "failed", "interrupted"}
        ):
            interrupted = candidate
            break
        time.sleep(0.1)
    _require(
        interrupted is not None
        and interrupted.get("status") == "interrupted"
        and interrupted.get("result_code") == "interrupted"
        and interrupted.get("archive_bytes") is None
        and interrupted.get("migration_version") is None
        and len(list(archive_dir.glob(f"atermius-backup-*-{expired_job}.atb"))) == 0,
        "an expired scheduled-job lease must become interrupted and must not replay an archive",
    )

    schedule_audits = database.execute(
        "SELECT action,actor_user_id,actor_device_id,resource_type,resource_id,source,result \
         FROM audit_events WHERE scope_type='instance' AND action='admin.backup_schedule_updated' \
           AND actor_user_id=%s ORDER BY event_id",
        (admin.user_id,),
    ).fetchall()
    _require(
        len(schedule_audits) == 3
        and all(
            item[0] == "admin.backup_schedule_updated"
            and item[1] == admin.user_id
            and item[2] == admin.device_id
            and item[3] == "backup_schedule"
            and item[4] is None
            and item[5] == "api"
            and item[6] == "success"
            for item in schedule_audits
        ),
        "schedule enable, idempotent update, and disable audits must preserve the real admin/device and fixed resource",
    )
    system_audits = database.execute(
        "SELECT action,actor_user_id,actor_device_id,source,result FROM audit_events \
         WHERE scope_type='instance' AND resource_type='admin_job' \
           AND action IN ('admin.backup_requested','admin.backup_started','admin.backup_completed','admin.backup_interrupted') \
         ORDER BY event_id"
    ).fetchall()
    scheduled_audits = [item for item in system_audits if item[1] is None]
    _require(
        len(scheduled_audits) == 4
        and [item[0] for item in scheduled_audits]
        == [
            "admin.backup_requested",
            "admin.backup_started",
            "admin.backup_completed",
            "admin.backup_interrupted",
        ]
        and all(item[2] is None and item[3] == "maintenance" for item in scheduled_audits)
        and all(item[4] in {"success", "failure"} for item in scheduled_audits),
        "scheduled job audits must record system source without attributing work to a human administrator",
    )
    response_bundle = json.dumps([initial_body, enabled_body, scheduled_run, sources_body], sort_keys=True)
    _require(
        all(not value or value not in response_bundle for value in pg_http_world.secrets),
        "schedule responses and restore-source catalog must not reveal private PG configuration",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    ["pg_admin_backup_schedule_web"],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_backup_schedule_settings_browser_acceptance(
    pg_http_world: PgHttpWorld,
) -> None:
    """Drive schedule enable/disable through the current Web Settings UI on PG."""
    bootstrap_result = pg_http_world.run_cli_result("bootstrap")
    if bootstrap_result.returncode != 0:
        detail = redact_secrets(
            bootstrap_result.stderr or bootstrap_result.stdout,
            *pg_http_world.secrets,
        )[-1600:]
        pytest.fail(
            "PostgreSQL schedule-browser bootstrap failed; redacted detail: " + detail,
            pytrace=False,
        )
    bootstrap_match = re.search(
        r"one-time setup token[^\n]*:\s*([A-Za-z0-9_-]{43})",
        bootstrap_result.stdout,
    )
    if not bootstrap_match:
        pytest.fail(
            "PostgreSQL schedule-browser bootstrap omitted a valid token",
            pytrace=False,
        )

    bootstrap_token = bootstrap_match.group(1)
    password = f"PgSchedule-{uuid.uuid4().hex}"
    for value in (bootstrap_token, password, PG_WEB_BACKUP_SCHEDULE_USERNAME):
        pg_http_world.remember_secret(value)

    runner_env = pg_http_world.runtime_env.copy()
    runner_env.update(
        {
            "ATERMIUS_PG_BACKUP_SCHEDULE_BASE_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_BACKUP_SCHEDULE_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_BACKUP_SCHEDULE_ADMIN_USERNAME": PG_WEB_BACKUP_SCHEDULE_USERNAME,
            "ATERMIUS_PG_BACKUP_SCHEDULE_ADMIN_PASSWORD": password,
            "ATERMIUS_PG_BACKUP_SCHEDULE_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_HTTP_SERVER_BIN": str(pg_http_world.binary),
        }
    )
    try:
        result = subprocess.run(
            ["npm", "run", "test:pg-backup-schedule", "--prefix", str(ROOT / "integration" / "web")],
            cwd=ROOT,
            env=runner_env,
            capture_output=True,
            text=True,
            timeout=180,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        pytest.fail("PostgreSQL schedule Settings Chromium runner did not complete", pytrace=False)
    output = redact_secrets(result.stdout + "\n" + result.stderr, *pg_http_world.secrets)[-6000:]
    _require(
        result.returncode == 0,
        f"PostgreSQL schedule Settings Chromium runner failed; redacted output: {output}",
    )
    required_assertions = (
        "assert: admin_profile_registered=true",
        "assert: pg_backup_schedule_web_pass=true",
        "assert: schedule_shared_across_postgres_nodes=true",
        "assert: schedule_disable_shared_across_postgres_nodes=true",
        "assert: browser_cleanup_complete=true",
        "assert: page_errors=0",
        "assert: request_failures=0",
        "assert: relay_requests=0",
        "assert: web_release_sha256=",
    )
    missing_assertions = [item for item in required_assertions if item not in result.stdout]
    _require(
        not missing_assertions,
        f"PostgreSQL schedule browser assertions were incomplete; missing={','.join(missing_assertions)}; "
        f"redacted output: {output}",
    )
    schedule_state = pg_http_world.database_connection.execute(
        "SELECT interval_hours,next_run_at FROM instance_backup_schedule WHERE schedule_id=1"
    ).fetchone()
    admin_user_id = pg_http_world.database_connection.execute(
        "SELECT user_id FROM users WHERE username=%s",
        (PG_WEB_BACKUP_SCHEDULE_USERNAME,),
    ).fetchone()
    _require(
        schedule_state == (None, None) and admin_user_id is not None,
        "browser disable must persist as disabled shared PostgreSQL schedule state",
    )
    schedule_audits = pg_http_world.database_connection.execute(
        "SELECT action,actor_user_id,actor_device_id,resource_type,resource_id,source,result "
        "FROM audit_events WHERE scope_type='instance' "
        "AND action='admin.backup_schedule_updated' AND actor_user_id=%s ORDER BY event_id",
        (admin_user_id[0],),
    ).fetchall()
    _require(
        len(schedule_audits) == 2
        and all(
            event[0] == "admin.backup_schedule_updated"
            and event[1] == admin_user_id[0]
            and event[2] is not None
            and event[3] == "backup_schedule"
            and event[4] is None
            and event[5] == "api"
            and event[6] == "success"
            for event in schedule_audits
        ),
        "Web enable/disable must persist exactly two private actor-attributed schedule audit events",
    )


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_RELAY_WEB_ADMIN_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_relay_settings_browser_acceptance(
    pg_http_world: PgHttpWorld,
) -> None:
    """Drive PG instance, group policy, and group membership Settings flows."""
    bootstrap_result = pg_http_world.run_cli_result("bootstrap")
    if bootstrap_result.returncode != 0:
        detail = redact_secrets(
            bootstrap_result.stderr or bootstrap_result.stdout,
            *pg_http_world.secrets,
        )[-1600:]
        pytest.fail(
            "PostgreSQL Relay browser bootstrap failed; redacted detail: " + detail,
            pytrace=False,
        )
    bootstrap_match = re.search(
        r"one-time setup token[^\n]*:\s*([A-Za-z0-9_-]{43})",
        bootstrap_result.stdout,
    )
    if not bootstrap_match:
        pytest.fail(
            "PostgreSQL Relay browser bootstrap omitted a valid token",
            pytrace=False,
        )

    bootstrap_token = bootstrap_match.group(1)
    password = f"PgRelayWeb-{uuid.uuid4().hex}"
    target_password = f"PgRelayTarget-{uuid.uuid4().hex}"
    second_group_name = f"PG Relay Multi {uuid.uuid4().hex[:8]}"
    for value in (
        bootstrap_token,
        password,
        target_password,
        PG_RELAY_WEB_ADMIN_USERNAME,
        PG_RELAY_WEB_TARGET_USERNAME,
    ):
        pg_http_world.remember_secret(value)

    runner_env = pg_http_world.runtime_env.copy()
    runner_env.update(
        {
            "ATERMIUS_PG_ADMIN_RELAY_BASE_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_ADMIN_RELAY_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_ADMIN_RELAY_USERNAME": PG_RELAY_WEB_ADMIN_USERNAME,
            "ATERMIUS_PG_ADMIN_RELAY_PASSWORD": password,
            "ATERMIUS_PG_ADMIN_RELAY_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_ADMIN_RELAY_TARGET_USERNAME": PG_RELAY_WEB_TARGET_USERNAME,
            "ATERMIUS_PG_ADMIN_RELAY_TARGET_PASSWORD": target_password,
            "ATERMIUS_PG_ADMIN_RELAY_SECOND_GROUP_NAME": second_group_name,
        }
    )
    try:
        result = subprocess.run(
            ["npm", "run", "test:pg-admin-relay", "--prefix", str(ROOT / "integration" / "web")],
            cwd=ROOT,
            env=runner_env,
            capture_output=True,
            text=True,
            timeout=300,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        pytest.fail("PostgreSQL Relay Settings Chromium runner did not complete", pytrace=False)
    output = redact_secrets(result.stdout + "\n" + result.stderr, *pg_http_world.secrets)[-7000:]
    _require(
        result.returncode == 0,
        f"PostgreSQL Relay Settings Chromium runner failed; redacted output: {output}",
    )
    required_assertions = (
        "assert: admin_registered_through_pg_web=true",
        "assert: instance_policy_ui_read=true",
        "assert: instance_policy_saved_cross_node=true",
        "assert: group_policy_saved_cross_node=true",
        "assert: target_account_invited=true",
        "assert: target_membership_saved_cross_node=true",
        "assert: group_membership_cas_conflict_kept_draft=true",
        "assert: target_membership_removed_cross_node=true",
        "assert: target_member_in_two_groups_cross_node=true",
        "assert: account_policy_ui_inherited_read=true",
        "assert: account_policy_user_cas_conflict_kept_draft=true",
        "assert: account_policy_ui_save_cross_node=true",
        "assert: multi_group_user_override_effective_preview=true",
        "assert: account_policy_instance_cas_conflict_kept_draft=true",
        "assert: account_policy_reset_cross_node=true",
        "assert: account_policy_override_restored_cross_node=true",
        "assert: group_policy_reset_to_inherit_cross_node=true",
        "assert: group_policy_reset_ticket_allow_deny=true",
        "assert: group_delete_confirmation_reviewed=true",
        "assert: group_deleted_with_member_cross_node=true",
        "assert: group_delete_ticket_allow_deny_revocation=true",
        "assert: browser_secrets_absent=true",
        "assert: page_errors=0",
        "assert: request_failures=0",
        "assert: external_requests=0",
        "assert: browser_cleanup_complete=true",
    )
    _require(
        all(assertion in result.stdout for assertion in required_assertions),
        f"PostgreSQL Relay Settings assertions were incomplete; redacted output: {output}",
    )

    database = pg_http_world.database_connection
    instance_policy = database.execute(
        "SELECT enabled,allow_cidrs,allow_ports,revision FROM instance_relay_policy WHERE policy_id=1"
    ).fetchone()
    groups = database.execute(
        "SELECT g.group_id,g.name,g.revision,p.enabled,p.allow_cidrs,p.allow_ports,p.revision "
        "FROM relay_access_groups g JOIN relay_access_group_relay_policies p USING(group_id) "
        "ORDER BY g.name"
    ).fetchall()
    _require(
        instance_policy is not None
        and instance_policy[0] is True
        and json.loads(instance_policy[1]) == ["10.1.0.0/17"]
        and json.loads(instance_policy[2]) == [22]
        and instance_policy[3] == 2,
        "PG-backed instance policy did not persist the Web and cross-node CAS writes",
    )
    _require(
        len(groups) == 1
        and groups[0][1].startswith("PG Ops ")
        and groups[0][2] == 1
        and groups[0][3] is True
        and json.loads(groups[0][4]) == ["10.1.1.0/24"]
        and json.loads(groups[0][5]) == [22]
        and groups[0][6] == 1
        and database.execute(
            "SELECT COUNT(*) FROM relay_access_groups WHERE name=%s",
            (second_group_name,),
        ).fetchone()[0] == 0
        and database.execute(
            "SELECT COUNT(*) FROM relay_access_group_relay_policies"
        ).fetchone()[0] == 1
        and database.execute(
            "SELECT COUNT(*) FROM relay_access_group_relay_policy_revisions"
        ).fetchone()[0] == 1,
        "PG-backed group deletion did not leave only Group A and its policy/revision rows",
    )
    group = groups[0]
    membership_revision = database.execute(
        "SELECT revision FROM relay_access_group_membership_revisions WHERE group_id=%s",
        (group[0],),
    ).fetchone()
    _require(
        membership_revision is not None and membership_revision[0] == 5
        and database.execute(
            "SELECT COUNT(*) FROM relay_access_group_members WHERE group_id=%s",
            (group[0],),
        ).fetchone()[0] == 1,
        "PG first-group membership did not persist all CAS revisions and final re-add",
    )
    admin_user_id = database.execute(
        "SELECT user_id FROM users WHERE username=%s",
        (PG_RELAY_WEB_ADMIN_USERNAME,),
    ).fetchone()
    _require(admin_user_id is not None, "the Web-registered Relay admin is absent from PG")
    target_user_id = database.execute(
        "SELECT user_id FROM users WHERE username=%s",
        (PG_RELAY_WEB_TARGET_USERNAME,),
    ).fetchone()
    _require(target_user_id is not None, "the invited Relay target is absent from PG")
    _require(
        database.execute(
            "SELECT user_id FROM relay_access_group_members WHERE group_id=%s",
            (group[0],),
        ).fetchone() == (target_user_id[0],)
        and database.execute(
            "SELECT COUNT(*) FROM relay_access_group_members WHERE user_id=%s",
            (target_user_id[0],),
        ).fetchone()[0] == 1
        and database.execute(
            "SELECT COUNT(*) FROM relay_access_group_membership_revisions"
        ).fetchone()[0] == 1,
        "Group B deletion did not cascade its membership while preserving the invited member in Group A",
    )
    explicit_user_policy = database.execute(
        "SELECT enabled,allow_cidrs,allow_ports,revision FROM user_relay_policies "
        "WHERE user_id=%s",
        (target_user_id[0],),
    ).fetchone()
    _require(
        explicit_user_policy is not None
        and explicit_user_policy[0] is True
        and json.loads(explicit_user_policy[1]) == ["10.1.1.0/24"]
        and json.loads(explicit_user_policy[2]) == [22]
        and explicit_user_policy[3] == 4,
        "final PG state did not preserve the explicit user override through Group B deletion",
    )
    user_policy_watermark = database.execute(
        "SELECT revision,updated_at FROM user_relay_policy_revisions WHERE user_id=%s",
        (target_user_id[0],),
    ).fetchone()
    _require(
        user_policy_watermark is not None
        and user_policy_watermark[0] == 4
        and user_policy_watermark[1] is not None,
        "PG user policy reset did not retain the monotonic revision watermark",
    )
    admin_device_id = database.execute(
        "SELECT device_id FROM devices WHERE user_id=%s ORDER BY device_id LIMIT 1",
        (admin_user_id[0],),
    ).fetchone()
    _require(admin_device_id is not None, "the Web Relay admin device is absent from PG")
    user_policy_audit = database.execute(
        "SELECT actor_user_id,actor_device_id,action,resource_type,resource_id,result,source "
        "FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND resource_type='relay_user_policy' ORDER BY event_id",
        (admin_user_id[0],),
    ).fetchall()
    _require(
        len(user_policy_audit) == 4
        and all(
            row[0] == admin_user_id[0]
            and row[1] == admin_device_id[0]
            and row[2] == "admin.relay_policy_updated"
            and re.fullmatch(r"[0-9a-f]{64}", row[4] or "") is not None
            and row[4] != target_user_id[0]
            and row[5] == "success"
            and row[6] == "api"
            for row in user_policy_audit
        ),
        "PG account Relay override, reset, and restoration did not produce four private actor-attributed audit rows",
    )
    membership_audit = database.execute(
        "SELECT actor_user_id,actor_device_id,action,resource_type,resource_id,result,source "
        "FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND action='admin.relay_group_membership_updated' ORDER BY event_id",
        (admin_user_id[0],),
    ).fetchall()
    _require(
        len(membership_audit) == 6
        and all(
            row[0] == admin_user_id[0]
            and row[1] == admin_device_id[0]
            and row[2] == "admin.relay_group_membership_updated"
            and row[3] == "relay_access_group"
            and re.fullmatch(r"[0-9a-f]{64}", row[4] or "") is not None
            and row[4] != group[0]
            and row[5] == "success"
            and row[6] == "api"
            for row in membership_audit
        ),
        "PG group membership writes did not produce six private actor-attributed audit rows",
    )
    serialized_membership_audit = json.dumps(membership_audit, ensure_ascii=False)
    for private_value in (
        group[0],
        group[1],
        second_group_name,
        target_user_id[0],
        PG_RELAY_WEB_TARGET_USERNAME,
    ):
        _require(
            private_value not in serialized_membership_audit,
            "PG group membership audit exposed a group or account identifier",
        )
    serialized_user_audit = json.dumps(user_policy_audit, ensure_ascii=False)
    for private_value in (
        target_user_id[0],
        PG_RELAY_WEB_TARGET_USERNAME,
        "10.1.1.0/24",
        "10.1.0.0/17",
        "10.1.2.0/24",
    ):
        _require(
            private_value not in serialized_user_audit,
            "PG user Relay policy audit exposed a target identifier or policy value",
        )
    group_policy_audit = database.execute(
        "SELECT actor_user_id,actor_device_id,action,resource_type,resource_id,result,source "
        "FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND action IN ('admin.relay_group_policy_updated','admin.relay_group_policy_reset') "
        "ORDER BY event_id",
        (admin_user_id[0],),
    ).fetchall()
    _require(
        [row[2] for row in group_policy_audit]
        == [
            "admin.relay_group_policy_updated",
            "admin.relay_group_policy_updated",
            "admin.relay_group_policy_updated",
            "admin.relay_group_policy_reset",
            "admin.relay_group_policy_updated",
        ]
        and all(
            row[0] == admin_user_id[0]
            and row[1] == admin_device_id[0]
            and row[3] == "relay_access_group"
            and re.fullmatch(r"[0-9a-f]{64}", row[4] or "") is not None
            and row[4] != group[0]
            and row[5] == "success"
            and row[6] == "api"
            for row in group_policy_audit
        ),
        "PG group policy updates and reset did not produce private actor-attributed audit rows",
    )
    group_delete_audit = database.execute(
        "SELECT actor_user_id,actor_device_id,action,resource_type,resource_id,result,source "
        "FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND action='admin.relay_group_deleted' ORDER BY event_id",
        (admin_user_id[0],),
    ).fetchall()
    _require(
        len(group_delete_audit) == 1
        and all(
            row[0] == admin_user_id[0]
            and row[1] == admin_device_id[0]
            and row[2] == "admin.relay_group_deleted"
            and row[3] == "relay_access_group"
            and re.fullmatch(r"[0-9a-f]{64}", row[4] or "") is not None
            and row[4] != group[0]
            and row[5] == "success"
            and row[6] == "api"
            for row in group_delete_audit
        )
        and group_policy_audit[1][4] == group_delete_audit[0][4]
        and group_policy_audit[2][4] == group_delete_audit[0][4]
        and group_policy_audit[3][4] == group_delete_audit[0][4]
        and group_policy_audit[4][4] == group_delete_audit[0][4]
        and group_policy_audit[0][4] != group_delete_audit[0][4],
        "Group B reset and deletion did not share one private HMAC resource audit identity",
    )
    serialized_group_policy_audit = json.dumps(group_policy_audit, ensure_ascii=False)
    for private_value in (
        group[0],
        group[1],
        second_group_name,
        target_user_id[0],
        PG_RELAY_WEB_TARGET_USERNAME,
        "10.1.1.0/24",
        "10.1.0.0/17",
        "10.1.1.128/25",
    ):
        _require(
            private_value not in serialized_group_policy_audit,
            "PG group Relay policy audit exposed a group name, ID, or policy value",
        )
    serialized_group_delete_audit = json.dumps(group_delete_audit, ensure_ascii=False)
    for private_value in (
        group[0],
        group[1],
        second_group_name,
        target_user_id[0],
        PG_RELAY_WEB_TARGET_USERNAME,
        "10.1.1.0/24",
        "10.1.0.0/17",
        "10.1.1.128/25",
    ):
        _require(
            private_value not in serialized_group_delete_audit,
            "PG group deletion audit exposed a group, account, or policy value",
        )
    audit_actions = database.execute(
        "SELECT action FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND action IN ('admin.relay_policy_updated','admin.relay_group_created',"
        "'admin.relay_group_policy_updated','admin.relay_group_policy_reset',"
        "'admin.relay_group_deleted') AND resource_type <> 'relay_user_policy' ORDER BY action",
        (admin_user_id[0],),
    ).fetchall()
    _require(
        [row[0] for row in audit_actions]
        == [
            "admin.relay_group_created",
            "admin.relay_group_created",
            "admin.relay_group_deleted",
            "admin.relay_group_policy_reset",
            "admin.relay_group_policy_updated",
            "admin.relay_group_policy_updated",
            "admin.relay_group_policy_updated",
            "admin.relay_group_policy_updated",
            "admin.relay_policy_updated",
            "admin.relay_policy_updated",
        ],
        "Relay Web Settings writes did not produce the expected group reset and deletion audit events",
    )
    revoked_ticket_match = re.search(
        r"assert: group_delete_revoked_ticket_hash=([0-9a-f]{64})", result.stdout
    )
    consumed_ticket_match = re.search(
        r"assert: group_delete_consumed_ticket_hash=([0-9a-f]{64})", result.stdout
    )
    _require(
        revoked_ticket_match is not None and consumed_ticket_match is not None,
        "browser did not provide the hashed ticket witnesses for group deletion",
    )
    revoked_ticket_row = database.execute(
        "SELECT consumed_at FROM relay_tickets WHERE ticket_hash=%s",
        (revoked_ticket_match.group(1),),
    ).fetchone()
    consumed_ticket_row = database.execute(
        "SELECT consumed_at FROM relay_tickets WHERE ticket_hash=%s",
        (consumed_ticket_match.group(1),),
    ).fetchone()
    _require(
        revoked_ticket_row is None
        and consumed_ticket_row is not None
        and consumed_ticket_row[0] is not None,
        "deleting Group B did not revoke its pending ticket or the post-delete WebSocket ticket was not consumed",
    )
    pending_target_tickets = database.execute(
        "SELECT COUNT(*) FROM relay_tickets WHERE user_id=%s AND consumed_at IS NULL",
        (target_user_id[0],),
    ).fetchone()
    _require(
        pending_target_tickets is not None and pending_target_tickets[0] == 0,
        "Group B deletion left an unused Relay ticket for the invited target",
    )
    pg_http_world.assert_secrets_not_in_local_files()


@pytest.mark.parametrize(
    "pg_http_world",
    [PG_WEB_METRICS_USERNAME],
    indirect=True,
    scope="module",
)
def test_pg_http_admin_metrics_settings_browser_acceptance(
    pg_http_world: PgHttpWorld,
) -> None:
    """Exercise one-time credential create/copy/dismiss/rotate/revoke in Web on PG."""
    bootstrap_token = pg_http_world.bootstrap_token()
    password = f"PgMetrics-{uuid.uuid4().hex}"
    pg_http_world.remember_secret(password)

    runner_env = {
        key: os.environ[key]
        for key in (
            "PATH",
            "HOME",
            "TMPDIR",
            "TMP",
            "TEMP",
            "XDG_CACHE_HOME",
            "CI",
            "PLAYWRIGHT_BROWSERS_PATH",
            "PLAYWRIGHT_CHROMIUM_EXECUTABLE",
        )
        if key in os.environ
    }
    runner_env.update(
        {
            "ATERMIUS_PG_ADMIN_METRICS_BASE_URL": pg_http_world.clients[0].base_url,
            "ATERMIUS_PG_ADMIN_METRICS_NODE_B_URL": pg_http_world.clients[1].base_url,
            "ATERMIUS_PG_ADMIN_METRICS_USERNAME": PG_WEB_METRICS_USERNAME,
            "ATERMIUS_PG_ADMIN_METRICS_PASSWORD": password,
            "ATERMIUS_PG_ADMIN_METRICS_BOOTSTRAP_TOKEN": bootstrap_token,
            "ATERMIUS_PG_HTTP_SERVER_BIN": str(pg_http_world.binary),
        }
    )
    try:
        result = subprocess.run(
            ["npm", "run", "test:pg-admin-metrics", "--prefix", str(ROOT / "integration" / "web")],
            cwd=ROOT,
            env=runner_env,
            capture_output=True,
            text=True,
            timeout=180,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        pytest.fail("PostgreSQL metrics Settings Chromium runner did not complete", pytrace=False)
    output = redact_secrets(result.stdout + "\n" + result.stderr, *pg_http_world.secrets)[-5000:]
    _require(
        result.returncode == 0,
        f"PostgreSQL metrics Settings Chromium runner failed; redacted output: {output}",
    )
    required_assertions = (
        "assert: admin_registered_in_browser=true",
        "assert: credential_created=true",
        "assert: credential_copied_and_clipboard_cleared=true",
        "assert: credential_dismissed=true",
        "assert: credential_rotated=true",
        "assert: pg_node_b_scrape=true",
        "assert: old_credential_invalidated_on_both_nodes=true",
        "assert: credential_revoked=true",
        "assert: page_errors=0",
        "assert: request_failures=0",
        "assert: relay_requests=0",
        "assert: browser_cleanup_complete=true",
        "assert: web_release_sha256=",
    )
    missing_assertions = [item for item in required_assertions if item not in result.stdout]
    _require(
        not missing_assertions,
        "PostgreSQL metrics browser assertions were incomplete; "
        f"missing={','.join(missing_assertions)}; redacted output: {output}",
    )

    database = pg_http_world.database_connection
    admin_user = database.execute(
        "SELECT user_id FROM users WHERE username=%s",
        (PG_WEB_METRICS_USERNAME,),
    ).fetchone()
    _require(admin_user is not None, "Web metrics acceptance did not register its PG administrator")
    credential_rows = database.execute(
        "SELECT COUNT(*) FROM instance_metrics_credential WHERE credential_id=1"
    ).fetchone()[0]
    audit_rows = database.execute(
        "SELECT action,actor_user_id,actor_device_id,resource_type,resource_id,source,result "
        "FROM audit_events WHERE scope_type='instance' AND actor_user_id=%s "
        "AND action IN ('admin.metrics_credential_rotated','admin.metrics_credential_revoked') "
        "ORDER BY event_id",
        (admin_user[0],),
    ).fetchall()
    _require(
        credential_rows == 0
        and len(audit_rows) == 3
        and [row[0] for row in audit_rows]
        == [
            "admin.metrics_credential_rotated",
            "admin.metrics_credential_rotated",
            "admin.metrics_credential_revoked",
        ]
        and all(
            row[1] == admin_user[0]
            and row[2] is not None
            and row[3] == "metrics_credential"
            and row[4] is None
            and row[5] == "api"
            and row[6] == "success"
            for row in audit_rows
        ),
        "Web lifecycle must leave no active verifier and exactly three private actor-attributed PG audits",
    )
    pg_http_world.assert_secrets_not_in_local_files()
